var style_default = "@import \"./tokens.css\";\r\n\r\n/*\r\n * hermes-console · 外壳 + 设计系统样式\r\n *\r\n * 颜色规则（构建脚本强制检查，出现字面色值即构建失败）：\r\n *   - 只允许 var(--ui-text-primary|secondary|quaternary)、var(--ui-stroke-secondary)、\r\n *     var(--ui-accent)、var(--ui-bg-*)；\r\n *   - 每个变量都带 inherit 兜底：宿主没定义该变量时退化成本色文字，不会变成透明块；\r\n *   - 深浅主题由宿主改写 `--ui-*` 完成，本文件没有任何 data-theme 分支；\r\n *   - 卡片只用 1px stroke 立起来，无阴影；hover 只提亮 stroke / 背景一档。\r\n *\r\n * 布局：左栏（.hc-rail）固定宽度不滚动，右列（.hc-main）= 顶栏 + 内容区。\r\n * 内容区里当前分区是一个绝对定位的滚动面板（.hc-pane）；切分区时旧面板**卸载**，\r\n * 只剩当前那一个（DOM 不再随访问过的分区数单调增长）。\r\n */\r\n\r\n.hc-root {\r\n  /* 窄窗判定用容器查询而不是 window 媒体查询：面板被拖窄时同样要收成图标条 */\r\n  container: hc / inline-size;\r\n  display: flex;\r\n  height: 100%;\r\n  min-height: 0;\r\n  box-sizing: border-box;\r\n  color: var(--ui-text-primary, inherit);\r\n  font-size: var(--fs-md);\r\n  line-height: 1.55;\r\n  text-align: left;\r\n}\r\n\r\n.hc-root *,\r\n.hc-root *::before,\r\n.hc-root *::after {\r\n  box-sizing: border-box;\r\n}\r\n\r\n/* 键盘可达：所有可点元素共用同一圈焦点环（鼠标点击不触发）。\r\n   不在这里设 border-radius：outline 会跟随元素自身的圆角，改它会抖一下。 */\r\n.hc-root :focus-visible {\r\n  outline: 2px solid var(--ui-accent, currentColor);\r\n  outline-offset: 1px;\r\n}\r\n\r\n/* ---------------------------------------------------------------- 左栏导航 */\r\n\r\n.hc-rail {\r\n  flex: 0 0 var(--nav-w);\r\n  width: var(--nav-w);\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s1);\r\n  padding: var(--s3) var(--s2);\r\n  border-right: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  min-width: 0;\r\n  overflow: hidden;\r\n}\r\n\r\n.hc-rail__brand {\r\n  padding: var(--s1) var(--s2) var(--s3);\r\n  font-size: var(--fs-xs);\r\n  letter-spacing: 0.08em;\r\n  color: var(--ui-text-quaternary, inherit);\r\n  white-space: nowrap;\r\n}\r\n\r\n.hc-nav {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s1);\r\n  margin: 0;\r\n  padding: 0;\r\n  list-style: none;\r\n}\r\n\r\n.hc-nav__item {\r\n  position: relative;\r\n  display: flex;\r\n  align-items: center;\r\n  gap: var(--s2);\r\n  width: 100%;\r\n  min-height: var(--row-h);\r\n  padding: 0 var(--s2);\r\n  border: 0;\r\n  /* 选中态的第一重信号是左侧 --nav-mark 描边；未选中时透明占位，选中不跳版 */\r\n  border-left: var(--nav-mark) solid transparent;\r\n  border-radius: 0 var(--r-sm) var(--r-sm) 0;\r\n  background: none;\r\n  font: inherit;\r\n  font-size: var(--fs-md);\r\n  color: var(--ui-text-secondary, inherit);\r\n  cursor: pointer;\r\n  text-align: left;\r\n  transition: color var(--t-fast), background-color var(--t-fast), border-color var(--t-fast);\r\n}\r\n\r\n/* 未选中：只有 hover 才变（静止态一律 secondary + 无底色的弱化） */\r\n.hc-nav__item:hover {\r\n  color: var(--ui-text-primary, inherit);\r\n  background: var(--ui-bg-quaternary, transparent);\r\n}\r\n\r\n/* 选中：左描边 + 底色 + 文字提亮 + 字重，三重信号同时存在。\r\n   截图里三个分区是纯文本竖排，看不出哪个被选中 —— 根因是这一档只改了字色和一点点底色。 */\r\n.hc-nav__item--active {\r\n  border-left-color: var(--ui-accent, currentColor);\r\n  background: var(--ui-bg-tertiary, transparent);\r\n  color: var(--ui-text-primary, inherit);\r\n  font-weight: 600;\r\n}\r\n\r\n/* 选中项再补一条不透明内嵌标记：底色在浅色主题里太淡，这条始终看得见 */\r\n.hc-nav__item--active::before {\r\n  content: '';\r\n  position: absolute;\r\n  left: 0;\r\n  top: var(--s2);\r\n  bottom: var(--s2);\r\n  width: var(--nav-mark);\r\n  border-radius: var(--r-sm);\r\n  background: var(--ui-accent, currentColor);\r\n}\r\n\r\n.hc-nav__item--active:hover {\r\n  background: var(--ui-row-active-background, var(--ui-bg-tertiary, transparent));\r\n}\r\n\r\n.hc-nav__icon {\r\n  flex: 0 0 auto;\r\n  display: inline-flex;\r\n  align-items: center;\r\n  justify-content: center;\r\n  width: var(--s4);\r\n  height: var(--s4);\r\n  opacity: 0.9;\r\n}\r\n\r\n.hc-nav__item--active .hc-nav__icon {\r\n  opacity: 1;\r\n}\r\n\r\n.hc-nav__label {\r\n  min-width: 0;\r\n  overflow: hidden;\r\n  text-overflow: ellipsis;\r\n  white-space: nowrap;\r\n}\r\n\r\n/* 导航重取中（首屏 / 切作用域）的骨架条：占住导航的形状，不闪空白。\r\n   不写「加载中…」这种没信息量的字，也不把已渲染的项整片盖掉。 */\r\n.hc-nav--loading .hc-nav__item {\r\n  opacity: 0.7;\r\n}\r\n\r\n.hc-nav__skel {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s1);\r\n  padding: 0 var(--s2);\r\n}\r\n\r\n.hc-nav__skel-bar {\r\n  height: var(--s2);\r\n  border-radius: var(--r-sm);\r\n  background: var(--ui-bg-tertiary, transparent);\r\n  animation: hc-breathe 1.8s ease-in-out infinite;\r\n}\r\n\r\n/* 后端一个模块都没启用：导航真空，但必须说清为什么空（不是白板） */\r\n.hc-nav__empty {\r\n  padding: var(--s2);\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-quaternary, inherit);\r\n}\r\n\r\n/* 模块清单拉取失败的回退提示（可关闭）：明说已回退 + 后端原话 */\r\n.hc-notice {\r\n  display: flex;\r\n  align-items: flex-start;\r\n  gap: var(--s2);\r\n  padding: var(--s2);\r\n  border: var(--hairline) dashed var(--ui-warning, currentColor);\r\n  border-radius: var(--r-sm);\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-secondary, inherit);\r\n}\r\n\r\n.hc-notice__text {\r\n  flex: 1 1 auto;\r\n  min-width: 0;\r\n  word-break: break-word;\r\n}\r\n\r\n.hc-notice__close {\r\n  flex: 0 0 auto;\r\n  padding: 0;\r\n  border: 0;\r\n  background: none;\r\n  font: inherit;\r\n  color: var(--ui-text-quaternary, inherit);\r\n  cursor: pointer;\r\n}\r\n\r\n.hc-notice__close:hover {\r\n  color: var(--ui-text-primary, inherit);\r\n}\r\n\r\n/* -------------------------------------------------------------- 右列 / 顶栏 */\r\n\r\n.hc-main {\r\n  flex: 1 1 auto;\r\n  min-width: 0;\r\n  min-height: 0;\r\n  display: flex;\r\n  flex-direction: column;\r\n}\r\n\r\n.hc-topbar {\r\n  flex: 0 0 auto;\r\n  display: flex;\r\n  align-items: center;\r\n  flex-wrap: wrap;\r\n  gap: var(--s2) var(--s3);\r\n  min-height: var(--s8);\r\n  padding: var(--s2) var(--s4);\r\n  border-bottom: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n}\r\n\r\n.hc-topbar__title {\r\n  font-size: var(--fs-lg);\r\n  font-weight: 600;\r\n  letter-spacing: 0.01em;\r\n  white-space: nowrap;\r\n}\r\n\r\n.hc-topbar__right {\r\n  display: flex;\r\n  align-items: center;\r\n  flex-wrap: wrap;\r\n  gap: var(--s2);\r\n  margin-left: auto;\r\n  min-width: 0;\r\n}\r\n\r\n/* 作用域选择器 */\r\n.hc-scope {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: var(--s2);\r\n  min-width: 0;\r\n}\r\n\r\n/* 当前分区不吃作用域（ignoresScope）时整块让位：`hidden` 必须真的不占位，\r\n * 否则 flex 会把 [hidden] 又显示出来，页面里就又出现两个 agent 选择器了。 */\r\n.hc-scope[hidden],\r\n.hc-scope--na {\r\n  display: none !important;\r\n}\r\n\r\n.hc-scope__label {\r\n  font-size: var(--fs-sm);\r\n  color: var(--ui-text-quaternary, inherit);\r\n  white-space: nowrap;\r\n}\r\n\r\n.hc-select {\r\n  max-width: 220px;\r\n  min-width: 0;\r\n  padding: var(--s1) var(--s2);\r\n  border: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  border-radius: var(--r-sm);\r\n  background: var(--ui-bg-quaternary, transparent);\r\n  color: var(--ui-text-primary, inherit);\r\n  font: inherit;\r\n  font-size: var(--fs-sm);\r\n  cursor: pointer;\r\n  transition: border-color var(--t-fast), background-color var(--t-fast);\r\n}\r\n\r\n.hc-select:hover {\r\n  border-color: var(--ui-accent, currentColor);\r\n  background: var(--ui-bg-tertiary, transparent);\r\n}\r\n\r\n.hc-select:disabled {\r\n  cursor: not-allowed;\r\n  color: var(--ui-text-quaternary, inherit);\r\n}\r\n\r\n/* 作用域退化时的一行原因（不遮内容、不新建页面） */\r\n.hc-scope__reason {\r\n  flex: 1 1 100%;\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-quaternary, inherit);\r\n}\r\n\r\n.hc-scope__reason--warn {\r\n  color: var(--ui-text-secondary, inherit);\r\n}\r\n\r\n/* 按钮三档（全站唯一来源；分区不许再自定义第 4 种视觉）：\r\n *   主操作  .hc-btn--primary = 实心 accent 底 + 反白字（同一屏最多一个，放最想让用户点的那个）\r\n *   次操作  .hc-btn         = 描边（默认档，刷新/查询/切换这类都归这里）\r\n *   危险操作 .hc-btn--danger = 红字（见文件末尾那一档；不加实心底，避免和主操作抢注意力）\r\n * `.hc-btn--accent` 是历史别名，等价于 --primary（lib/states.js 的 ErrorState 重试用它）。 */\r\n.hc-btn {\r\n  display: inline-flex;\r\n  align-items: center;\r\n  gap: var(--s1);\r\n  padding: var(--s1) var(--s3);\r\n  border: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  border-radius: var(--r-sm);\r\n  background: none;\r\n  font: inherit;\r\n  font-size: var(--fs-sm);\r\n  color: var(--ui-text-secondary, inherit);\r\n  cursor: pointer;\r\n  white-space: nowrap;\r\n  transition: color var(--t-fast), border-color var(--t-fast), background-color var(--t-fast);\r\n}\r\n\r\n.hc-btn:hover {\r\n  color: var(--ui-text-primary, inherit);\r\n  border-color: var(--ui-accent, currentColor);\r\n  background: var(--ui-bg-quaternary, transparent);\r\n}\r\n\r\n/* 主操作：实心 accent。反白字用 --ui-bg-editor（浅色主题≈近白、深色主题≈近黑），\r\n   两个主题下都与 accent 拉开对比度，且不引入任何字面色值。 */\r\n.hc-btn--primary,\r\n.hc-btn--accent {\r\n  color: var(--ui-bg-editor, var(--ui-bg-chrome, inherit));\r\n  background: var(--ui-accent, transparent);\r\n  border-color: var(--ui-accent, currentColor);\r\n  font-weight: 600;\r\n}\r\n\r\n.hc-btn--primary:hover,\r\n.hc-btn--accent:hover {\r\n  color: var(--ui-bg-editor, var(--ui-bg-chrome, inherit));\r\n  background: var(--ui-accent, transparent);\r\n  border-color: var(--ui-accent, currentColor);\r\n  /* 实心底上不做加亮底（会丢对比度），用轻微降亮表示按下/悬停 */\r\n  opacity: 0.88;\r\n}\r\n\r\n/* 刷新完成后的 800ms 反馈（按钮文字同时变「已刷新」，不只靠颜色） */\r\n.hc-btn--done,\r\n.hc-btn--done:hover {\r\n  color: var(--ui-text-primary, inherit);\r\n  border-color: var(--ui-accent, currentColor);\r\n  background: var(--ui-bg-tertiary, transparent);\r\n}\r\n\r\n/* 连接状态：形状 + 文字双通道，不靠颜色单独表达 */\r\n.hc-conn {\r\n  display: inline-flex;\r\n  align-items: center;\r\n  gap: var(--s1);\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-quaternary, inherit);\r\n  white-space: nowrap;\r\n}\r\n\r\n.hc-conn__dot {\r\n  width: var(--s2);\r\n  height: var(--s2);\r\n  border-radius: 999px;\r\n  border: var(--hairline) solid var(--ui-text-quaternary, currentColor);\r\n}\r\n\r\n.hc-conn--ok .hc-conn__dot {\r\n  background: var(--ui-accent, currentColor);\r\n  border-color: var(--ui-accent, currentColor);\r\n}\r\n\r\n.hc-conn--ok .hc-conn__text {\r\n  color: var(--ui-text-secondary, inherit);\r\n}\r\n\r\n.hc-conn--error .hc-conn__dot {\r\n  background: none;\r\n  border-color: var(--ui-accent, currentColor);\r\n  border-width: var(--nav-mark);\r\n}\r\n\r\n.hc-conn--error .hc-conn__text {\r\n  color: var(--ui-text-primary, inherit);\r\n}\r\n\r\n.hc-conn--loading .hc-conn__dot {\r\n  opacity: 0.5;\r\n}\r\n\r\n/* ------------------------------------------------------------- 内容区面板 */\r\n\r\n.hc-content {\r\n  position: relative;\r\n  flex: 1 1 auto;\r\n  min-height: 240px;\r\n  min-width: 0;\r\n}\r\n\r\n.hc-pane {\r\n  position: absolute;\r\n  inset: 0;\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s3);\r\n  /* 只纵向滚：面板被拖窄时不允许整页横向滚动（横向滚动只发生在组件内部的\r\n     专门容器里，比如逐小时天气条）。 */\r\n  overflow-x: hidden;\r\n  overflow-y: auto;\r\n  padding: var(--s4);\r\n}\r\n\r\n/* 历史：分区面板曾是「挂载后一直挂着、只切 visibility」，这档样式给非激活面板用。\r\n   现在切分区即卸载（见 src/shell.js），没有任何地方再挂这个 class —— 保留是为了\r\n   不删仍有外部引用的公共 CSS（删前要 grep 全仓确认零引用；本次未确认，故不动）。 */\r\n.hc-pane--idle {\r\n  visibility: hidden;\r\n  pointer-events: none;\r\n}\r\n\r\n.hc-pane__head {\r\n  display: flex;\r\n  align-items: baseline;\r\n  flex-wrap: wrap;\r\n  gap: var(--s2);\r\n}\r\n\r\n.hc-pane__title {\r\n  font-size: var(--fs-md);\r\n  font-weight: 600;\r\n}\r\n\r\n/* 状态徽标。**三档字号的第二档（12px）+ 次级前景**，不是 11px + 36% 透明：\r\n   实测 11px + --ui-text-quaternary（= 前景 36% alpha）在浅色底上只有 2.06~2.17:1，\r\n   远低于 WCAG AA 4.5:1，看板挂件右上角「有数据 / 空态 / 读取中」几乎看不清。\r\n   现在：font-size 12px（--fs-sm），前景用 --ui-text-secondary（74% alpha），\r\n   浅/深两套主题下都重算过对比度（见交接里的数值）。\r\n   形状仍与按钮区分：徽标无底色、胶囊圆角、不可点（不挂 pointer）。 */\r\n.hc-chip {\r\n  display: inline-flex;\r\n  align-items: center;\r\n  gap: var(--s1);\r\n  padding: 0 var(--s2);\r\n  border: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  border-radius: 999px;\r\n  font-size: var(--fs-sm);\r\n  line-height: 1.5;\r\n  color: var(--ui-text-secondary, inherit);\r\n  white-space: nowrap;\r\n}\r\n\r\n.hc-muted {\r\n  font-size: var(--fs-sm);\r\n  color: var(--ui-text-quaternary, inherit);\r\n}\r\n\r\n/* ------------------------------------------------------- 三态：骨架屏 */\r\n\r\n.hc-skel {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s2);\r\n  width: 100%;\r\n}\r\n\r\n.hc-skel__line {\r\n  height: var(--s3);\r\n  border-radius: var(--r-sm);\r\n  background: var(--ui-bg-tertiary, transparent);\r\n  animation: hc-breathe 1.8s ease-in-out infinite;\r\n}\r\n\r\n.hc-skel__card {\r\n  height: var(--s8);\r\n  border-radius: var(--r-md);\r\n  background: var(--ui-bg-quaternary, transparent);\r\n}\r\n\r\n/* 统计卡里的骨架屏：占住「标签 / 大数字 / 两行小字」的形状，不写「读取中」三个字。\r\n   analytics 实测 2.4–4.2s，这段时间用户该看到的是「马上就要有数字」而不是一句文案。 */\r\n.hc-skel-card {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s2);\r\n  min-width: 0;\r\n  padding: var(--s4);\r\n  border: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  border-radius: var(--r-md);\r\n  background: var(--ui-bg-secondary, transparent);\r\n}\r\n\r\n.hc-skel-card__bar {\r\n  border-radius: var(--r-sm);\r\n  background: var(--ui-bg-quaternary, transparent);\r\n  animation: hc-breathe 1.8s ease-in-out infinite;\r\n}\r\n\r\n.hc-skel-card__bar--label {\r\n  width: 42%;\r\n  height: var(--s2);\r\n}\r\n\r\n.hc-skel-card__bar--value {\r\n  width: 58%;\r\n  height: var(--s6);\r\n  margin: var(--s1) 0;\r\n}\r\n\r\n.hc-skel-card__bar--sub {\r\n  width: 88%;\r\n  height: var(--s2);\r\n}\r\n\r\n.hc-skel-card__bar--caliber {\r\n  width: 68%;\r\n  height: var(--s2);\r\n}\r\n\r\n@keyframes hc-breathe {\r\n  0%,\r\n  100% {\r\n    opacity: 0.55;\r\n  }\r\n  50% {\r\n    opacity: 0.95;\r\n  }\r\n}\r\n\r\n/* ------------------------------------------------- 三态：空 / 错误 */\r\n\r\n.hc-state {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s2);\r\n  padding: var(--s4) var(--s5);\r\n  border: var(--hairline) dashed var(--ui-stroke-secondary, currentColor);\r\n  border-radius: var(--r-md);\r\n  max-width: 720px;\r\n}\r\n\r\n.hc-state__title {\r\n  font-size: var(--fs-md);\r\n  font-weight: 600;\r\n  color: var(--ui-text-primary, inherit);\r\n}\r\n\r\n.hc-state__hint {\r\n  font-size: var(--fs-sm);\r\n  color: var(--ui-text-quaternary, inherit);\r\n  white-space: pre-wrap;\r\n}\r\n\r\n.hc-state__actions {\r\n  display: flex;\r\n  flex-wrap: wrap;\r\n  gap: var(--s2);\r\n  padding-top: var(--s1);\r\n}\r\n\r\n.hc-state--error {\r\n  border-style: solid;\r\n  border-color: var(--ui-accent, currentColor);\r\n}\r\n\r\n.hc-state__code {\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-secondary, inherit);\r\n  white-space: pre-wrap;\r\n  word-break: break-word;\r\n}\r\n\r\n/* ------------------------------------------------- 概览分区（C3） */\r\n\r\n.hc-overview {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s4);\r\n  min-width: 0;\r\n}\r\n\r\n/* 统计卡：响应式栅格 —— ≥1200px 四列 / ≥900px 两列 / 更窄一列。\r\n   用容器查询而不是窗口媒体查询：面板被宿主编排拖窄时同样要降列。\r\n   卡间 --s4：四张卡是四条并列读数，间距要比卡内元素间距大一档才读得出「四个格子」。 */\r\n.hc-cards {\r\n  display: grid;\r\n  grid-template-columns: minmax(0, 1fr);\r\n  gap: var(--s4);\r\n}\r\n\r\n@container hc (min-width: 900px) {\r\n  .hc-cards {\r\n    grid-template-columns: repeat(2, minmax(0, 1fr));\r\n  }\r\n}\r\n\r\n@container hc (min-width: 1200px) {\r\n  .hc-cards {\r\n    grid-template-columns: repeat(4, minmax(0, 1fr));\r\n  }\r\n}\r\n\r\n.hc-card {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s2);\r\n  min-width: 0;\r\n  padding: var(--s4);\r\n  border: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  border-radius: var(--r-md);\r\n  background: var(--ui-bg-secondary, transparent);\r\n}\r\n\r\n/* 降级/异常：虚线框 + 警示色；形状与颜色双通道，不只靠颜色 */\r\n.hc-card--warn,\r\n.hc-card--error {\r\n  border-style: dashed;\r\n  border-color: var(--ui-warning, var(--ui-orange, currentColor));\r\n}\r\n\r\n.hc-card__label {\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-quaternary, inherit);\r\n  letter-spacing: 0.02em;\r\n}\r\n\r\n/* 数字层级：一行三档 —— 主数值(--fs-xl/primary) · 单位(--fs-sm/quaternary) · 口径(--fs-xs/弱色)。\r\n   旧版把「88%内存」「已用 26.9 GB / 共 31.8 GB · CPU 37%…」全塞进一行同字号，\r\n   读数、单位、口径分不出来，才会被读成「一堆裸文本」。 */\r\n.hc-card__value {\r\n  display: flex;\r\n  align-items: baseline;\r\n  flex-wrap: wrap;\r\n  gap: var(--s1);\r\n  min-width: 0;\r\n}\r\n\r\n.hc-card__num {\r\n  font-size: var(--fs-xl);\r\n  font-weight: 600;\r\n  line-height: 1.2;\r\n  font-variant-numeric: tabular-nums;\r\n  color: var(--ui-text-primary, inherit);\r\n}\r\n\r\n.hc-card__unit {\r\n  font-size: var(--fs-sm);\r\n  line-height: 1.2;\r\n  color: var(--ui-text-quaternary, inherit);\r\n  white-space: nowrap;\r\n}\r\n\r\n/* 精确值/构成（已用 26.9 GB / 共 31.8 GB …）：次要但可读 */\r\n.hc-card__sub {\r\n  font-size: var(--fs-sm);\r\n  color: var(--ui-text-secondary, inherit);\r\n  overflow-wrap: anywhere;\r\n}\r\n\r\n/* 口径说明：最弱一档，**吸底**（margin-top:auto）。\r\n   旧版跟着正文自然流排：4 张统计卡里正文行数不同的那两张，「口径：」浮在卡片中上部，\r\n   与相邻卡不在同一基线（实测截图里一眼就看得出来）。卡是 flex column + 栅格拉伸，\r\n   给这一行 auto 上边距即可让四张卡的底部说明齐平。 */\r\n.hc-card__caliber {\r\n  margin-top: auto;\r\n  font-size: var(--fs-xs);\r\n  line-height: 1.45;\r\n  color: var(--ui-text-quaternary, inherit);\r\n  overflow-wrap: anywhere;\r\n}\r\n\r\n/* 区块：标题一行 + 内容 */\r\n.hc-block {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s2);\r\n  min-width: 0;\r\n}\r\n\r\n.hc-block__head {\r\n  display: flex;\r\n  align-items: baseline;\r\n  flex-wrap: wrap;\r\n  gap: var(--s2);\r\n}\r\n\r\n.hc-block__title {\r\n  font-size: var(--fs-md);\r\n  font-weight: 600;\r\n  color: var(--ui-text-primary, inherit);\r\n}\r\n\r\n/* 只读列表：容器自己滚，行高固定，长列表不把整页顶开 */\r\n.hc-rows {\r\n  display: flex;\r\n  flex-direction: column;\r\n  max-height: 264px;\r\n  overflow-y: auto;\r\n  border: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  border-radius: var(--r-md);\r\n}\r\n\r\n/* 表头：与数据行共用同一份列定义（--row-cols），列才不会各说各话。\r\n   旧版每行是 `1fr auto auto auto`，auto 列宽随内容变化，四行四套对齐 —— 肉眼看到的是\r\n   「oai.sb 额度监控下次 10-28 15:00启用default」这种粘连文本。 */\r\n.hc-rows__head {\r\n  position: sticky;\r\n  top: 0;\r\n  z-index: 1;\r\n  display: grid;\r\n  grid-template-columns: var(--row-cols);\r\n  align-items: center;\r\n  gap: var(--s2);\r\n  min-height: var(--s7);\r\n  padding: 0 var(--s3);\r\n  border-bottom: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  background: var(--ui-bg-secondary, transparent);\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-quaternary, inherit);\r\n  letter-spacing: 0.02em;\r\n}\r\n\r\n/* 一行的**外观**（高、内距、字号、垂直居中）。**故意不含列定义**：\r\n   `.hc-row` 在 `src/` 里不止被表格用 —— `models.js` 的「整块内容塞一行」（1 个子元素、\r\n   自己用内联 `flex-direction: column`）和 `overview.js` 的三列自检行也在用它。基类写死\r\n   四列会把这两种消费者挤进第 1 列、其余列留空。列定义一律下放到具体容器：\r\n     * 表格行：`.hc-rows .hc-row`（默认比列、`--row-cols` 覆盖、窄档 3 列）；\r\n     * 整块堆叠行：`.hc-rows--stack .hc-row`；\r\n     * 自检行：`.hc-rows--selfcheck .hc-row`。\r\n   新增使用 `.hc-row` 的地方，如果不在 `.hc-rows` 容器里，必须显式换成上面某一个或补专用类。 */\r\n.hc-row {\r\n  align-items: center;\r\n  gap: var(--s2);\r\n  min-height: var(--row-h);\r\n  padding: 0 var(--s3);\r\n  font-size: var(--fs-sm);\r\n}\r\n\r\n/* 只有**真正在列表容器里**的行才吃列定义（表头 `.hc-rows__head` 的 `--row-cols` 同源）。 */\r\n.hc-rows .hc-row {\r\n  display: grid;\r\n  grid-template-columns: minmax(0, 1fr) auto auto auto;\r\n}\r\n\r\n/* 定时任务：列 = 任务名 / 下次执行 / 状态 / 作用域。定宽列（不是 auto），\r\n   四行上下严格对齐；数字列用等宽数字，时间戳不会左右抖。 */\r\n.hc-rows--cron {\r\n  --row-cols: minmax(0, 1fr) 132px 76px 100px;\r\n}\r\n\r\n.hc-rows--cron .hc-row {\r\n  grid-template-columns: var(--row-cols);\r\n}\r\n\r\n/* 自检行（overview.js「分区自检」）：三列 —— 子路由 / 状态 / 宿主接口（或失败原因）。 */\r\n.hc-rows--selfcheck {\r\n  --row-cols: minmax(0, 96px) 88px minmax(0, 1fr);\r\n}\r\n\r\n.hc-rows--selfcheck .hc-row,\r\n.hc-rows--selfcheck .hc-rows__head {\r\n  grid-template-columns: var(--row-cols);\r\n}\r\n\r\n/* 整块堆叠行（models.js 的「写入结果 / 回滚结果 / 批次账本 / 预览」）：一行是**一整块内容**\r\n   （标题 + 若干行说明），不是表格的一行。这里把每一行摆成纵向 flex，子元素自己决定排布；\r\n   绝不能落到 `.hc-rows .hc-row` 的 4 列网格上（那会把整块塞进第 1 列）。 */\r\n.hc-rows--stack .hc-row {\r\n  display: flex;\r\n  flex-direction: column;\r\n  align-items: stretch;\r\n  gap: var(--s1);\r\n  padding: var(--s2) var(--s3);\r\n}\r\n\r\n.hc-row + .hc-row {\r\n  border-top: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n}\r\n\r\n.hc-row:hover {\r\n  background: var(--ui-row-hover-background, var(--ui-bg-tertiary, transparent));\r\n}\r\n\r\n.hc-row__name {\r\n  overflow: hidden;\r\n  text-overflow: ellipsis;\r\n  white-space: nowrap;\r\n  color: var(--ui-text-primary, inherit);\r\n}\r\n\r\n.hc-row__meta {\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-quaternary, inherit);\r\n  white-space: nowrap;\r\n}\r\n\r\n.hc-row__meta--tail {\r\n  min-width: 4ch;\r\n  text-align: right;\r\n}\r\n\r\n/* 下次执行时间：等宽数字 + 次要色（时间是要比对的，不能和任务名同权重） */\r\n.hc-row__next {\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-secondary, inherit);\r\n  font-variant-numeric: tabular-nums;\r\n  white-space: nowrap;\r\n}\r\n\r\n/* 状态色纪律：正常 secondary / 异常危险 warning / 禁用 quaternary。\r\n   形状同时变化（左圆点），色弱与色盲也能分辨，不靠颜色单独表达。 */\r\n.hc-status {\r\n  display: inline-flex;\r\n  align-items: center;\r\n  gap: var(--s1);\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-secondary, inherit);\r\n  white-space: nowrap;\r\n}\r\n\r\n.hc-status::before {\r\n  content: '';\r\n  width: var(--s2);\r\n  height: var(--s2);\r\n  flex: 0 0 auto;\r\n  border-radius: 999px;\r\n  border: var(--hairline) solid currentColor;\r\n  background: none;\r\n}\r\n\r\n.hc-status--ok::before {\r\n  background: currentColor;\r\n}\r\n\r\n.hc-status--warn {\r\n  color: var(--ui-warning, var(--ui-orange, currentColor));\r\n}\r\n\r\n/* 异常：实心 + 双倍描边，与正常态一眼分开 */\r\n.hc-status--warn::before {\r\n  background: currentColor;\r\n  border-width: var(--nav-mark);\r\n}\r\n\r\n.hc-status--off {\r\n  color: var(--ui-text-quaternary, inherit);\r\n}\r\n\r\n.hc-status--off::before {\r\n  border-style: dashed;\r\n}\r\n\r\n/* 作用域列（agent 名）：弱色，窄窗整列隐藏 */\r\n.hc-row__scope {\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-quaternary, inherit);\r\n  overflow: hidden;\r\n  text-overflow: ellipsis;\r\n  white-space: nowrap;\r\n  text-align: right;\r\n}\r\n\r\n/* 停用/暂停的胶囊：虚线框 + 去掉强调，形状与文字双通道 */\r\n.hc-chip--off {\r\n  border-style: dashed;\r\n  color: var(--ui-text-quaternary, inherit);\r\n}\r\n\r\n.hc-sessions {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s2);\r\n}\r\n\r\n.hc-pager {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: var(--s2);\r\n  flex-wrap: wrap;\r\n}\r\n\r\n.hc-btn:disabled {\r\n  opacity: 0.5;\r\n  cursor: default;\r\n}\r\n\r\n/* 看板挂件：13 张「有真数据 / 明确空态 / 明确占位」的卡。\r\n   旧版每格只有「挂件名 + 出现次数」，而这份布局里每个挂件只出现 1 次 —— 13 张卡全是\r\n   「1 个」，等于没有信息。现在每张卡要有数值/原因，所以栅格从 132px 放宽到 240px：\r\n   132px 装不下「在线 · pid 1234 · 平台 1 个」这类构成行。 */\r\n.hc-widgets {\r\n  display: grid;\r\n  /* min(240px, 100%)：极窄窗（面板被拖到 240px 以下）也不会顶出横向滚动条 */\r\n  grid-template-columns: repeat(auto-fill, minmax(min(240px, 100%), 1fr));\r\n  gap: var(--s3);\r\n}\r\n\r\n.hc-widget {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s1);\r\n  min-width: 0;\r\n  padding: var(--s3) var(--s4);\r\n  border: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  border-radius: var(--r-md);\r\n  background: var(--ui-bg-secondary, transparent);\r\n  overflow: hidden;\r\n}\r\n\r\n/* 空态/占位：虚线框 —— 形状与颜色双通道，不只靠颜色区分「这格没有数字」。 */\r\n.hc-widget--empty,\r\n.hc-widget--placeholder {\r\n  border-style: dashed;\r\n}\r\n\r\n/* 取数失败：警示色虚线（与统计卡的降级样式同一套语义）。 */\r\n.hc-widget--error {\r\n  border-style: dashed;\r\n  border-color: var(--ui-warning, var(--ui-orange, currentColor));\r\n}\r\n\r\n.hc-widget__head {\r\n  display: flex;\r\n  align-items: baseline;\r\n  gap: var(--s2);\r\n  min-width: 0;\r\n}\r\n\r\n.hc-widget__label {\r\n  font-size: var(--fs-sm);\r\n  color: var(--ui-text-secondary, inherit);\r\n  overflow: hidden;\r\n  text-overflow: ellipsis;\r\n  white-space: nowrap;\r\n}\r\n\r\n/* 英文 id 降级成角标：它是布局里的键，不是给人读的标题 */\r\n.hc-widget__id {\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-quaternary, inherit);\r\n  white-space: nowrap;\r\n}\r\n\r\n.hc-widget__badge {\r\n  margin-left: auto;\r\n  font-size: var(--fs-xs);\r\n  line-height: 1.2;\r\n  padding: 0 var(--s1);\r\n  border: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  border-radius: var(--r-sm);\r\n  color: var(--ui-text-quaternary, inherit);\r\n  white-space: nowrap;\r\n}\r\n\r\n.hc-widget__body {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s1);\r\n  min-width: 0;\r\n}\r\n\r\n.hc-widget__value {\r\n  display: flex;\r\n  align-items: baseline;\r\n  gap: var(--s1);\r\n  min-width: 0;\r\n  flex-wrap: wrap;\r\n}\r\n\r\n.hc-widget__num {\r\n  font-size: var(--fs-xl);\r\n  font-weight: 600;\r\n  line-height: 1.2;\r\n  font-variant-numeric: tabular-nums;\r\n  color: var(--ui-text-primary, inherit);\r\n}\r\n\r\n.hc-widget__unit {\r\n  font-size: var(--fs-sm);\r\n  color: var(--ui-text-quaternary, inherit);\r\n  white-space: nowrap;\r\n}\r\n\r\n.hc-widget__meta {\r\n  font-size: var(--fs-sm);\r\n  color: var(--ui-text-secondary, inherit);\r\n  overflow-wrap: anywhere;\r\n}\r\n\r\n/* 空态/占位的说明：多行（带 \\n），所以 pre-wrap —— 「为什么空 + 在哪能填」不能被折成一坨 */\r\n.hc-widget__hint {\r\n  font-size: var(--fs-sm);\r\n  line-height: 1.5;\r\n  color: var(--ui-text-tertiary, var(--ui-text-secondary, inherit));\r\n  white-space: pre-wrap;\r\n  overflow-wrap: anywhere;\r\n}\r\n\r\n.hc-widget__loading {\r\n  font-size: var(--fs-sm);\r\n  color: var(--ui-text-quaternary, inherit);\r\n}\r\n\r\n/* 口径：最弱一档，永远在卡片底部（与统计卡的 .hc-card__caliber 同一层级语义） */\r\n.hc-widget__caliber {\r\n  margin-top: auto;\r\n  font-size: var(--fs-xs);\r\n  line-height: 1.45;\r\n  color: var(--ui-text-quaternary, inherit);\r\n  overflow-wrap: anywhere;\r\n}\r\n\r\n/* 挂件脚注（位置 gx,gy）：**换行不截断**。\r\n   旧版 white-space:nowrap + text-overflow:ellipsis：窄格里「位置 8,3 4×4」被吃掉一半，\r\n   第二排几张卡看起来像「没有位置」。脚注短，直接允许换行即可读全。 */\r\n.hc-widget__foot {\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-quaternary, inherit);\r\n  white-space: normal;\r\n  overflow-wrap: anywhere;\r\n}\r\n\r\n/* 旧的 12 列预览容器保留给「布局位置」这类需要真实摆位的场景，\r\n   但挂件清单本身走上面的 .hc-widgets 卡片栅格。 */\r\n.hc-layout {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s2);\r\n  min-width: 0;\r\n}\r\n\r\n/* ------------------------------------------------------------ 窄窗图标条 */\r\n\r\n/* <900px：统计卡两列、列表隐藏「作用域」列、面板不横向滚动 */\r\n@container hc (max-width: 899px) {\r\n  .hc-rail {\r\n    flex-basis: var(--nav-w-narrow);\r\n    width: var(--nav-w-narrow);\r\n    padding: var(--s3) var(--s1);\r\n    align-items: stretch;\r\n  }\r\n\r\n  .hc-rail__brand,\r\n  .hc-nav__label,\r\n  .hc-scope__label {\r\n    display: none;\r\n  }\r\n\r\n  .hc-nav__item {\r\n    justify-content: center;\r\n    padding: 0;\r\n    gap: 0;\r\n  }\r\n\r\n  .hc-topbar {\r\n    padding: var(--s2) var(--s3);\r\n    gap: var(--s1) var(--s2);\r\n  }\r\n\r\n  .hc-topbar__title {\r\n    font-size: var(--fs-md);\r\n  }\r\n\r\n  .hc-select {\r\n    max-width: 40cqw;\r\n  }\r\n\r\n  .hc-conn__text {\r\n    display: none;\r\n  }\r\n\r\n  .hc-pane {\r\n    padding: var(--s3);\r\n  }\r\n\r\n  /* 概览：<900px 统计卡单列（基类即一列，这里不再覆盖，只留注释防止误改） */\r\n  /* 定时任务：收起「作用域」列（agent 名已在区块标题里），三列仍严格对齐 */\r\n  .hc-rows--cron {\r\n    --row-cols: minmax(0, 1fr) 116px 68px;\r\n  }\r\n\r\n  .hc-rows__head > :last-child,\r\n  .hc-row__scope {\r\n    display: none;\r\n  }\r\n\r\n  /* 窄档：表格行三列（作用域列已在上一条收起）。只作用于列表容器里的行 ——\r\n     基类 `.hc-row` 不再有列定义，堆叠/自检行也不会被这条误伤。 */\r\n  .hc-rows .hc-row {\r\n    grid-template-columns: minmax(0, 1fr) auto auto;\r\n  }\r\n\r\n  /* 定时任务仍用上面那套定宽三列（--row-cols）：通用三列只给没定义 --row-cols 的表。\r\n     两条选择器同权重，靠源码顺序让这条覆盖通用那条。 */\r\n  .hc-rows--cron .hc-row {\r\n    grid-template-columns: var(--row-cols);\r\n  }\r\n\r\n  /* 自检行同理：它本来就是三列（96px / 88px / 1fr），不能被通用三列改写成 auto auto。 */\r\n  .hc-rows--selfcheck .hc-row,\r\n  .hc-rows--selfcheck .hc-rows__head {\r\n    grid-template-columns: var(--row-cols);\r\n  }\r\n\r\n  /* 会话列表第 4 列（profile 名）同样收起：留着会折到第二行，行高就不整齐了。\r\n     会话的作用域本来就等于顶栏那个选择器，重复一遍只占宽度。 */\r\n  .hc-sessions .hc-row > :nth-child(4) {\r\n    display: none;\r\n  }\r\n}\r\n\r\n/* 更窄（被拖成半个面板）时统计卡单列堆叠，避免数字被挤成两行 */\r\n@container hc (max-width: 599px) {\r\n  .hc-rows--cron {\r\n    --row-cols: minmax(0, 1fr) 84px;\r\n  }\r\n\r\n  .hc-rows--cron .hc-row > :nth-child(3),\r\n  .hc-rows__head > :nth-child(3) {\r\n    display: none;\r\n  }\r\n}\r\n\r\n/* ===========================================================================\r\n * 天气分区（C4）\r\n *\r\n * 结构：.hc-wx 是分区根（纵向堆叠若干 .hc-wx-block），当前天气是 .hc-wx-now 卡。\r\n * 颜色全部走 var(--ui-*)，没有字面色值；卡片只用 1px stroke，无阴影。\r\n * =========================================================================== */\r\n\r\n.hc-wx {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s4);\r\n  min-width: 0;\r\n}\r\n\r\n/* ---- 当前天气卡 ---- */\r\n.hc-wx-now {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s4);\r\n  padding: var(--s4);\r\n  border: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  border-radius: var(--r-md);\r\n  background: var(--ui-bg-secondary, transparent);\r\n}\r\n\r\n.hc-wx-now__main {\r\n  display: flex;\r\n  align-items: flex-end;\r\n  gap: var(--s4);\r\n  min-width: 0;\r\n}\r\n\r\n.hc-wx-now__temp {\r\n  font-size: 40px;\r\n  line-height: 1;\r\n  font-weight: 600;\r\n  font-variant-numeric: tabular-nums;\r\n  color: var(--ui-text-primary, inherit);\r\n  white-space: nowrap;\r\n}\r\n\r\n.hc-wx-now__side {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 2px;\r\n  min-width: 0;\r\n  padding-bottom: 2px;\r\n}\r\n\r\n.hc-wx-now__desc {\r\n  font-size: var(--fs-lg);\r\n  color: var(--ui-text-primary, inherit);\r\n  overflow-wrap: anywhere;\r\n}\r\n\r\n.hc-wx-now__place {\r\n  font-size: var(--fs-sm);\r\n  color: var(--ui-text-quaternary, inherit);\r\n}\r\n\r\n/* 指标网格：窄窗自动降列（auto-fit，不需要媒体查询逐档写） */\r\n.hc-wx-metrics {\r\n  display: grid;\r\n  grid-template-columns: repeat(auto-fit, minmax(104px, 1fr));\r\n  gap: var(--s2);\r\n}\r\n\r\n.hc-wx-metric {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 2px;\r\n  padding: var(--s2) var(--s3);\r\n  border: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  border-radius: var(--r-sm);\r\n  min-width: 0;\r\n}\r\n\r\n.hc-wx-metric__label {\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-quaternary, inherit);\r\n}\r\n\r\n.hc-wx-metric__value {\r\n  font-size: var(--fs-lg);\r\n  font-variant-numeric: tabular-nums;\r\n  color: var(--ui-text-primary, inherit);\r\n  overflow-wrap: anywhere;\r\n}\r\n\r\n.hc-wx-metric__hint {\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-secondary, inherit);\r\n  overflow-wrap: anywhere;\r\n}\r\n\r\n/* ---- 附注（未来 2 小时降水 / 预警 / 未取到的项） ---- */\r\n.hc-wx-notes {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s1);\r\n}\r\n\r\n.hc-wx-note {\r\n  display: flex;\r\n  gap: var(--s2);\r\n  font-size: var(--fs-sm);\r\n  color: var(--ui-text-secondary, inherit);\r\n}\r\n\r\n.hc-wx-note__label {\r\n  flex: 0 0 auto;\r\n  color: var(--ui-text-quaternary, inherit);\r\n}\r\n\r\n.hc-wx-note__text {\r\n  flex: 1 1 auto;\r\n  min-width: 0;\r\n  overflow-wrap: anywhere;\r\n}\r\n\r\n.hc-wx-note--warn .hc-wx-note__label {\r\n  color: var(--ui-accent, currentColor);\r\n}\r\n\r\n.hc-wx-note--muted {\r\n  color: var(--ui-text-quaternary, inherit);\r\n}\r\n\r\n/* ---- 来源 + 更新时间 ---- */\r\n.hc-wx-stamp {\r\n  display: flex;\r\n  flex-wrap: wrap;\r\n  gap: var(--s1) var(--s3);\r\n  padding-top: var(--s2);\r\n  border-top: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-quaternary, inherit);\r\n}\r\n\r\n.hc-wx-stamp__src {\r\n  color: var(--ui-text-secondary, inherit);\r\n}\r\n\r\n.hc-wx-stamp__tried {\r\n  font-variant-numeric: tabular-nums;\r\n}\r\n\r\n/* ---- 通用区块 ---- */\r\n.hc-wx-block {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s2);\r\n  min-width: 0;\r\n}\r\n\r\n.hc-wx-block__head {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: var(--s2);\r\n  flex-wrap: wrap;\r\n}\r\n\r\n.hc-wx-block__title {\r\n  margin: 0;\r\n  font-size: var(--fs-md);\r\n  font-weight: 600;\r\n  color: var(--ui-text-primary, inherit);\r\n}\r\n\r\n/* ---- 逐小时：换行铺满（见上）---- */\r\n/* 逐小时条：24 格**换行**铺满，不再横向滚动。\r\n   实测旧行为：24×64px + 23×8px gap = 1736px 宽，1280 档可见区只有 1068px，\r\n   必须横向拖才看得到当天后半段（900 档只能看到约 1/3 天）。改成 flex-wrap 后\r\n   1280/1350 一屏两行、900 一屏三行，都不需要横向滚动。 */\r\n.hc-wx-hours {\r\n  display: flex;\r\n  flex-wrap: wrap;\r\n  gap: var(--s2);\r\n  border: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  border-radius: var(--r-md);\r\n  padding: var(--s2);\r\n}\r\n\r\n.hc-wx-hour {\r\n  flex: 0 0 auto;\r\n  width: 64px;\r\n  display: flex;\r\n  flex-direction: column;\r\n  align-items: center;\r\n  gap: 2px;\r\n  padding: var(--s1) 2px;\r\n  border-radius: var(--r-sm);\r\n  transition: background-color var(--t-fast);\r\n}\r\n\r\n.hc-wx-hour:hover {\r\n  background: var(--ui-bg-tertiary, transparent);\r\n}\r\n\r\n.hc-wx-hour__time {\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-quaternary, inherit);\r\n  font-variant-numeric: tabular-nums;\r\n}\r\n\r\n.hc-wx-hour__temp {\r\n  font-size: var(--fs-md);\r\n  color: var(--ui-text-primary, inherit);\r\n  font-variant-numeric: tabular-nums;\r\n}\r\n\r\n.hc-wx-hour__desc {\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-secondary, inherit);\r\n  text-align: center;\r\n  overflow-wrap: anywhere;\r\n}\r\n\r\n.hc-wx-hour__pop {\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-secondary, inherit);\r\n  font-variant-numeric: tabular-nums;\r\n}\r\n\r\n.hc-wx-hour__pop--none {\r\n  color: var(--ui-text-quaternary, inherit);\r\n}\r\n\r\n/* ---- 多日：一行一天 ---- */\r\n.hc-wx-days {\r\n  display: flex;\r\n  flex-direction: column;\r\n  border: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  border-radius: var(--r-md);\r\n  overflow: hidden;\r\n}\r\n\r\n.hc-wx-day {\r\n  display: grid;\r\n  grid-template-columns: 88px minmax(0, 1fr) 116px 56px;\r\n  align-items: center;\r\n  gap: var(--s2);\r\n  min-height: var(--row-h);\r\n  padding: 0 var(--s3);\r\n  font-size: var(--fs-sm);\r\n}\r\n\r\n.hc-wx-day + .hc-wx-day {\r\n  border-top: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n}\r\n\r\n.hc-wx-day:hover {\r\n  background: var(--ui-bg-tertiary, transparent);\r\n}\r\n\r\n.hc-wx-day__date {\r\n  color: var(--ui-text-secondary, inherit);\r\n  font-variant-numeric: tabular-nums;\r\n  white-space: nowrap;\r\n}\r\n\r\n.hc-wx-day__wd {\r\n  color: var(--ui-text-quaternary, inherit);\r\n  margin-left: var(--s1);\r\n}\r\n\r\n.hc-wx-day__desc {\r\n  color: var(--ui-text-primary, inherit);\r\n  overflow-wrap: anywhere;\r\n}\r\n\r\n.hc-wx-day__range {\r\n  text-align: right;\r\n  color: var(--ui-text-primary, inherit);\r\n  font-variant-numeric: tabular-nums;\r\n  white-space: nowrap;\r\n}\r\n\r\n.hc-wx-day__pop {\r\n  text-align: right;\r\n  color: var(--ui-text-secondary, inherit);\r\n  font-variant-numeric: tabular-nums;\r\n}\r\n\r\n/* ---- 工具栏（城市输入 / N 小时后） ---- */\r\n.hc-wx-toolbar {\r\n  display: flex;\r\n  flex-wrap: wrap;\r\n  align-items: center;\r\n  gap: var(--s2);\r\n}\r\n\r\n.hc-wx-toolbar__label {\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-quaternary, inherit);\r\n}\r\n\r\n.hc-wx-input {\r\n  min-width: 160px;\r\n  max-width: 220px;\r\n  padding: var(--s1) var(--s2);\r\n  border: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  border-radius: var(--r-sm);\r\n  background: var(--ui-bg-quaternary, transparent);\r\n  color: var(--ui-text-primary, inherit);\r\n  font: inherit;\r\n  font-size: var(--fs-sm);\r\n  transition: border-color var(--t-fast), background-color var(--t-fast);\r\n}\r\n\r\n.hc-wx-input:hover {\r\n  border-color: var(--ui-accent, currentColor);\r\n  background: var(--ui-bg-tertiary, transparent);\r\n}\r\n\r\n.hc-wx-input:focus-visible {\r\n  border-color: var(--ui-accent, currentColor);\r\n}\r\n\r\n/* 分段选择（1/6/12/24/48 小时）：选中的用 accent 边框 + 实心底，不只靠颜色 */\r\n.hc-wx-seg {\r\n  display: flex;\r\n  gap: var(--s1);\r\n}\r\n\r\n.hc-wx-seg__item {\r\n  padding: var(--s1) var(--s2);\r\n  border: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  border-radius: var(--r-sm);\r\n  background: none;\r\n  color: var(--ui-text-secondary, inherit);\r\n  font: inherit;\r\n  font-size: var(--fs-sm);\r\n  cursor: pointer;\r\n  font-variant-numeric: tabular-nums;\r\n  transition: color var(--t-fast), border-color var(--t-fast), background-color var(--t-fast);\r\n}\r\n\r\n.hc-wx-seg__item:hover {\r\n  color: var(--ui-text-primary, inherit);\r\n  border-color: var(--ui-accent, currentColor);\r\n}\r\n\r\n.hc-wx-seg__item--on {\r\n  color: var(--ui-text-primary, inherit);\r\n  border-color: var(--ui-accent, currentColor);\r\n  background: var(--ui-bg-tertiary, transparent);\r\n}\r\n\r\n/* ---- 「N 小时后」内联结果 ---- */\r\n.hc-wx-at {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s2);\r\n  padding: var(--s3);\r\n  border: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  border-radius: var(--r-md);\r\n  background: var(--ui-bg-secondary, transparent);\r\n}\r\n\r\n.hc-wx-at__text {\r\n  font-size: var(--fs-md);\r\n  color: var(--ui-text-primary, inherit);\r\n  overflow-wrap: anywhere;\r\n}\r\n\r\n.hc-wx-at__stamp {\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-quaternary, inherit);\r\n}\r\n\r\n@container hc (max-width: 899px) {\r\n  /* 窄窗：逐日行去掉降水概率列（表格挤成两行更难看），当前卡温度缩小一档 */\r\n  .hc-wx-day {\r\n    grid-template-columns: 72px minmax(0, 1fr) 96px;\r\n  }\r\n\r\n  .hc-wx-day__pop {\r\n    display: none;\r\n  }\r\n\r\n  .hc-wx-now__temp {\r\n    font-size: 32px;\r\n  }\r\n\r\n  .hc-wx-input {\r\n    min-width: 120px;\r\n    max-width: 160px;\r\n  }\r\n}\r\n\r\n@container hc (max-width: 599px) {\r\n  .hc-wx-metrics {\r\n    grid-template-columns: repeat(2, minmax(0, 1fr));\r\n  }\r\n\r\n  .hc-wx-now__main {\r\n    align-items: flex-start;\r\n    flex-direction: column;\r\n    gap: var(--s2);\r\n  }\r\n}\r\n\r\n/* ===========================================================================\r\n * Agent 总览分区（C7）\r\n *\r\n * 结构：.hc-ag > (.hc-ag__bar 工具行 + .hc-ag__table 表 + .hc-ag__foot 口径行)\r\n * 表：表头与每行共用同一份列定义 --ag-cols（否则各列各说各话，肉眼看到的就是错位）。\r\n * 颜色全部走 var(--ui-*)，没有字面色值；只有 1px stroke，无阴影。\r\n * =========================================================================== */\r\n\r\n.hc-ag {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s3);\r\n  min-width: 0;\r\n}\r\n\r\n.hc-ag__bar {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: var(--s2);\r\n  flex-wrap: wrap;\r\n}\r\n\r\n.hc-ag__count {\r\n  font-size: var(--fs-sm);\r\n  font-weight: 600;\r\n  color: var(--ui-text-secondary, inherit);\r\n}\r\n\r\n.hc-ag__sort {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: var(--s2);\r\n  margin-left: auto;\r\n}\r\n\r\n.hc-ag__sort-label {\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-quaternary, inherit);\r\n}\r\n\r\n.hc-ag__table {\r\n  /* 列：状态 / 名称 / 模型 / 会话 / 最近活动 / 定时任务 / 插件 / 操作 */\r\n  --ag-cols: 76px minmax(0, 1fr) 148px 60px 92px 88px 48px 196px;\r\n\r\n  display: flex;\r\n  flex-direction: column;\r\n  border: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  border-radius: var(--r-md);\r\n  overflow: hidden;\r\n}\r\n\r\n.hc-ag__head {\r\n  display: grid;\r\n  grid-template-columns: var(--ag-cols);\r\n  align-items: center;\r\n  gap: var(--s2);\r\n  min-height: var(--row-h);\r\n  padding: 0 var(--s3);\r\n  border-bottom: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  background: var(--ui-bg-secondary, transparent);\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-quaternary, inherit);\r\n  letter-spacing: 0.02em;\r\n}\r\n\r\n.hc-ag__item {\r\n  display: flex;\r\n  flex-direction: column;\r\n}\r\n\r\n.hc-ag__item + .hc-ag__item {\r\n  border-top: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n}\r\n\r\n.hc-ag__row {\r\n  display: grid;\r\n  grid-template-columns: var(--ag-cols);\r\n  align-items: center;\r\n  gap: var(--s2);\r\n  min-height: calc(var(--row-h) + var(--s1));\r\n  padding: 0 var(--s3);\r\n  font-size: var(--fs-sm);\r\n}\r\n\r\n.hc-ag__row:hover {\r\n  background: var(--ui-row-hover-background, var(--ui-bg-tertiary, transparent));\r\n}\r\n\r\n/* 失败行：左侧告警竖条（形状变化 + 下面那行原因，不靠颜色单独表达） */\r\n.hc-ag__row--bad {\r\n  border-left: var(--nav-mark) solid var(--ui-warning, var(--ui-orange, currentColor));\r\n  padding-left: calc(var(--s3) - var(--nav-mark));\r\n}\r\n\r\n.hc-ag__cell {\r\n  min-width: 0;\r\n  display: flex;\r\n  align-items: center;\r\n  gap: var(--s1);\r\n}\r\n\r\n.hc-ag__cell--status {\r\n  min-width: 0;\r\n}\r\n\r\n.hc-ag__status-text {\r\n  font-size: var(--fs-xs);\r\n  overflow: hidden;\r\n  text-overflow: ellipsis;\r\n  white-space: nowrap;\r\n}\r\n\r\n.hc-ag__cell--name {\r\n  flex-direction: column;\r\n  align-items: flex-start;\r\n  gap: 0;\r\n}\r\n\r\n.hc-ag__label {\r\n  max-width: 100%;\r\n  overflow: hidden;\r\n  text-overflow: ellipsis;\r\n  white-space: nowrap;\r\n  color: var(--ui-text-primary, inherit);\r\n}\r\n\r\n.hc-ag__id {\r\n  max-width: 100%;\r\n  overflow: hidden;\r\n  text-overflow: ellipsis;\r\n  white-space: nowrap;\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-quaternary, inherit);\r\n}\r\n\r\n.hc-ag__text {\r\n  overflow: hidden;\r\n  text-overflow: ellipsis;\r\n  white-space: nowrap;\r\n  color: var(--ui-text-secondary, inherit);\r\n}\r\n\r\n/* 数字列：等宽数字，几行的数上下对齐；取不到的用弱色 + 破折号 */\r\n.hc-ag__num {\r\n  font-variant-numeric: tabular-nums;\r\n  color: var(--ui-text-primary, inherit);\r\n}\r\n\r\n.hc-ag__num--none {\r\n  color: var(--ui-text-quaternary, inherit);\r\n}\r\n\r\n.hc-ag__cell--cron,\r\n.hc-ag__cell--sessions {\r\n  font-variant-numeric: tabular-nums;\r\n}\r\n\r\n.hc-ag__cell--ops {\r\n  justify-content: flex-end;\r\n  gap: var(--s1);\r\n  flex-wrap: wrap;\r\n}\r\n\r\n/* 行内小按钮：比 .hc-btn 再小一档，4 个才排得下 */\r\n.hc-btn--tiny {\r\n  min-height: 0;\r\n  padding: 1px var(--s2);\r\n  font-size: var(--fs-xs);\r\n  border-radius: var(--r-sm);\r\n}\r\n\r\n/* 失败行下面的原因 + 单独重试 */\r\n.hc-ag__reason {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: var(--s2);\r\n  flex-wrap: wrap;\r\n  padding: 0 var(--s3) var(--s2);\r\n}\r\n\r\n.hc-ag__reason-text {\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-warning, var(--ui-orange, currentColor));\r\n  overflow-wrap: anywhere;\r\n}\r\n\r\n/* 展开详情：两栏（会话 / 定时任务），窄窗自动堆成一栏 */\r\n.hc-ag__detail-wrap {\r\n  padding: 0 var(--s3) var(--s3);\r\n}\r\n\r\n.hc-ag__detail {\r\n  display: grid;\r\n  grid-template-columns: repeat(auto-fit, minmax(min(280px, 100%), 1fr));\r\n  gap: var(--s3);\r\n  padding: var(--s3);\r\n  border: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  border-radius: var(--r-md);\r\n  background: var(--ui-bg-secondary, transparent);\r\n}\r\n\r\n.hc-ag__detail-title {\r\n  font-size: var(--fs-xs);\r\n  font-weight: 600;\r\n  color: var(--ui-text-secondary, inherit);\r\n  margin-bottom: var(--s1);\r\n}\r\n\r\n.hc-ag__list {\r\n  display: flex;\r\n  flex-direction: column;\r\n}\r\n\r\n.hc-ag__list-row {\r\n  display: grid;\r\n  grid-template-columns: minmax(0, 1fr) auto auto;\r\n  align-items: center;\r\n  gap: var(--s2);\r\n  min-height: var(--row-h);\r\n  font-size: var(--fs-xs);\r\n}\r\n\r\n.hc-ag__list-row + .hc-ag__list-row {\r\n  border-top: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n}\r\n\r\n.hc-ag__list-name {\r\n  overflow: hidden;\r\n  text-overflow: ellipsis;\r\n  white-space: nowrap;\r\n  color: var(--ui-text-primary, inherit);\r\n}\r\n\r\n.hc-ag__list-meta {\r\n  white-space: nowrap;\r\n  font-variant-numeric: tabular-nums;\r\n  color: var(--ui-text-quaternary, inherit);\r\n}\r\n\r\n.hc-ag__list-foot {\r\n  margin-top: var(--s1);\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-quaternary, inherit);\r\n}\r\n\r\n.hc-ag__foot {\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-quaternary, inherit);\r\n  overflow-wrap: anywhere;\r\n}\r\n\r\n/* 容器 <1100px（= 900~1099px 视口）：收敛列 —— 隐藏「模型」「插件」两列，--ag-cols 同步收窄。\r\n   断点必须是 1099 而不是 899：侧栏 ~220px + 面板 padding 之后，900px 视口的内容宽只有 ~648px，\r\n   写 899 会让 900 宽度下仍按 8 列排（实测 28 个元素右边界溢出视口、「插件/操作」两列被挤到\r\n   容器外，要横向拖才看得见）。收窄后 6 列总宽 536px，关键操作列在 900px 内可见。 */\r\n@container hc (max-width: 1099px) {\r\n  .hc-ag__table {\r\n    --ag-cols: 68px minmax(0, 1fr) 56px 88px 84px 176px;\r\n  }\r\n\r\n  .hc-ag__cell--wide,\r\n  .hc-ag__head > .hc-ag__cell--wide {\r\n    display: none;\r\n  }\r\n}\r\n\r\n/* 更窄：状态灯只留圆点（文字挤不下会把行高顶开） */\r\n@container hc (max-width: 599px) {\r\n  .hc-ag__table {\r\n    --ag-cols: 20px minmax(0, 1fr) 48px 72px 64px 150px;\r\n  }\r\n\r\n  .hc-ag__status-text {\r\n    display: none;\r\n  }\r\n\r\n  .hc-ag__cell--ops {\r\n    gap: 2px;\r\n  }\r\n}\r\n\r\n/* ===========================================================================\r\n * 项目分组分区（C8b：只读展示 + 手动扫描）\r\n *\r\n * 结构：.hc-agg 是分区根，自上而下 = 状态条（3 个数字卡）→ 工具条（扫描按钮）\r\n * → 扫描结果/失败 → 建议列表（表格 + 分页）。\r\n * 列定义只有一份 --agg-cols，表头与数据行共用（否则两套 auto 列宽，行行不对齐）。\r\n * 颜色全部走 var(--ui-*)，无字面色值；卡片只用 1px stroke，无阴影。\r\n * =========================================================================== */\r\n\r\n.hc-agg {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s4);\r\n  min-width: 0;\r\n}\r\n\r\n/* ------------------------------------------------------------- 顶部状态条 */\r\n\r\n.hc-agg__status {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s2);\r\n  min-width: 0;\r\n}\r\n\r\n.hc-agg__stats {\r\n  display: grid;\r\n  grid-template-columns: minmax(0, 1fr);\r\n  gap: var(--s4);\r\n}\r\n\r\n/* ≥900px 三列：三个数字是并列读数，横排才能一眼比大小 */\r\n@container hc (min-width: 900px) {\r\n  .hc-agg__stats {\r\n    grid-template-columns: repeat(3, minmax(0, 1fr));\r\n  }\r\n}\r\n\r\n.hc-agg__stat {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s1);\r\n  min-width: 0;\r\n  padding: var(--s4);\r\n  border: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  border-radius: var(--r-md);\r\n  background: var(--ui-bg-secondary, transparent);\r\n}\r\n\r\n.hc-agg__stat-label {\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-quaternary, inherit);\r\n  letter-spacing: 0.02em;\r\n}\r\n\r\n.hc-agg__stat-value {\r\n  display: flex;\r\n  align-items: baseline;\r\n  flex-wrap: wrap;\r\n  gap: var(--s1);\r\n  min-width: 0;\r\n}\r\n\r\n.hc-agg__stat-num {\r\n  font-size: var(--fs-xl);\r\n  font-weight: 600;\r\n  line-height: 1.2;\r\n  font-variant-numeric: tabular-nums;\r\n  color: var(--ui-text-primary, inherit);\r\n}\r\n\r\n.hc-agg__stat-unit {\r\n  font-size: var(--fs-sm);\r\n  color: var(--ui-text-quaternary, inherit);\r\n  white-space: nowrap;\r\n}\r\n\r\n.hc-agg__stat-sub {\r\n  font-size: var(--fs-sm);\r\n  color: var(--ui-text-secondary, inherit);\r\n  overflow-wrap: anywhere;\r\n}\r\n\r\n/* 口径永远在最下面、最弱一档：数字离开口径就是猜 */\r\n.hc-agg__stat-caliber {\r\n  font-size: var(--fs-xs);\r\n  line-height: 1.45;\r\n  color: var(--ui-text-quaternary, inherit);\r\n  overflow-wrap: anywhere;\r\n}\r\n\r\n.hc-agg__notes {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s1);\r\n  min-width: 0;\r\n}\r\n\r\n.hc-agg__note {\r\n  font-size: var(--fs-xs);\r\n  line-height: 1.5;\r\n  color: var(--ui-text-quaternary, inherit);\r\n  overflow-wrap: anywhere;\r\n}\r\n\r\n/* ------------------------------------------------------------ 工具条 */\r\n\r\n.hc-agg__toolbar {\r\n  display: flex;\r\n  align-items: center;\r\n  flex-wrap: wrap;\r\n  gap: var(--s2);\r\n}\r\n\r\n.hc-agg__hint {\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-quaternary, inherit);\r\n  overflow-wrap: anywhere;\r\n}\r\n\r\n.hc-agg__scan-result {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s1);\r\n  padding: var(--s2) var(--s3);\r\n  border: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  border-radius: var(--r-sm);\r\n  font-size: var(--fs-sm);\r\n  color: var(--ui-text-secondary, inherit);\r\n  overflow-wrap: anywhere;\r\n}\r\n\r\n/* 进行中：左侧色条 + 主文案加粗，保证「按下去了」在视觉上立刻可见 */\r\n.hc-agg__scan-result--live {\r\n  border-left: 3px solid var(--ui-accent, currentColor);\r\n}\r\n\r\n.hc-agg__scan-live {\r\n  font-weight: 600;\r\n  color: var(--ui-text-primary, inherit);\r\n}\r\n\r\n/* 空结果：独立一块，标题字号与正文拉开，绝不允许看起来「什么也没发生」 */\r\n.hc-agg__scan-empty {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s1);\r\n  padding: var(--s2);\r\n  border: var(--hairline) dashed var(--ui-stroke-secondary, currentColor);\r\n  border-radius: var(--r-sm);\r\n}\r\n\r\n.hc-agg__scan-five {\r\n  display: flex;\r\n  flex-wrap: wrap;\r\n  gap: var(--s1) var(--s3);\r\n  padding: var(--s1) 0;\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-secondary, inherit);\r\n}\r\n\r\n.hc-agg__scan-five > span {\r\n  white-space: nowrap;\r\n}\r\n\r\n.hc-agg__scan-empty strong {\r\n  font-size: var(--fs-md);\r\n  color: var(--ui-text-primary, inherit);\r\n}\r\n\r\n/* ------------------------------------------------------------ AI 模型配置 */\r\n\r\n.hc-agg__model {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s2);\r\n  min-width: 0;\r\n}\r\n\r\n.hc-agg__model-row {\r\n  display: flex;\r\n  align-items: center;\r\n  flex-wrap: wrap;\r\n  gap: var(--s2);\r\n  min-width: 0;\r\n}\r\n\r\n.hc-agg__model-k {\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-tertiary, inherit);\r\n  flex: 0 0 auto;\r\n}\r\n\r\n.hc-agg__model-v {\r\n  font-size: var(--fs-sm);\r\n  color: var(--ui-text-primary, inherit);\r\n  overflow-wrap: anywhere;\r\n  min-width: 0;\r\n}\r\n\r\n.hc-agg__model-facts {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s1);\r\n  padding: var(--s2) var(--s3);\r\n  border: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  border-radius: var(--r-sm);\r\n  min-width: 0;\r\n}\r\n\r\n.hc-agg__model-kv {\r\n  display: flex;\r\n  align-items: baseline;\r\n  gap: var(--s2);\r\n  min-width: 0;\r\n}\r\n\r\n.hc-agg__model-kv .hc-agg__model-k {\r\n  flex: 0 0 148px;\r\n}\r\n\r\n.hc-agg__model-select,\r\n.hc-agg__model-input {\r\n  font: inherit;\r\n  font-size: var(--fs-sm);\r\n  max-width: 100%;\r\n  min-width: 0;\r\n  padding: 4px var(--s2);\r\n  border: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  border-radius: var(--r-sm);\r\n  background: var(--ui-bg-secondary, transparent);\r\n  color: var(--ui-text-primary, inherit);\r\n}\r\n\r\n.hc-agg__model-modes {\r\n  display: flex;\r\n  flex-wrap: wrap;\r\n  gap: var(--s2);\r\n}\r\n\r\n.hc-agg__model-mode {\r\n  display: inline-flex;\r\n  align-items: center;\r\n  gap: var(--s1);\r\n  font-size: var(--fs-sm);\r\n  padding: 2px var(--s2);\r\n  border: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  border-radius: var(--r-sm);\r\n  cursor: pointer;\r\n}\r\n\r\n.hc-agg__model-mode--on {\r\n  border-color: var(--ui-accent, currentColor);\r\n  color: var(--ui-text-primary, inherit);\r\n}\r\n\r\n.hc-agg__model-twolevel,\r\n.hc-agg__model-models {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s1);\r\n  min-width: 0;\r\n}\r\n\r\n.hc-agg__model-providers {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s1);\r\n  padding: var(--s2);\r\n  border: var(--hairline) dashed var(--ui-stroke-secondary, currentColor);\r\n  border-radius: var(--r-sm);\r\n  min-width: 0;\r\n}\r\n\r\n.hc-agg__model-providers-head {\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-tertiary, inherit);\r\n}\r\n\r\n.hc-agg__model-providers-rows {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s1);\r\n}\r\n\r\n.hc-agg__model-provider {\r\n  display: flex;\r\n  align-items: center;\r\n  flex-wrap: wrap;\r\n  gap: var(--s2);\r\n  font-size: var(--fs-sm);\r\n  min-width: 0;\r\n}\r\n\r\n/* t_11b7edbb C：provider 行是**可点选的入口**（button），不是装饰。\r\n   浏览器默认的 button 外观必须显式清掉，否则一列灰底方框比之前的纯展示更难看；\r\n   hover / 选中态要有可见反馈，否则用户还是不知道能点。 */\r\n.hc-agg__model-provider--pick {\r\n  width: 100%;\r\n  padding: var(--s1) var(--s2);\r\n  border: var(--hairline) solid transparent;\r\n  border-radius: var(--r-sm);\r\n  background: transparent;\r\n  color: inherit;\r\n  font: inherit;\r\n  font-size: var(--fs-sm);\r\n  text-align: left;\r\n  cursor: pointer;\r\n  appearance: none;\r\n}\r\n\r\n.hc-agg__model-provider--pick:hover {\r\n  border-color: var(--ui-stroke-secondary, currentColor);\r\n  background: var(--ui-row-hover-background, var(--ui-bg-tertiary, transparent));\r\n}\r\n\r\n.hc-agg__model-provider--pick:focus-visible {\r\n  outline: 2px solid var(--ui-accent, currentColor);\r\n  outline-offset: 1px;\r\n}\r\n\r\n.hc-agg__model-provider--pick.hc-agg__model-provider--on {\r\n  border-color: var(--ui-accent, currentColor);\r\n  background: var(--ui-row-active-background, var(--ui-bg-tertiary, transparent));\r\n  /* 只靠边框在深色主题下不够醒目：再加一条左侧强调条 */\r\n  box-shadow: inset 2px 0 0 0 var(--ui-accent, currentColor);\r\n}\r\n\r\n.hc-agg__model-provider--on .hc-agg__model-provider-name {\r\n  font-weight: 600;\r\n  color: var(--ui-text-primary, inherit);\r\n}\r\n\r\n.hc-agg__model-provider-name {\r\n  min-width: 0;\r\n  overflow-wrap: anywhere;\r\n}\r\n\r\n.hc-agg__model-provider-k {\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-quaternary, inherit);\r\n  font-family: var(--ui-font-mono);\r\n}\r\n\r\n.hc-agg__model-err {\r\n  font-size: var(--fs-sm);\r\n  color: var(--ui-warning, inherit);\r\n  overflow-wrap: anywhere;\r\n}\r\n\r\n.hc-agg__model-calls {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s1);\r\n  padding: var(--s2);\r\n  border: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  border-radius: var(--r-sm);\r\n  min-width: 0;\r\n}\r\n\r\n.hc-agg__model-calls-rows {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 2px;\r\n  min-width: 0;\r\n}\r\n\r\n/* ------------------------------------------------------------ 建议列表 */\r\n\r\n\r\n.hc-agg__block {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s2);\r\n  min-width: 0;\r\n}\r\n\r\n.hc-agg__block-head {\r\n  display: flex;\r\n  align-items: baseline;\r\n  flex-wrap: wrap;\r\n  gap: var(--s2);\r\n}\r\n\r\n.hc-agg__block-title {\r\n  font-size: var(--fs-md);\r\n  font-weight: 600;\r\n  color: var(--ui-text-primary, inherit);\r\n}\r\n\r\n/* 列 = 会话标题 / agent / 建议项目 / 判定依据 / 生成时间 / 操作占位 */\r\n.hc-agg__table {\r\n  --agg-cols: minmax(0, 1.5fr) 92px minmax(0, 0.9fr) minmax(0, 1.3fr) 76px minmax(136px, 0.8fr);\r\n\r\n  display: flex;\r\n  flex-direction: column;\r\n  border: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  border-radius: var(--r-md);\r\n  overflow: hidden;\r\n}\r\n\r\n.hc-agg__head {\r\n  display: grid;\r\n  grid-template-columns: var(--agg-cols);\r\n  align-items: center;\r\n  gap: var(--s2);\r\n  min-height: var(--s7);\r\n  padding: 0 var(--s3);\r\n  border-bottom: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  background: var(--ui-bg-secondary, transparent);\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-quaternary, inherit);\r\n  letter-spacing: 0.02em;\r\n}\r\n\r\n.hc-agg__row {\r\n  display: grid;\r\n  grid-template-columns: var(--agg-cols);\r\n  align-items: center;\r\n  gap: var(--s2);\r\n  min-height: var(--row-h);\r\n  padding: var(--s1) var(--s3);\r\n  font-size: var(--fs-sm);\r\n}\r\n\r\n.hc-agg__row + .hc-agg__row {\r\n  border-top: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n}\r\n\r\n.hc-agg__row:hover {\r\n  background: var(--ui-row-hover-background, var(--ui-bg-tertiary, transparent));\r\n}\r\n\r\n.hc-agg__cell {\r\n  min-width: 0;\r\n  overflow: hidden;\r\n}\r\n\r\n.hc-agg__cell--title {\r\n  display: flex;\r\n  align-items: baseline;\r\n  gap: var(--s2);\r\n}\r\n\r\n.hc-agg__title {\r\n  overflow: hidden;\r\n  text-overflow: ellipsis;\r\n  white-space: nowrap;\r\n  color: var(--ui-text-primary, inherit);\r\n}\r\n\r\n.hc-agg__msg {\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-quaternary, inherit);\r\n  white-space: nowrap;\r\n}\r\n\r\n.hc-agg__cell--agent {\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-secondary, inherit);\r\n  overflow: hidden;\r\n  text-overflow: ellipsis;\r\n  white-space: nowrap;\r\n}\r\n\r\n.hc-agg__cell--project {\r\n  display: flex;\r\n  align-items: baseline;\r\n  gap: var(--s1);\r\n}\r\n\r\n.hc-agg__project {\r\n  overflow: hidden;\r\n  text-overflow: ellipsis;\r\n  white-space: nowrap;\r\n  color: var(--ui-text-primary, inherit);\r\n}\r\n\r\n/* 项目库缺这个 slug：虚线小标签（形状 + 文字双通道，不只靠颜色） */\r\n.hc-agg__warn {\r\n  padding: 0 var(--s1);\r\n  border: var(--hairline) dashed var(--ui-warning, var(--ui-orange, currentColor));\r\n  border-radius: 999px;\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-warning, var(--ui-orange, inherit));\r\n  white-space: nowrap;\r\n}\r\n\r\n/* 判定依据允许折行：关键词列表比一列定宽更值得读全 */\r\n.hc-agg__cell--basis {\r\n  font-size: var(--fs-xs);\r\n  line-height: 1.45;\r\n  color: var(--ui-text-quaternary, inherit);\r\n  white-space: normal;\r\n  overflow-wrap: anywhere;\r\n}\r\n\r\n.hc-agg__cell--time {\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-secondary, inherit);\r\n  font-variant-numeric: tabular-nums;\r\n  text-align: right;\r\n  white-space: nowrap;\r\n}\r\n\r\n.hc-agg__cell--ops {\r\n  text-align: right;\r\n  white-space: nowrap;\r\n}\r\n\r\n/* 行内「同意并归入」：按钮 + 二次确认（from→to）+ 回读结果都塞在这一列，\r\n   必须允许换行，否则「同意并归入」五个字会被 136px 裁掉（点了像没反应）。 */\r\n.hc-agg__cell--ops-stack {\r\n  display: flex;\r\n  flex-direction: column;\r\n  align-items: flex-end;\r\n  gap: 2px;\r\n  white-space: normal;\r\n  text-align: right;\r\n  overflow-wrap: anywhere;\r\n}\r\n\r\n.hc-agg__cell--ops-stack .hc-btn {\r\n  white-space: nowrap;\r\n}\r\n\r\n\r\n.hc-agg__pager {\r\n  display: flex;\r\n  align-items: center;\r\n  flex-wrap: wrap;\r\n  gap: var(--s2);\r\n}\r\n\r\n/* <900px：收起 agent 与时间两列（agent 对「归到哪个项目」不是决定信息） */\r\n@container hc (max-width: 899px) {\r\n  .hc-agg__table {\r\n    --agg-cols: minmax(0, 1.5fr) minmax(0, 0.9fr) minmax(0, 1.3fr) 58px;\r\n  }\r\n\r\n  .hc-agg__cell--agent,\r\n  .hc-agg__head > .hc-agg__cell--agent,\r\n  .hc-agg__cell--time,\r\n  .hc-agg__head > .hc-agg__cell--time {\r\n    display: none;\r\n  }\r\n}\r\n\r\n/* <600px：再收起操作占位（C8c 才有的东西，窄窗先让位给依据） */\r\n@container hc (max-width: 599px) {\r\n  .hc-agg__table {\r\n    --agg-cols: minmax(0, 1fr) minmax(0, 0.8fr);\r\n  }\r\n\r\n  .hc-agg__cell--basis,\r\n  .hc-agg__head > .hc-agg__cell--basis,\r\n  .hc-agg__cell--ops,\r\n  .hc-agg__head > .hc-agg__cell--ops {\r\n    display: none;\r\n  }\r\n}\r\n\r\n\r\n/* ===========================================================================\r\n * Advisor 审核台（C9b：建议台账 + 采纳/拒绝 + 策略设置）\r\n *\r\n * 结构：.hc-adv 是分区根，自上而下 = 状态条（4 个数字卡 + 7 天趋势）→ 筛选条\r\n * → 建议列表（表格 + 分页）→ 详情（含决定表单）→ 策略设置（含只读阀门徽标）。\r\n * 列定义只有一份 --adv-cols，表头与数据行共用（两套 auto 列宽必然行行不对齐）。\r\n * 窄容器（<900px）列表行从表格折叠成卡片：flex-wrap + 摘要独占一行，\r\n * 任何一档都不出现横向滚动条（列表容器不设 overflow-x: auto/scroll）。\r\n * 颜色全部走 var(--ui-*)，无字面色值；卡片只用 1px stroke，无阴影。\r\n * =========================================================================== */\r\n\r\n.hc-adv {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s4);\r\n  min-width: 0;\r\n}\r\n\r\n/* ------------------------------------------------------------- 顶部状态条 */\r\n\r\n.hc-adv__status {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s2);\r\n  min-width: 0;\r\n}\r\n\r\n.hc-adv__stats {\r\n  display: grid;\r\n  grid-template-columns: minmax(0, 1fr);\r\n  gap: var(--s4);\r\n}\r\n\r\n/* ≥900px 两列 / ≥1200px 四列：四个数字是并列读数，横排才能一眼比大小 */\r\n@container hc (min-width: 900px) {\r\n  .hc-adv__stats {\r\n    grid-template-columns: repeat(2, minmax(0, 1fr));\r\n  }\r\n}\r\n\r\n@container hc (min-width: 1200px) {\r\n  .hc-adv__stats {\r\n    grid-template-columns: repeat(4, minmax(0, 1fr));\r\n  }\r\n}\r\n\r\n.hc-adv__stat {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s1);\r\n  min-width: 0;\r\n  padding: var(--s4);\r\n  border: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  border-radius: var(--r-md);\r\n  background: var(--ui-bg-secondary, transparent);\r\n}\r\n\r\n.hc-adv__stat-label {\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-quaternary, inherit);\r\n  letter-spacing: 0.02em;\r\n}\r\n\r\n.hc-adv__stat-value {\r\n  display: flex;\r\n  align-items: baseline;\r\n  flex-wrap: wrap;\r\n  gap: var(--s1);\r\n  min-width: 0;\r\n}\r\n\r\n.hc-adv__stat-num {\r\n  font-size: var(--fs-xl);\r\n  font-weight: 600;\r\n  line-height: 1.2;\r\n  font-variant-numeric: tabular-nums;\r\n  color: var(--ui-text-primary, inherit);\r\n}\r\n\r\n.hc-adv__stat-unit {\r\n  font-size: var(--fs-sm);\r\n  color: var(--ui-text-quaternary, inherit);\r\n  white-space: nowrap;\r\n}\r\n\r\n.hc-adv__stat-sub {\r\n  font-size: var(--fs-sm);\r\n  color: var(--ui-text-secondary, inherit);\r\n  overflow-wrap: anywhere;\r\n}\r\n\r\n/* 口径永远在最下面、最弱一档：数字离开口径就是猜 */\r\n.hc-adv__stat-caliber {\r\n  font-size: var(--fs-xs);\r\n  line-height: 1.45;\r\n  color: var(--ui-text-quaternary, inherit);\r\n  overflow-wrap: anywhere;\r\n}\r\n\r\n/* 7 天趋势：一行小字 + 7 根细柱（柱高只表达「当天新增」的相对量） */\r\n.hc-adv__trend {\r\n  display: flex;\r\n  align-items: center;\r\n  flex-wrap: wrap;\r\n  gap: var(--s2);\r\n  min-width: 0;\r\n}\r\n\r\n.hc-adv__trend-text {\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-quaternary, inherit);\r\n}\r\n\r\n.hc-adv__trend-bars {\r\n  display: flex;\r\n  align-items: flex-end;\r\n  gap: 2px;\r\n  height: var(--s6);\r\n}\r\n\r\n.hc-adv__trend-day {\r\n  display: block;\r\n  width: 6px;\r\n  min-height: 2px;\r\n  border-radius: 2px;\r\n  background: var(--ui-accent, currentColor);\r\n  opacity: 0.55;\r\n}\r\n\r\n.hc-adv__notes {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s1);\r\n  min-width: 0;\r\n}\r\n\r\n.hc-adv__note {\r\n  font-size: var(--fs-xs);\r\n  line-height: 1.5;\r\n  color: var(--ui-text-quaternary, inherit);\r\n  overflow-wrap: anywhere;\r\n}\r\n\r\n/* ------------------------------------------------------------ 筛选条 */\r\n\r\n.hc-adv__filters {\r\n  display: flex;\r\n  align-items: center;\r\n  flex-wrap: wrap;\r\n  gap: var(--s2);\r\n}\r\n\r\n.hc-adv__filter {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: var(--s1);\r\n  min-width: 0;\r\n}\r\n\r\n.hc-adv__filter--grow {\r\n  flex: 1 1 200px;\r\n}\r\n\r\n/* 「建议详情与策略设置」里的 Agent 选择器。\r\n * 坑（t_4121ded4 实测）：`.hc-adv__settings` 是 flex-direction:column 的容器，\r\n * 在这里套 `.hc-adv__filter--grow`（flex: 1 1 200px）会让 flex-basis 变成**高度**，\r\n * 包壳 label 被撑成 200px 高、控件垂直居中 —— 下拉框和下一行「当前读写」之间凭空多出\r\n * 约 170px 空白（用户看到的「大片留白」）。列方向里必须显式 flex:0 0 auto。 */\r\n.hc-adv__settings-picker {\r\n  flex: 0 0 auto;\r\n  align-self: flex-start;\r\n  max-width: 100%;\r\n}\r\n\r\n.hc-adv__filter-label {\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-quaternary, inherit);\r\n  white-space: nowrap;\r\n}\r\n\r\n.hc-adv__input {\r\n  min-width: 0;\r\n  width: 100%;\r\n  padding: 4px var(--s2);\r\n  border: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  border-radius: var(--r-sm);\r\n  background: var(--ui-bg-secondary, transparent);\r\n  color: var(--ui-text-primary, inherit);\r\n  font-size: var(--fs-sm);\r\n  font-family: inherit;\r\n}\r\n\r\n.hc-adv__textarea {\r\n  width: 100%;\r\n  min-width: 0;\r\n  padding: var(--s1) var(--s2);\r\n  border: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  border-radius: var(--r-sm);\r\n  background: var(--ui-bg-secondary, transparent);\r\n  color: var(--ui-text-primary, inherit);\r\n  font-size: var(--fs-sm);\r\n  font-family: inherit;\r\n  resize: vertical;\r\n}\r\n\r\n/* ------------------------------------------------------------ 建议列表 */\r\n\r\n.hc-adv__block {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s2);\r\n  min-width: 0;\r\n}\r\n\r\n.hc-adv__block-head {\r\n  display: flex;\r\n  align-items: baseline;\r\n  flex-wrap: wrap;\r\n  gap: var(--s2);\r\n}\r\n\r\n.hc-adv__block-title {\r\n  font-size: var(--fs-md);\r\n  font-weight: 600;\r\n  color: var(--ui-text-primary, inherit);\r\n}\r\n\r\n/* 列 = 时间 / 严重度 / 摘要 / 状态 / 来源 / 操作。全部 minmax(0, …)：定宽列会把窄窗撑出横向滚动 */\r\n.hc-adv__table {\r\n  --adv-cols: 74px 78px minmax(0, 1fr) 68px minmax(0, 132px) 62px;\r\n  display: flex;\r\n  flex-direction: column;\r\n  min-width: 0;\r\n  border: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  border-radius: var(--r-md);\r\n  overflow: hidden;\r\n}\r\n\r\n.hc-adv__head {\r\n  display: grid;\r\n  grid-template-columns: var(--adv-cols);\r\n  align-items: center;\r\n  gap: var(--s2);\r\n  min-height: var(--s7);\r\n  padding: 0 var(--s3);\r\n  border-bottom: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  background: var(--ui-bg-secondary, transparent);\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-quaternary, inherit);\r\n  letter-spacing: 0.02em;\r\n}\r\n\r\n.hc-adv__row {\r\n  display: grid;\r\n  grid-template-columns: var(--adv-cols);\r\n  align-items: center;\r\n  gap: var(--s2);\r\n  min-height: var(--row-h);\r\n  padding: var(--s1) var(--s3);\r\n  font-size: var(--fs-sm);\r\n  min-width: 0;\r\n}\r\n\r\n.hc-adv__row + .hc-adv__row {\r\n  border-top: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n}\r\n\r\n.hc-adv__row:hover {\r\n  background: var(--ui-row-hover-background, var(--ui-bg-tertiary, transparent));\r\n}\r\n\r\n.hc-adv__row--active {\r\n  background: var(--ui-row-active-background, var(--ui-bg-tertiary, transparent));\r\n}\r\n\r\n.hc-adv__cell {\r\n  min-width: 0;\r\n  overflow: hidden;\r\n}\r\n\r\n.hc-adv__cell--time {\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-secondary, inherit);\r\n  font-variant-numeric: tabular-nums;\r\n  white-space: nowrap;\r\n}\r\n\r\n.hc-adv__cell--sev {\r\n  white-space: nowrap;\r\n}\r\n\r\n.hc-adv__cell--note {\r\n  min-width: 0;\r\n}\r\n\r\n.hc-adv__note-text {\r\n  display: block;\r\n  overflow: hidden;\r\n  text-overflow: ellipsis;\r\n  white-space: nowrap;\r\n  color: var(--ui-text-primary, inherit);\r\n}\r\n\r\n/* 摘要行：可选「未点名」小标记 + 省略号正文（标记不参与省略号，正文自己收缩） */\r\n.hc-adv__note-wrap {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: var(--s1);\r\n  min-width: 0;\r\n}\r\n\r\n.hc-adv__note-wrap > .hc-adv__note-text {\r\n  flex: 1 1 auto;\r\n  min-width: 0;\r\n}\r\n\r\n.hc-adv__cell--status {\r\n  white-space: nowrap;\r\n}\r\n\r\n.hc-adv__cell--source {\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-quaternary, inherit);\r\n  overflow: hidden;\r\n  text-overflow: ellipsis;\r\n  white-space: nowrap;\r\n}\r\n\r\n.hc-adv__profile {\r\n  color: var(--ui-text-secondary, inherit);\r\n}\r\n\r\n.hc-adv__session {\r\n  font-variant-numeric: tabular-nums;\r\n}\r\n\r\n.hc-adv__cell--ops {\r\n  text-align: right;\r\n  white-space: nowrap;\r\n}\r\n\r\n/* severity 徽标：三档视觉强度不同（描边 → 加粗描边 → 粗描边 + 字重），不只靠颜色 */\r\n.hc-adv__sev {\r\n  display: inline-block;\r\n  padding: 0 var(--s1);\r\n  border: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  border-radius: 999px;\r\n  font-size: var(--fs-xs);\r\n  letter-spacing: 0.04em;\r\n  color: var(--ui-text-quaternary, inherit);\r\n}\r\n\r\n.hc-adv__sev--concern {\r\n  border-color: var(--ui-warning, var(--ui-orange, currentColor));\r\n  color: var(--ui-warning, var(--ui-orange, inherit));\r\n}\r\n\r\n.hc-adv__sev--blocker {\r\n  border-width: 2px;\r\n  border-color: var(--ui-warning, var(--ui-orange, currentColor));\r\n  color: var(--ui-warning, var(--ui-orange, inherit));\r\n  font-weight: 600;\r\n}\r\n\r\n/* 状态药丸：形状 + 文字双通道 */\r\n.hc-adv__pill {\r\n  display: inline-block;\r\n  padding: 0 var(--s2);\r\n  border-radius: 999px;\r\n  font-size: var(--fs-xs);\r\n  border: var(--hairline) dashed var(--ui-stroke-secondary, currentColor);\r\n  color: var(--ui-text-quaternary, inherit);\r\n  white-space: nowrap;\r\n}\r\n\r\n.hc-adv__pill--delivered {\r\n  border-style: solid;\r\n  color: var(--ui-text-secondary, inherit);\r\n}\r\n\r\n.hc-adv__pill--accepted {\r\n  border-style: solid;\r\n  border-color: var(--ui-accent, currentColor);\r\n  color: var(--ui-accent, inherit);\r\n}\r\n\r\n.hc-adv__pill--rejected {\r\n  border-style: solid;\r\n  border-color: var(--ui-warning, var(--ui-orange, currentColor));\r\n  color: var(--ui-warning, var(--ui-orange, inherit));\r\n}\r\n\r\n.hc-adv__pill--dropped {\r\n  border-style: dotted;\r\n  color: var(--ui-text-quaternary, inherit);\r\n}\r\n\r\n.hc-adv__pager {\r\n  display: flex;\r\n  align-items: center;\r\n  flex-wrap: wrap;\r\n  gap: var(--s2);\r\n}\r\n\r\n.hc-adv__hint {\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-quaternary, inherit);\r\n  overflow-wrap: anywhere;\r\n}\r\n\r\n/* ------------------------------------------------------------ 详情 */\r\n\r\n.hc-adv__detail {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s3);\r\n  min-width: 0;\r\n  padding: var(--s4);\r\n  border: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  border-radius: var(--r-md);\r\n  background: var(--ui-bg-secondary, transparent);\r\n}\r\n\r\n.hc-adv__detail-head {\r\n  display: flex;\r\n  align-items: center;\r\n  flex-wrap: wrap;\r\n  gap: var(--s2);\r\n  min-width: 0;\r\n}\r\n\r\n.hc-adv__detail-title {\r\n  font-size: var(--fs-md);\r\n  font-weight: 600;\r\n  color: var(--ui-text-primary, inherit);\r\n}\r\n\r\n.hc-adv__detail-note {\r\n  font-size: var(--fs-sm);\r\n  line-height: 1.6;\r\n  color: var(--ui-text-primary, inherit);\r\n  white-space: pre-wrap;\r\n  overflow-wrap: anywhere;\r\n}\r\n\r\n.hc-adv__facts {\r\n  display: flex;\r\n  align-items: baseline;\r\n  flex-wrap: wrap;\r\n  gap: var(--s1) var(--s3);\r\n  min-width: 0;\r\n}\r\n\r\n.hc-adv__fact {\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-quaternary, inherit);\r\n  font-variant-numeric: tabular-nums;\r\n  white-space: nowrap;\r\n}\r\n\r\n.hc-adv__timeline {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s1);\r\n  min-width: 0;\r\n  padding-left: var(--s3);\r\n  border-left: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n}\r\n\r\n.hc-adv__timeline-title {\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-quaternary, inherit);\r\n  letter-spacing: 0.02em;\r\n}\r\n\r\n.hc-adv__event {\r\n  display: flex;\r\n  align-items: baseline;\r\n  flex-wrap: wrap;\r\n  gap: var(--s1) var(--s2);\r\n  min-width: 0;\r\n  font-size: var(--fs-xs);\r\n}\r\n\r\n.hc-adv__event-ts {\r\n  color: var(--ui-text-quaternary, inherit);\r\n  font-variant-numeric: tabular-nums;\r\n  white-space: nowrap;\r\n}\r\n\r\n.hc-adv__event-name {\r\n  color: var(--ui-text-primary, inherit);\r\n  font-weight: 600;\r\n  white-space: nowrap;\r\n}\r\n\r\n.hc-adv__event-meta {\r\n  color: var(--ui-text-secondary, inherit);\r\n  overflow-wrap: anywhere;\r\n}\r\n\r\n/* ------------------------------------------------------------ 决定表单 */\r\n\r\n.hc-adv__decision {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s2);\r\n  min-width: 0;\r\n  padding-top: var(--s3);\r\n  border-top: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n}\r\n\r\n.hc-adv__decision-head {\r\n  display: flex;\r\n  align-items: center;\r\n  flex-wrap: wrap;\r\n  gap: var(--s2);\r\n}\r\n\r\n.hc-adv__decision-label {\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-quaternary, inherit);\r\n}\r\n\r\n.hc-adv__decision-reason {\r\n  font-size: var(--fs-sm);\r\n  color: var(--ui-text-secondary, inherit);\r\n  overflow-wrap: anywhere;\r\n}\r\n\r\n.hc-adv__reason {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s2);\r\n  min-width: 0;\r\n}\r\n\r\n.hc-adv__reason-actions {\r\n  display: flex;\r\n  align-items: center;\r\n  flex-wrap: wrap;\r\n  gap: var(--s2);\r\n}\r\n\r\n/* 校验/写失败：虚线框 + 文字（形状与文字双通道，不只靠颜色） */\r\n.hc-adv__formerr {\r\n  padding: var(--s1) var(--s2);\r\n  border: var(--hairline) dashed var(--ui-warning, var(--ui-orange, currentColor));\r\n  border-radius: var(--r-sm);\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-warning, var(--ui-orange, inherit));\r\n  overflow-wrap: anywhere;\r\n}\r\n\r\n.hc-adv__formsaved {\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-accent, inherit);\r\n}\r\n\r\n/* ------------------------------------------------------------ 策略设置 */\r\n\r\n.hc-adv__settings {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s3);\r\n  min-width: 0;\r\n  padding: var(--s4);\r\n  border: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  border-radius: var(--r-md);\r\n}\r\n\r\n.hc-adv__form {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s2);\r\n  min-width: 0;\r\n}\r\n\r\n.hc-adv__field {\r\n  display: flex;\r\n  align-items: center;\r\n  flex-wrap: wrap;\r\n  gap: var(--s2);\r\n  min-width: 0;\r\n}\r\n\r\n.hc-adv__field-label {\r\n  font-size: var(--fs-sm);\r\n  color: var(--ui-text-secondary, inherit);\r\n  min-width: 160px;\r\n}\r\n\r\n.hc-adv__field .hc-adv__input {\r\n  flex: 1 1 160px;\r\n  width: auto;\r\n}\r\n\r\n.hc-adv__form-actions {\r\n  display: flex;\r\n  align-items: center;\r\n  flex-wrap: wrap;\r\n  gap: var(--s2);\r\n}\r\n\r\n/* 只读阀门徽标：一眼看出「这不是开关」，内部没有任何可点控件 */\r\n.hc-adv__readonly {\r\n  display: flex;\r\n  align-items: baseline;\r\n  flex-wrap: wrap;\r\n  gap: var(--s1) var(--s2);\r\n  min-width: 0;\r\n  padding: var(--s2) var(--s3);\r\n  border: var(--hairline) dashed var(--ui-warning, var(--ui-orange, currentColor));\r\n  border-radius: var(--r-sm);\r\n  background: var(--ui-bg-tertiary, transparent);\r\n}\r\n\r\n.hc-adv__readonly-label {\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-secondary, inherit);\r\n}\r\n\r\n.hc-adv__readonly-value {\r\n  font-size: var(--fs-sm);\r\n  font-weight: 600;\r\n  font-variant-numeric: tabular-nums;\r\n  color: var(--ui-warning, var(--ui-orange, inherit));\r\n}\r\n\r\n.hc-adv__readonly-note {\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-warning, var(--ui-orange, inherit));\r\n  white-space: nowrap;\r\n}\r\n\r\n/* <900px：表头收起，列表行折叠成卡片（摘要独占一行，其余换行排布）。\r\n   全部用 flex-wrap + 百分比宽度：不产生横向滚动条，也不依赖具体像素。 */\r\n@container hc (max-width: 899px) {\r\n  .hc-adv__head {\r\n    display: none;\r\n  }\r\n\r\n  .hc-adv__table {\r\n    border: none;\r\n    border-radius: 0;\r\n    overflow: visible;\r\n  }\r\n\r\n  .hc-adv__row {\r\n    display: flex;\r\n    flex-wrap: wrap;\r\n    align-items: baseline;\r\n    gap: var(--s1) var(--s2);\r\n    min-height: 0;\r\n    padding: var(--s3);\r\n    border: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n    border-radius: var(--r-sm);\r\n  }\r\n\r\n  .hc-adv__row + .hc-adv__row {\r\n    border-top: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n    margin-top: var(--s2);\r\n  }\r\n\r\n  .hc-adv__cell--note {\r\n    flex: 1 1 100%;\r\n    order: -1;\r\n  }\r\n\r\n  .hc-adv__note-text {\r\n    white-space: normal;\r\n    overflow-wrap: anywhere;\r\n  }\r\n\r\n  .hc-adv__cell--source {\r\n    flex: 1 1 auto;\r\n  }\r\n\r\n  .hc-adv__cell--ops {\r\n    margin-left: auto;\r\n  }\r\n\r\n  .hc-adv__field-label {\r\n    min-width: 0;\r\n    flex: 1 1 100%;\r\n  }\r\n}\r\n\r\n/* ------------------------------------------------------------------ 设置分区（M4b1）\r\n *\r\n * 三态必须**形状 + 文字双通道**区分，不靠颜色单独表达（同 .hc-conn 的规矩）：\r\n *   enabled     实线描边 + 「已启用」\r\n *   disabled    虚线描边 + 「已被禁用」\r\n *   unavailable 点线描边 + 一档灰底 + 「不在该 Agent 可用范围」，这一行**不渲染开关**\r\n * 颜色一律 var(--ui-*)，本块零字面色值。\r\n */\r\n\r\n.hc-set {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s4);\r\n  min-width: 0;\r\n}\r\n\r\n.hc-set__grid {\r\n  display: grid;\r\n  grid-template-columns: minmax(0, 1fr);\r\n  gap: var(--s4);\r\n  min-width: 0;\r\n}\r\n\r\n@container hc (min-width: 900px) {\r\n  .hc-set__grid {\r\n    grid-template-columns: minmax(0, 1fr) minmax(0, 1.1fr);\r\n  }\r\n}\r\n\r\n.hc-set__col {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s2);\r\n  min-width: 0;\r\n  padding: var(--s3);\r\n  border: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  border-radius: var(--r-md);\r\n}\r\n\r\n.hc-set__listhead,\r\n.hc-set__detailhead {\r\n  display: flex;\r\n  flex-wrap: wrap;\r\n  align-items: center;\r\n  gap: var(--s2);\r\n}\r\n\r\n.hc-set__listtitle {\r\n  font-size: var(--fs-lg);\r\n  color: var(--ui-text-primary, inherit);\r\n}\r\n\r\n.hc-set__path {\r\n  margin-left: auto;\r\n}\r\n\r\n.hc-set__counts {\r\n  display: flex;\r\n  flex-wrap: wrap;\r\n  gap: var(--s1);\r\n}\r\n\r\n.hc-set__count--enabled {\r\n  border-style: solid;\r\n  color: var(--ui-text-primary, inherit);\r\n}\r\n\r\n.hc-set__count--disabled {\r\n  border-style: dashed;\r\n}\r\n\r\n/* 第三态在计数条上也要「一眼不是已启用」：点线 + 最弱一档文字 */\r\n.hc-set__count--unavailable {\r\n  border-style: dotted;\r\n  background: var(--ui-bg-tertiary, transparent);\r\n}\r\n\r\n.hc-set__list {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s2);\r\n  margin: 0;\r\n  padding: 0;\r\n  list-style: none;\r\n  min-width: 0;\r\n}\r\n\r\n.hc-set__row {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s1);\r\n  padding: var(--s2) var(--s3);\r\n  border: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  border-radius: var(--r-sm);\r\n  min-width: 0;\r\n  overflow-wrap: anywhere;\r\n}\r\n\r\n.hc-set__row--enabled {\r\n  border-style: solid;\r\n}\r\n\r\n.hc-set__row--disabled {\r\n  border-style: dashed;\r\n}\r\n\r\n.hc-set__row--unavailable {\r\n  border-style: dotted;\r\n  background: var(--ui-bg-tertiary, transparent);\r\n}\r\n\r\n.hc-set__row--selected {\r\n  border-color: var(--ui-accent, currentColor);\r\n  background: var(--ui-row-active-background, transparent);\r\n}\r\n\r\n/*\r\n * 整行可点（role=\"button\"）：视觉上必须给出「这一行能点」的反馈。\r\n * 之前行只有卡片外观、没有任何点击反馈，看起来能点、实际只有内部小按钮能点 ——\r\n * hover / 键盘焦点 / 按下三种状态都要显式，别让老板靠猜。\r\n */\r\n.hc-set__row--clickable {\r\n  cursor: pointer;\r\n}\r\n\r\n.hc-set__row--clickable:hover {\r\n  background: var(--ui-row-hover-background, var(--ui-bg-tertiary, transparent));\r\n}\r\n\r\n.hc-set__row--clickable:focus-visible {\r\n  outline: var(--hairline) solid var(--ui-accent, currentColor);\r\n  outline-offset: 2px;\r\n}\r\n\r\n.hc-set__row--clickable:active {\r\n  background: var(--ui-row-active-background, transparent);\r\n}\r\n\r\n/* 选中态优先于 hover：别让鼠标划过把「正在看哪个插件」冲淡 */\r\n.hc-set__row--clickable.hc-set__row--selected:hover {\r\n  border-color: var(--ui-accent, currentColor);\r\n  background: var(--ui-row-active-background, transparent);\r\n}\r\n\r\n.hc-set__row-head {\r\n  display: flex;\r\n  flex-wrap: wrap;\r\n  align-items: baseline;\r\n  gap: var(--s2);\r\n  min-width: 0;\r\n}\r\n\r\n.hc-set__name {\r\n  display: inline-flex;\r\n  align-items: baseline;\r\n  gap: var(--s2);\r\n  flex: 1 1 auto;\r\n  min-width: 0;\r\n}\r\n\r\n.hc-set__display {\r\n  font-size: var(--fs-lg);\r\n  color: var(--ui-text-primary, inherit);\r\n}\r\n\r\n.hc-set__id {\r\n  font-size: var(--fs-sm);\r\n  color: var(--ui-text-quaternary, inherit);\r\n}\r\n\r\n.hc-set__state {\r\n  padding: 0 var(--s2);\r\n  border: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  border-radius: 999px;\r\n  font-size: var(--fs-xs);\r\n  white-space: nowrap;\r\n}\r\n\r\n.hc-set__state--enabled {\r\n  color: var(--ui-text-primary, inherit);\r\n}\r\n\r\n.hc-set__state--disabled {\r\n  border-style: dashed;\r\n  color: var(--ui-text-secondary, inherit);\r\n}\r\n\r\n.hc-set__state--unavailable {\r\n  border-style: dotted;\r\n  color: var(--ui-warning, inherit);\r\n}\r\n\r\n.hc-set__row-chips {\r\n  display: flex;\r\n  flex-wrap: wrap;\r\n  gap: var(--s1);\r\n  min-width: 0;\r\n}\r\n\r\n/* 插件命名空间标识：和 hc-chip（面板 / 版本 / 来源）刻意不同形（方角描边） */\r\n.hc-set__kind {\r\n  padding: 0 var(--s2);\r\n  border: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  border-radius: var(--r-sm);\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-secondary, inherit);\r\n  white-space: nowrap;\r\n}\r\n\r\n.hc-set__row-hint,\r\n.hc-set__row-note,\r\n.hc-set__note {\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-quaternary, inherit);\r\n  min-width: 0;\r\n  overflow-wrap: anywhere;\r\n}\r\n\r\n.hc-set__row-note {\r\n  display: -webkit-box;\r\n  -webkit-line-clamp: 2;\r\n  -webkit-box-orient: vertical;\r\n  overflow: hidden;\r\n}\r\n\r\n.hc-set__note {\r\n  padding: var(--s1) var(--s2);\r\n  border-left: var(--nav-mark) solid var(--ui-stroke-secondary, currentColor);\r\n}\r\n\r\n.hc-set__notes {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s1);\r\n  margin: 0;\r\n  padding: 0;\r\n  list-style: none;\r\n}\r\n\r\n.hc-set__warn {\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-warning, inherit);\r\n}\r\n\r\n.hc-set__row-actions {\r\n  display: flex;\r\n  flex-wrap: wrap;\r\n  align-items: center;\r\n  gap: var(--s2);\r\n}\r\n\r\n/* 409 冲突：单独一块，不靠颜色说话（role=alert + 标题 + 后端原话 + 刷新按钮） */\r\n.hc-set__conflict {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s2);\r\n  min-width: 0;\r\n  padding: var(--s3);\r\n  border: var(--hairline) solid var(--ui-warning, currentColor);\r\n  border-radius: var(--r-sm);\r\n  background: var(--ui-bg-tertiary, transparent);\r\n}\r\n\r\n.hc-set__conflict-title {\r\n  font-size: var(--fs-md);\r\n  color: var(--ui-text-primary, inherit);\r\n}\r\n\r\n.hc-set__conflict-detail {\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-quaternary, inherit);\r\n  overflow-wrap: anywhere;\r\n}\r\n\r\n.hc-set__fields {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s2);\r\n  min-width: 0;\r\n}\r\n\r\n.hc-set__field {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s1);\r\n  min-width: 0;\r\n  padding: var(--s2);\r\n  border: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  border-radius: var(--r-sm);\r\n}\r\n\r\n/* 只读项（脱敏 / manifest readonly / 结构化值）：点线 + 一档灰底，和可写项一眼可分 */\r\n.hc-set__field--locked {\r\n  border-style: dotted;\r\n  background: var(--ui-bg-tertiary, transparent);\r\n}\r\n\r\n.hc-set__field-head {\r\n  display: flex;\r\n  flex-wrap: wrap;\r\n  align-items: baseline;\r\n  gap: var(--s2);\r\n  min-width: 0;\r\n}\r\n\r\n.hc-set__key {\r\n  min-width: 0;\r\n  font-size: var(--fs-sm);\r\n  color: var(--ui-text-primary, inherit);\r\n  overflow-wrap: anywhere;\r\n}\r\n\r\n/* 来源层三种写法必须区分：点线=模块默认，虚线=全局，实线加粗描边=本 Agent 覆盖 */\r\n.hc-set__src {\r\n  padding: 0 var(--s2);\r\n  border: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  border-radius: var(--r-sm);\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-quaternary, inherit);\r\n  white-space: nowrap;\r\n}\r\n\r\n.hc-set__src--module_default {\r\n  border-style: dotted;\r\n}\r\n\r\n.hc-set__src--global {\r\n  border-style: dashed;\r\n}\r\n\r\n.hc-set__src--agent {\r\n  color: var(--ui-text-primary, inherit);\r\n  border-color: var(--ui-accent, currentColor);\r\n  font-weight: 600;\r\n}\r\n\r\n.hc-set__ro {\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-warning, inherit);\r\n  white-space: nowrap;\r\n}\r\n\r\n.hc-set__field-body {\r\n  display: flex;\r\n  flex-wrap: wrap;\r\n  align-items: center;\r\n  gap: var(--s2);\r\n  min-width: 0;\r\n}\r\n\r\n.hc-set__input {\r\n  flex: 1 1 180px;\r\n  min-width: 0;\r\n  padding: var(--s1) var(--s2);\r\n  border: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  border-radius: var(--r-sm);\r\n  background: var(--ui-bg-secondary, transparent);\r\n  color: var(--ui-text-primary, inherit);\r\n  font: inherit;\r\n  font-size: var(--fs-md);\r\n}\r\n\r\n.hc-set__input:focus-visible {\r\n  border-color: var(--ui-accent, currentColor);\r\n}\r\n\r\n.hc-set__input:disabled {\r\n  color: var(--ui-text-quaternary, inherit);\r\n  cursor: not-allowed;\r\n}\r\n\r\n@container hc (max-width: 899px) {\r\n  /* 窄窗：列内边距收紧、输入与动作各占整行 —— 目的是不横向滚动 */\r\n  .hc-set__col {\r\n    padding: var(--s2);\r\n  }\r\n\r\n  .hc-set__row {\r\n    padding: var(--s2);\r\n  }\r\n\r\n  .hc-set__state {\r\n    margin-left: auto;\r\n  }\r\n\r\n  .hc-set__input {\r\n    flex: 1 1 100%;\r\n  }\r\n\r\n  .hc-set__row-actions .hc-btn {\r\n    flex: 1 1 auto;\r\n  }\r\n}\r\n\r\n/* ------------------------------------------------ 升级分区（V2：6 路由真实 UI） */\r\n/*\r\n * 只用概览已有的 .hc-cards / .hc-card / .hc-block / .hc-rows / .hc-btn 等积木，\r\n * 这里补的是升级分区独有的四样东西：顶栏、操作条、二次确认条、动作结果条。\r\n * 颜色一律 var(--ui-*)，没有字面色值（build.mjs 会扫）。\r\n */\r\n\r\n.hc-up {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s4);\r\n  min-width: 0;\r\n}\r\n\r\n/* 顶栏：版本 / 快照路径 / 作用域说明 / 重新扫描。路径很长，必须能被截断。 */\r\n.hc-up__bar {\r\n  display: flex;\r\n  align-items: center;\r\n  flex-wrap: wrap;\r\n  gap: var(--s2) var(--s3);\r\n  min-width: 0;\r\n}\r\n\r\n.hc-up__version {\r\n  font-size: var(--fs-md);\r\n  font-weight: 600;\r\n  color: var(--ui-text-primary, inherit);\r\n  white-space: nowrap;\r\n}\r\n\r\n.hc-up__path {\r\n  flex: 1 1 240px;\r\n  min-width: 0;\r\n  overflow: hidden;\r\n  text-overflow: ellipsis;\r\n  white-space: nowrap;\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-quaternary, inherit);\r\n  font-variant-numeric: tabular-nums;\r\n}\r\n\r\n/* 操作条：三个动作横排，窄窗自动换行（不横向滚动） */\r\n.hc-up__ops {\r\n  display: flex;\r\n  align-items: center;\r\n  flex-wrap: wrap;\r\n  gap: var(--s2);\r\n}\r\n\r\n/* 危险动作：虚线警示框 + 警示色文字。\r\n   颜色只是辅助 —— 真正的保护是「必须先点一次、再点确认」这条交互。 */\r\n.hc-up__danger {\r\n  border-style: dashed;\r\n  border-color: var(--ui-warning, var(--ui-orange, currentColor));\r\n  color: var(--ui-warning, var(--ui-orange, inherit));\r\n}\r\n\r\n.hc-up__danger:hover {\r\n  border-color: var(--ui-warning, var(--ui-orange, currentColor));\r\n  color: var(--ui-text-primary, inherit);\r\n}\r\n\r\n.hc-up__danger:disabled {\r\n  border-style: solid;\r\n  border-color: var(--ui-stroke-secondary, currentColor);\r\n  color: var(--ui-text-quaternary, inherit);\r\n}\r\n\r\n/* 二次确认条：占满一行，问题在左、确认 / 取消在右 */\r\n.hc-up__confirm {\r\n  display: flex;\r\n  align-items: center;\r\n  flex-wrap: wrap;\r\n  gap: var(--s2);\r\n  padding: var(--s2) var(--s3);\r\n  border: var(--hairline) dashed var(--ui-warning, var(--ui-orange, currentColor));\r\n  border-radius: var(--r-sm);\r\n  background: var(--ui-bg-secondary, transparent);\r\n}\r\n\r\n.hc-up__confirm-q {\r\n  flex: 1 1 240px;\r\n  min-width: 0;\r\n  font-size: var(--fs-sm);\r\n  color: var(--ui-warning, var(--ui-orange, inherit));\r\n  overflow-wrap: anywhere;\r\n}\r\n\r\n/* 动作结果：成功 / 失败同一块，靠左边框 + 文字双通道区分（不只靠颜色） */\r\n.hc-up__feedback {\r\n  display: flex;\r\n  align-items: baseline;\r\n  flex-wrap: wrap;\r\n  gap: var(--s2);\r\n  padding: var(--s2) var(--s3);\r\n  border-left: var(--nav-mark) solid var(--ui-stroke-secondary, currentColor);\r\n  border-radius: var(--r-sm);\r\n  background: var(--ui-bg-secondary, transparent);\r\n}\r\n\r\n.hc-up__feedback--ok {\r\n  border-left-color: var(--ui-accent, currentColor);\r\n}\r\n\r\n.hc-up__feedback--error {\r\n  border-left-color: var(--ui-warning, var(--ui-orange, currentColor));\r\n}\r\n\r\n.hc-up__feedback-title {\r\n  font-size: var(--fs-sm);\r\n  font-weight: 600;\r\n  color: var(--ui-text-primary, inherit);\r\n  white-space: nowrap;\r\n}\r\n\r\n/* 后端原话：允许任意断行（错误里常有长路径），不截断、不省略 */\r\n.hc-up__feedback-text {\r\n  flex: 1 1 260px;\r\n  min-width: 0;\r\n  font-size: var(--fs-sm);\r\n  color: var(--ui-text-secondary, inherit);\r\n  overflow-wrap: anywhere;\r\n}\r\n\r\n/* 进程表：PID / 身份 / 命令行 / 操作。命令行可伸缩，其余定宽。 */\r\n.hc-up__rows {\r\n  --row-cols: 76px 132px minmax(0, 1fr) auto;\r\n}\r\n\r\n.hc-up__rows .hc-row {\r\n  grid-template-columns: var(--row-cols);\r\n}\r\n\r\n.hc-up__cell {\r\n  min-width: 0;\r\n}\r\n\r\n.hc-up__cell--pid {\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-quaternary, inherit);\r\n  font-variant-numeric: tabular-nums;\r\n}\r\n\r\n.hc-up__cell--cmd {\r\n  overflow: hidden;\r\n  text-overflow: ellipsis;\r\n  white-space: nowrap;\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-secondary, inherit);\r\n}\r\n\r\n.hc-up__cell--ops {\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: flex-end;\r\n  gap: var(--s1);\r\n}\r\n\r\n.hc-up__foot {\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-quaternary, inherit);\r\n}\r\n\r\n@container hc (max-width: 899px) {\r\n  /* 窄窗：命令行列最不关键，先让它消失，避免整表横向滚动 */\r\n  .hc-up__rows {\r\n    --row-cols: 68px minmax(0, 1fr) auto;\r\n  }\r\n\r\n  .hc-up__cell--cmd {\r\n    display: none;\r\n  }\r\n\r\n  .hc-up__ops .hc-btn,\r\n  .hc-up__confirm .hc-btn {\r\n    flex: 1 1 auto;\r\n  }\r\n}\r\n\r\n/* ==========================================================================\r\n * V5 · 模型分区（models）\r\n *\r\n * 只加「整体骨架」的几处样式：目标 agent 横幅 / 切换面板 / 对比条 / 模型库分组。\r\n * 其余全部复用既有积木（.hc-block / .hc-rows / .hc-row / .hc-btn / .hc-chip /\r\n * .hc-cards / .hc-card / .hc-up__confirm / .hc-up__feedback），不新造一套视觉。\r\n * 颜色只用 `var(--ui-*)`：本文件里不出现任何字面色值。\r\n * ========================================================================== */\r\n.hc-models__target {\r\n  padding: var(--s3) 0;\r\n  border-bottom: var(--hairline) solid var(--ui-border);\r\n}\r\n\r\n.hc-models__diff {\r\n  padding: var(--s1) 0;\r\n  border-bottom: var(--hairline) dashed var(--ui-border);\r\n}\r\n\r\n.hc-models__diff:last-of-type {\r\n  border-bottom: 0;\r\n}\r\n\r\n.hc-models__switch,\r\n.hc-models__confirm {\r\n  padding: var(--s3);\r\n  border: var(--hairline) solid var(--ui-stroke-secondary);\r\n  border-radius: var(--r-md);\r\n}\r\n\r\n.hc-models__confirm {\r\n  background: var(--ui-bg-secondary);\r\n}\r\n\r\n.hc-models__prow,\r\n.hc-models__lib {\r\n  padding: var(--s2) 0;\r\n}\r\n\r\n.hc-models__lib {\r\n  border-bottom: var(--hairline) solid var(--ui-stroke-secondary);\r\n}\r\n\r\n.hc-models__lib:last-child {\r\n  border-bottom: 0;\r\n}\r\n\r\n/* ==========================================================================\r\n * provider 目录：三列紧凑网格（Provider / URL / Key env）\r\n *\r\n * 整改前每一格都是 `flex: 1 1 Npx`：三列被拉到极宽，URL 与 key_env 之间出现大片\r\n * 横向空白，最右的 key_env 孤立悬浮，还没有列标题、行间几乎没有分隔。\r\n * 现在：列宽由这里统一给（中间那列承担弹性宽度），列标题与数据行共用同一份列定义，\r\n * 行高 42px + 细分隔线，key_env 与所在列左对齐、超长省略号（title 给全值）。\r\n * ========================================================================== */\r\n.hc-models__pv {\r\n  display: flex;\r\n  flex-direction: column;\r\n  min-width: 0;\r\n  /* 目录只有三列，不需要铺满整个内容区：把表宽收在一个读得舒服的量度上，\r\n     URL 列承担剩余宽度。不设上限时 URL 列会被拉到 600px+，右边又是一片空白。 */\r\n  max-width: 900px;\r\n  border: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  border-radius: var(--r-md);\r\n  overflow: hidden;\r\n}\r\n\r\n.hc-models__pv-head,\r\n.hc-models__pv-row {\r\n  display: grid;\r\n  grid-template-columns: minmax(0, 220px) minmax(0, 1fr) minmax(0, 220px);\r\n  gap: var(--s6);\r\n  align-items: center;\r\n  min-width: 0;\r\n  max-width: 100%;\r\n  padding: 0 var(--s3);\r\n}\r\n\r\n.hc-models__pv-head {\r\n  min-height: var(--s7);\r\n  background: var(--ui-bg-secondary, transparent);\r\n  border-bottom: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  font-size: var(--fs-xs);\r\n  letter-spacing: 0.02em;\r\n  color: var(--ui-text-tertiary, inherit);\r\n}\r\n\r\n.hc-models__pv-list {\r\n  display: flex;\r\n  flex-direction: column;\r\n  min-width: 0;\r\n  max-height: 420px;\r\n  overflow-y: auto;\r\n}\r\n\r\n.hc-models__pv-row {\r\n  min-height: 42px;\r\n}\r\n\r\n.hc-models__pv-row + .hc-models__pv-row {\r\n  border-top: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n}\r\n\r\n.hc-models__pv-row:nth-child(even) {\r\n  background: var(--ui-bg-quaternary, transparent);\r\n}\r\n\r\n.hc-models__pv-row:hover {\r\n  background: var(--ui-bg-tertiary, transparent);\r\n}\r\n\r\n.hc-models__pv-row--on {\r\n  background: var(--ui-bg-secondary, transparent);\r\n}\r\n\r\n.hc-models__pv-cell {\r\n  min-width: 0;\r\n  max-width: 100%;\r\n  overflow: hidden;\r\n  text-overflow: ellipsis;\r\n  white-space: nowrap;\r\n}\r\n\r\n.hc-models__pv-name {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: var(--s2);\r\n}\r\n\r\n.hc-models__pv-name-text {\r\n  min-width: 0;\r\n  overflow: hidden;\r\n  text-overflow: ellipsis;\r\n  white-space: nowrap;\r\n  font-size: var(--fs-md);\r\n  font-weight: 600;\r\n  color: var(--ui-text-primary, inherit);\r\n}\r\n\r\n.hc-models__pv-url {\r\n  font-size: var(--fs-sm);\r\n  color: var(--ui-text-tertiary, inherit);\r\n}\r\n\r\n.hc-models__pv-key {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: var(--s2);\r\n  justify-content: flex-start;\r\n}\r\n\r\n.hc-models__pv-key .hc-chip {\r\n  min-width: 0;\r\n  max-width: 100%;\r\n  overflow: hidden;\r\n  text-overflow: ellipsis;\r\n  white-space: nowrap;\r\n  display: inline-block;\r\n  line-height: 1.6;\r\n}\r\n\r\n/* 备用链编辑器 / 辅助槽位编辑器：都只是竖排的小格子，不要额外的边框噪声 */\r\n.hc-models__chain,\r\n.hc-models__aux {\r\n  min-width: 0;\r\n  max-width: 100%;\r\n}\r\n\r\n.hc-models__aux-slot {\r\n  padding: var(--s2);\r\n  border: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  border-radius: var(--r-sm);\r\n}\r\n\r\n.hc-models__aux-slot[data-models-aux-dirty='1'] {\r\n  border-color: var(--ui-accent, currentColor);\r\n}\r\n\r\n.hc-models__aux-key {\r\n  max-width: 100%;\r\n  overflow: hidden;\r\n  text-overflow: ellipsis;\r\n  white-space: nowrap;\r\n  display: inline-block;\r\n  line-height: 1.6;\r\n}\r\n\r\n@container hc (max-width: 1150px) {\r\n  /* 中等宽度：三列一起收窄，URL 仍然吃掉剩余宽度（不是把两列钉死在 220px 上） */\r\n  .hc-models__pv-head,\r\n  .hc-models__pv-row {\r\n    grid-template-columns: minmax(0, 150px) minmax(0, 1fr) minmax(0, 150px);\r\n    gap: var(--s3);\r\n  }\r\n}\r\n\r\n@container hc (max-width: 899px) {\r\n  /* 窄窗：列标题收进每一格自己的前缀，行改竖排卡片 —— 绝不出现横向滚动 */\r\n  .hc-models__pv-head {\r\n    display: none;\r\n  }\r\n\r\n  .hc-models__pv-row {\r\n    grid-template-columns: minmax(0, 1fr);\r\n    gap: var(--s1);\r\n    padding: var(--s2) var(--s3);\r\n    min-height: 0;\r\n  }\r\n\r\n  .hc-models__pv-cell {\r\n    white-space: normal;\r\n    overflow-wrap: anywhere;\r\n  }\r\n\r\n  .hc-models__pv-name {\r\n    flex-wrap: wrap;\r\n  }\r\n}\r\n\r\n\r\n/* 「当前」这类正向标记：和 .hc-chip--off 对称，仍然只用主题变量 */\r\n.hc-chip--on {\r\n  border-color: var(--ui-accent);\r\n  color: var(--ui-text-primary);\r\n}\r\n\r\n/* 写操作面板里的输入框沿用 .hc-select 的边框手感（它是 select 的样式类，input 借用） */\r\n.hc-models__switch input.hc-select {\r\n  background: var(--ui-bg-secondary);\r\n  color: inherit;\r\n}\r\n\r\n@container hc (max-width: 899px) {\r\n  /* 窄窗：任何一行都不许撑出横向滚动条 —— 长模型名 / 长路径一律就地折行 */\r\n  .hc-models,\r\n  .hc-models__target,\r\n  .hc-models__switch,\r\n  .hc-models__confirm,\r\n  .hc-models__prow,\r\n  .hc-models__lib {\r\n    min-width: 0;\r\n    max-width: 100%;\r\n    overflow-wrap: anywhere;\r\n  }\r\n\r\n  .hc-models__switch .hc-btn,\r\n  .hc-models__confirm .hc-btn {\r\n    flex: 1 1 auto;\r\n  }\r\n}\r\n\r\n/* ===========================================================================\r\n * 远端后端分区（V4b）：一屏一表，一行一个 agent\r\n *\r\n * 结构：.hc-rt > (.hc-rt__head-line 标题+摘要+刷新 / .hc-rt__hint 口径 / .hc-rt__main)\r\n *       .hc-rt__main > .hc-rt__table > (.hc-rt__head 表头 + .hc-rt__body 行)\r\n *       每行 .hc-rt__item > (.hc-rt__row 单元格网格 + 确认条 / 回执)\r\n *\r\n * 列定义只有一份 --rt-cols：表头与数据行共用（否则两套列宽，行行不对齐）。\r\n * 为什么是表格而不是卡片：老板的原话是\"页面信息密度非常低\"——9 个 agent 各占一张卡，\r\n * 一屏只看得到 2 个；一行 34px 的表在同样一屏里能放下全部 9 行 + 10 个字段。\r\n * 颜色全部走 var(--ui-*)，间距全部走 var(--s*)。\r\n * =========================================================================== */\r\n\r\n.hc-rt {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s3);\r\n  min-width: 0;\r\n  max-width: 100%;\r\n}\r\n\r\n.hc-rt__head-line {\r\n  display: flex;\r\n  align-items: center;\r\n  flex-wrap: wrap;\r\n  gap: var(--s2);\r\n  min-width: 0;\r\n}\r\n\r\n.hc-rt__summary {\r\n  display: flex;\r\n  align-items: center;\r\n  flex-wrap: wrap;\r\n  gap: var(--s1);\r\n  min-width: 0;\r\n}\r\n\r\n.hc-rt__refresh {\r\n  margin-left: auto;\r\n}\r\n\r\n.hc-rt__hint {\r\n  font-size: var(--fs-xs);\r\n  line-height: 1.5;\r\n  color: var(--ui-text-quaternary, inherit);\r\n  overflow-wrap: anywhere;\r\n}\r\n\r\n.hc-rt__main {\r\n  min-width: 0;\r\n  max-width: 100%;\r\n}\r\n\r\n.hc-rt__table {\r\n  /* 列：状态 / Agent / 端口 / PID / 连接 / 账号 / 密码 / 最近启动 / 最近停止 / 最近错误 / 操作 */\r\n  --rt-cols: 72px minmax(0, 1.1fr) 58px 70px 92px minmax(0, 0.9fr) 170px 96px 96px\r\n    minmax(0, 1fr) 128px;\r\n\r\n  display: flex;\r\n  flex-direction: column;\r\n  border: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  border-radius: var(--r-md);\r\n  overflow: hidden;\r\n}\r\n\r\n.hc-rt__head {\r\n  display: grid;\r\n  grid-template-columns: var(--rt-cols);\r\n  align-items: center;\r\n  gap: var(--s2);\r\n  min-height: var(--row-h);\r\n  padding: 0 var(--s3);\r\n  border-bottom: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  background: var(--ui-bg-secondary, transparent);\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-quaternary, inherit);\r\n  letter-spacing: 0.02em;\r\n}\r\n\r\n.hc-rt__body {\r\n  display: flex;\r\n  flex-direction: column;\r\n  min-width: 0;\r\n}\r\n\r\n.hc-rt__item {\r\n  display: flex;\r\n  flex-direction: column;\r\n  min-width: 0;\r\n}\r\n\r\n.hc-rt__item + .hc-rt__item {\r\n  border-top: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n}\r\n\r\n/* 有\"最近错误\"的行：左侧告警竖条（形状变化 + 那一列的文字，不靠颜色单独表达） */\r\n.hc-rt__item--bad {\r\n  border-left: var(--nav-mark) solid var(--ui-warning, var(--ui-orange, currentColor));\r\n}\r\n\r\n.hc-rt__row {\r\n  display: grid;\r\n  grid-template-columns: var(--rt-cols);\r\n  align-items: center;\r\n  gap: var(--s2);\r\n  min-height: calc(var(--row-h) + var(--s1));\r\n  padding: 0 var(--s3);\r\n  font-size: var(--fs-sm);\r\n}\r\n\r\n.hc-rt__row:hover {\r\n  background: var(--ui-row-hover-background, var(--ui-bg-tertiary, transparent));\r\n}\r\n\r\n.hc-rt__cell {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: var(--s1);\r\n  min-width: 0;\r\n  overflow: hidden;\r\n}\r\n\r\n/* 名称列两行：中文名在上、id 在下（一行放不下两个还都看得清） */\r\n.hc-rt__cell--name {\r\n  flex-direction: column;\r\n  align-items: flex-start;\r\n  gap: 0;\r\n}\r\n\r\n.hc-rt__label {\r\n  max-width: 100%;\r\n  overflow: hidden;\r\n  text-overflow: ellipsis;\r\n  white-space: nowrap;\r\n  font-weight: 600;\r\n  color: var(--ui-text-primary, inherit);\r\n}\r\n\r\n.hc-rt__id {\r\n  max-width: 100%;\r\n  overflow: hidden;\r\n  text-overflow: ellipsis;\r\n  white-space: nowrap;\r\n  font-size: var(--fs-xs);\r\n  font-variant-numeric: tabular-nums;\r\n  color: var(--ui-text-quaternary, inherit);\r\n}\r\n\r\n/* 窄窗才显示：宽窗那几列（端口/PID/时间/错误）收进名称下面 */\r\n.hc-rt__meta {\r\n  display: none;\r\n  flex-wrap: wrap;\r\n  gap: var(--s1);\r\n  margin-top: 2px;\r\n  min-width: 0;\r\n}\r\n\r\n.hc-rt__text {\r\n  max-width: 100%;\r\n  overflow: hidden;\r\n  text-overflow: ellipsis;\r\n  white-space: nowrap;\r\n  color: var(--ui-text-secondary, inherit);\r\n}\r\n\r\n.hc-rt__num {\r\n  font-variant-numeric: tabular-nums;\r\n  color: var(--ui-text-primary, inherit);\r\n}\r\n\r\n.hc-rt__none {\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-quaternary, inherit);\r\n  white-space: nowrap;\r\n}\r\n\r\n.hc-rt__err {\r\n  max-width: 100%;\r\n  overflow: hidden;\r\n  text-overflow: ellipsis;\r\n  white-space: nowrap;\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-warning, var(--ui-orange, inherit));\r\n}\r\n\r\n/* 密码：默认掩码（圆点，不暴露长度与首尾） */\r\n.hc-rt__masked,\r\n.hc-rt__secret {\r\n  display: inline-flex;\r\n  align-items: center;\r\n  gap: var(--s1);\r\n  min-width: 0;\r\n  max-width: 100%;\r\n}\r\n\r\n.hc-rt__mask {\r\n  letter-spacing: 0.08em;\r\n  color: var(--ui-text-quaternary, inherit);\r\n  white-space: nowrap;\r\n}\r\n\r\n/* 解密后的明文：等宽 + 描边小块，点「隐藏」立刻回到掩码 */\r\n.hc-rt__secret-text {\r\n  max-width: 96px;\r\n  overflow: hidden;\r\n  text-overflow: ellipsis;\r\n  white-space: nowrap;\r\n  padding: 0 var(--s1);\r\n  border: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  border-radius: var(--r-sm);\r\n  background: var(--ui-bg-secondary, transparent);\r\n  font-size: var(--fs-xs);\r\n  font-variant-numeric: tabular-nums;\r\n  color: var(--ui-text-primary, inherit);\r\n}\r\n\r\n.hc-rt__cell--ops {\r\n  justify-content: flex-end;\r\n  gap: var(--s1);\r\n}\r\n\r\n/* 确认条 / 回执挂在行下面（与 .hc-up__confirm / .hc-up__feedback 同一套视觉） */\r\n.hc-rt__confirm,\r\n.hc-rt__feedback {\r\n  margin: 0 var(--s3) var(--s2);\r\n}\r\n\r\n/* <900px：收列，不横向滚动。只留 状态/名称/账号/密码/操作；\r\n   端口·PID·时间·错误改用名称下面的小字（.hc-rt__meta）。 */\r\n@container hc (max-width: 899px) {\r\n  .hc-rt__table {\r\n    --rt-cols: 66px minmax(0, 1fr) minmax(0, 1fr) 152px 116px;\r\n  }\r\n\r\n  .hc-rt__cell--port,\r\n  .hc-rt__cell--pid,\r\n  .hc-rt__cell--conn,\r\n  .hc-rt__cell--time,\r\n  .hc-rt__cell--err {\r\n    display: none;\r\n  }\r\n\r\n  .hc-rt__meta {\r\n    display: flex;\r\n  }\r\n\r\n  .hc-rt__confirm .hc-btn,\r\n  .hc-rt__feedback {\r\n    flex: 1 1 auto;\r\n  }\r\n}\r\n\r\n/* 更窄：状态只留圆点，密码按钮竖排（挤不下会把行高顶开） */\r\n@container hc (max-width: 599px) {\r\n  .hc-rt__table {\r\n    --rt-cols: 20px minmax(0, 1fr) minmax(0, 1fr) 132px 104px;\r\n  }\r\n\r\n  .hc-rt__cell--status .hc-status {\r\n    font-size: 0;\r\n    gap: 0;\r\n  }\r\n}\r\n\r\n/* ==========================================================================\r\n * V6 · 模型分区（models）：**Agent 表就是页面主体** + 单个/批量共用编辑器\r\n *\r\n * 为什么加这几条：V5 的页面上方是「作用域横幅 + 表单」，下方是两栏卡片，\r\n * agent 本身要滚很久才看得到；整改后 agent 表占满整宽（左列），编辑器固定\r\n * 在右列（420px），窗口窄时自动上下叠。这里只补「表格当主体」需要的骨架，\r\n * 其余继续复用 .hc-block / .hc-rows / .hc-row / .hc-btn / .hc-chip / .hc-cards。\r\n *\r\n * 颜色只用 var(--ui-*)：本段零字面色值（构建脚本会扫描，写了就失败）。\r\n * ========================================================================== */\r\n.hc-models__tabs {\r\n  padding-bottom: var(--s2);\r\n  border-bottom: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n}\r\n\r\n.hc-models__thead {\r\n  padding-bottom: var(--s1);\r\n}\r\n\r\n/* agent 表是主体：不套 .hc-rows 的 264px 滚动上限，整表随页面走 */\r\n.hc-models__table .hc-rows {\r\n  max-height: none;\r\n}\r\n\r\n.hc-models__row {\r\n  padding: var(--s2) var(--s3);\r\n  min-height: var(--row-h);\r\n  align-items: center;\r\n}\r\n\r\n.hc-models__row--on {\r\n  background: var(--ui-row-active-background, var(--ui-bg-tertiary, transparent));\r\n}\r\n\r\n.hc-models__selbar {\r\n  padding: var(--s2) var(--s3);\r\n}\r\n\r\n.hc-models__editor {\r\n  padding: var(--s3);\r\n  border: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  border-radius: var(--r-md);\r\n  background: var(--ui-bg-secondary, transparent);\r\n}\r\n\r\n.hc-models__preview {\r\n  padding: var(--s3);\r\n  border: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  border-radius: var(--r-md);\r\n  background: var(--ui-bg-tertiary, transparent);\r\n}\r\n\r\n/* 编辑器里的下拉占满整格（.hc-select 默认只到 220px，批量表单会右半边空着） */\r\n.hc-models__editor .hc-select {\r\n  max-width: none;\r\n  width: 100%;\r\n}\r\n\r\n/* 文本输入沿用 .hc-select 的边框手感（同一个视觉，不新造一套） */\r\n.hc-input {\r\n  min-width: 0;\r\n  padding: var(--s1) var(--s2);\r\n  border: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  border-radius: var(--r-sm);\r\n  background: var(--ui-bg-quaternary, transparent);\r\n  color: var(--ui-text-primary, inherit);\r\n  font: inherit;\r\n  font-size: var(--fs-sm);\r\n  transition: border-color var(--t-fast), background-color var(--t-fast);\r\n}\r\n\r\n.hc-input:hover {\r\n  border-color: var(--ui-accent, currentColor);\r\n  background: var(--ui-bg-tertiary, transparent);\r\n}\r\n\r\n.hc-input:disabled {\r\n  cursor: not-allowed;\r\n  color: var(--ui-text-quaternary, inherit);\r\n}\r\n\r\n@container hc (max-width: 899px) {\r\n  /* 窄窗：表格与编辑器都改成竖排卡片，任何一行都不许撑出横向滚动条 */\r\n  .hc-models__table,\r\n  .hc-models__editor,\r\n  .hc-models__preview,\r\n  .hc-models__selbar,\r\n  .hc-models__thead {\r\n    min-width: 0;\r\n    max-width: 100%;\r\n    overflow-wrap: anywhere;\r\n  }\r\n\r\n  .hc-models__editor .hc-btn,\r\n  .hc-models__selbar .hc-btn {\r\n    flex: 1 1 auto;\r\n  }\r\n}\r\n\r\n/* 宽窗：Agent 表的每个格子**一行**（长值省略号 + title 兜底）。\r\n   整改前的截图里一行被折成 5~6 行，9 个 agent 就把整屏顶满了 —— 表格当主体\r\n   的前提是「一屏能扫完」。窄窗仍然竖排卡片（见上面的 @container max-width）。 */\r\n@container hc (min-width: 900px) {\r\n  .hc-models__row {\r\n    padding: var(--s1) var(--s3);\r\n  }\r\n\r\n  .hc-models__row > [data-cell] {\r\n    overflow: hidden;\r\n    text-overflow: ellipsis;\r\n    white-space: nowrap;\r\n  }\r\n\r\n  .hc-models__row > [data-cell] > div {\r\n    min-width: 0;\r\n    flex-wrap: nowrap;\r\n  }\r\n\r\n  /* 编辑器跟着滚动（表很长时不用滚回顶部才看得到表单） */\r\n  .hc-models__side {\r\n    position: sticky;\r\n    top: var(--s2);\r\n  }\r\n}\r\n\r\n/* ===========================================================================\r\n * Advisor 覆盖面矩阵 + 按 profile 设置（本轮新增）\r\n *\r\n * 结构：覆盖状态条（五档数字，各带口径）→ 覆盖矩阵（每 agent 一行 + 行内诊断）\r\n * → 原状态条 → 筛选 → 列表 → 详情 → 按 profile 的设置（含「实际生效值」两栏）。\r\n *\r\n * 状态配色只用宿主的 --ui-accent / --ui-warning 两档 + 文字弱化，**没有第三种颜色**：\r\n * 颜色是提示，判据是徽标文字与边框样式（实心 / 虚线 / 点线），色盲与深浅主题都读得出来。\r\n * 禁止字面色值（构建脚本会检查）。\r\n * =========================================================================== */\r\n\r\n.hc-adv__coverage {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s3);\r\n  min-width: 0;\r\n}\r\n\r\n/* 五档数字：窄窗一列，宽窗并排（并排才能比大小） */\r\n.hc-adv__cov-strip {\r\n  display: grid;\r\n  grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));\r\n  gap: var(--s2);\r\n  min-width: 0;\r\n}\r\n\r\n.hc-adv__cov-cell {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s1);\r\n  min-width: 0;\r\n  padding: var(--s3);\r\n  border: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  border-radius: var(--r-sm);\r\n  background: var(--ui-bg-secondary, transparent);\r\n  overflow-wrap: anywhere;\r\n}\r\n\r\n.hc-adv__cov-num {\r\n  font-size: var(--fs-xl);\r\n  font-weight: 600;\r\n  line-height: 1.15;\r\n  font-variant-numeric: tabular-nums;\r\n  color: var(--ui-text-primary, inherit);\r\n}\r\n\r\n.hc-adv__cov-label {\r\n  font-size: var(--fs-sm);\r\n  color: var(--ui-text-secondary, inherit);\r\n}\r\n\r\n/* 口径永远最弱一档：数字离开口径就是猜 */\r\n.hc-adv__cov-caliber {\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-quaternary, inherit);\r\n}\r\n\r\n/* 在用 = accent 左边条（唯一「好消息」的一档） */\r\n.hc-adv__cov-cell--active {\r\n  border-left: var(--nav-mark) solid var(--ui-accent, currentColor);\r\n}\r\n\r\n/* 有评审无台账 / 在记账不能投递 = warning 虚线（要动手，但不是错误） */\r\n.hc-adv__cov-cell--reviewing_only,\r\n.hc-adv__cov-cell--ledger_no_delivery {\r\n  border-left: var(--nav-mark) dashed var(--ui-warning, var(--ui-orange, currentColor));\r\n}\r\n\r\n.hc-adv__cov-cell--reviewing_only .hc-adv__cov-num,\r\n.hc-adv__cov-cell--ledger_no_delivery .hc-adv__cov-num {\r\n  color: var(--ui-warning, var(--ui-orange, inherit));\r\n}\r\n\r\n/* 装了未启用 / 没装 = 纯弱化（不是问题，是事实） */\r\n.hc-adv__cov-cell--installed_disabled .hc-adv__cov-num,\r\n.hc-adv__cov-cell--not_installed .hc-adv__cov-num {\r\n  color: var(--ui-text-tertiary, inherit);\r\n}\r\n\r\n.hc-adv__cov-cell--zero {\r\n  border-style: dashed;\r\n  background: transparent;\r\n}\r\n\r\n/* reviewing_only 的整幅提示：本轮排查最花时间的那一句，必须在最上面就看见 */\r\n.hc-adv__cov-alert {\r\n  padding: var(--s2) var(--s3);\r\n  border: var(--hairline) dashed var(--ui-warning, var(--ui-orange, currentColor));\r\n  border-radius: var(--r-sm);\r\n  font-size: var(--fs-sm);\r\n  color: var(--ui-warning, var(--ui-orange, inherit));\r\n  overflow-wrap: anywhere;\r\n}\r\n\r\n/* ------------------------------------------------------------------ 矩阵表 */\r\n\r\n.hc-adv__cov-table {\r\n  display: flex;\r\n  flex-direction: column;\r\n  min-width: 0;\r\n  border: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  border-radius: var(--r-sm);\r\n  overflow: hidden;\r\n}\r\n\r\n.hc-adv__cov-cell--name {\r\n  display: flex;\r\n  align-items: baseline;\r\n  gap: var(--s1);\r\n}\r\n\r\n.hc-adv__cov-tag {\r\n  padding: 0 var(--s1);\r\n  border: var(--hairline) dashed var(--ui-warning, var(--ui-orange, currentColor));\r\n  border-radius: var(--r-sm);\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-warning, var(--ui-orange, inherit));\r\n  white-space: nowrap;\r\n}\r\n\r\n/* 行内诊断：占满整行（grid-column 1/-1），长句可折行 */\r\n.hc-adv__cov-diag {\r\n  grid-column: 1 / -1;\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-quaternary, inherit);\r\n  white-space: normal;\r\n  overflow-wrap: anywhere;\r\n}\r\n\r\n.hc-adv__cov-diag--action {\r\n  color: var(--ui-warning, var(--ui-orange, inherit));\r\n}\r\n\r\n/* 状态徽标：颜色区分状态（后面的 override 段把描边去掉，只留纯色文字） */\r\n.hc-adv__cov-badge {\r\n  display: inline-block;\r\n  max-width: 100%;\r\n  padding: 0 var(--s2);\r\n  border-radius: var(--r-sm);\r\n  font-size: var(--fs-xs);\r\n  white-space: nowrap;\r\n  overflow: hidden;\r\n  text-overflow: ellipsis;\r\n  color: var(--ui-text-secondary, inherit);\r\n}\r\n\r\n.hc-adv__cov-badge--active {\r\n  color: var(--ui-accent, inherit);\r\n}\r\n\r\n.hc-adv__cov-badge--reviewing_only,\r\n.hc-adv__cov-badge--ledger_no_delivery {\r\n  color: var(--ui-warning, var(--ui-orange, inherit));\r\n}\r\n\r\n.hc-adv__cov-badge--installed_disabled,\r\n.hc-adv__cov-badge--not_installed {\r\n  color: var(--ui-text-quaternary, inherit);\r\n}\r\n\r\n/* 窄容器：矩阵从表格折叠成卡片（一行一个 agent，诊断独占一行） */\r\n@container hc (max-width: 899px) {\r\n  .hc-adv__cov-table {\r\n    border: none;\r\n  }\r\n\r\n  .hc-adv__cov-cell--name {\r\n    flex: 1 1 100%;\r\n  }\r\n\r\n  .hc-adv__cov-diag {\r\n    flex: 1 1 100%;\r\n  }\r\n}\r\n\r\n/* ------------------------------------------- 来源列里的「目标来源 / 台账文件 */\r\n\r\n.hc-adv__profsrc {\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-quaternary, inherit);\r\n  white-space: nowrap;\r\n}\r\n\r\n/* 目标来源：未知时不隐藏、不加红，只弱化 —— 「未知目标」本身就是一条信息 */\r\n.hc-adv__goal {\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-tertiary, inherit);\r\n  white-space: nowrap;\r\n  overflow: hidden;\r\n  text-overflow: ellipsis;\r\n  /* nowrap 的 min-content 会超过单元格宽度：不夹住 max-width 的话，长 goal_ref\r\n     （用户原话前 80 字）会把元素盒子撑到可视边界外，尽管单元格已经 overflow:hidden。\r\n     夹住之后 ellipsis 才真正生效，1280/1350/900 三档都不再溢出。 */\r\n  display: block;\r\n  min-width: 0;\r\n  max-width: 100%;\r\n}\r\n\r\n.hc-adv__goal--unknown {\r\n  border-bottom: var(--hairline) dotted var(--ui-stroke-secondary, currentColor);\r\n}\r\n\r\n.hc-adv__fact--goal {\r\n  color: var(--ui-text-secondary, inherit);\r\n}\r\n\r\n.hc-adv__fact--goal[data-goal-source='unknown'] {\r\n  border-bottom: var(--hairline) dotted var(--ui-stroke-secondary, currentColor);\r\n}\r\n\r\n/* ------------------------------------------------ 设置的「实际生效值」两栏 */\r\n\r\n.hc-adv__applied {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s1);\r\n  min-width: 0;\r\n  padding: var(--s2) var(--s3);\r\n  border: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  border-radius: var(--r-sm);\r\n  background: var(--ui-bg-tertiary, transparent);\r\n}\r\n\r\n.hc-adv__applied-title {\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-quaternary, inherit);\r\n}\r\n\r\n.hc-adv__applied-rows {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s1);\r\n  min-width: 0;\r\n}\r\n\r\n.hc-adv__applied-row {\r\n  display: flex;\r\n  align-items: baseline;\r\n  flex-wrap: wrap;\r\n  gap: var(--s1) var(--s2);\r\n  min-width: 0;\r\n  font-size: var(--fs-sm);\r\n}\r\n\r\n.hc-adv__applied-key {\r\n  min-width: 150px;\r\n  color: var(--ui-text-quaternary, inherit);\r\n  font-size: var(--fs-xs);\r\n}\r\n\r\n.hc-adv__applied-value {\r\n  color: var(--ui-text-primary, inherit);\r\n  font-variant-numeric: tabular-nums;\r\n  overflow-wrap: anywhere;\r\n}\r\n\r\n.hc-adv__applied-disk {\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-quaternary, inherit);\r\n  font-variant-numeric: tabular-nums;\r\n}\r\n\r\n/* 窄容器：设置表单的标签不再占固定宽度（否则输入框只剩十几像素） */\r\n@container hc (max-width: 899px) {\r\n  .hc-adv__field-label {\r\n    min-width: 0;\r\n    flex: 1 1 100%;\r\n  }\r\n\r\n  .hc-adv__applied-key {\r\n    min-width: 0;\r\n    flex: 1 1 100%;\r\n  }\r\n}\r\n\r\n/* ===========================================================================\r\n * Advisor 本轮补齐的四块（t_56b4ee48）：评审模式 / 评审流水与错误 /\r\n * 设置逐项来源层 + 总闸 / 建议正文结构自检。\r\n *\r\n * 规矩与上文一致：颜色只走 var(--ui-*)；状态不只靠颜色（虚线 / 实线 / 点线 + 文字）；\r\n * 任何一档都不出现横向滚动条（宽窗用 grid，窄窗塌成一列）。\r\n * =========================================================================== */\r\n\r\n/* ------------------------------------------------ 评审模式（提示词模式） */\r\n\r\n.hc-adv__modes {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s2);\r\n  min-width: 0;\r\n  padding: var(--s4);\r\n  border: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  border-radius: var(--r-md);\r\n}\r\n\r\n/* 「当前：X」是读数，不是开关：实心描边 + 强调色 */\r\n.hc-adv__mode-now {\r\n  padding: 0 var(--s2);\r\n  border: var(--hairline) solid var(--ui-accent, currentColor);\r\n  border-radius: var(--r-sm);\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-accent, inherit);\r\n  white-space: nowrap;\r\n}\r\n\r\n/* 「不支持切换」用虚线 + 弱化文字：和可点的控件刻意不同形 */\r\n.hc-adv__mode-fixed {\r\n  padding: 0 var(--s2);\r\n  border: var(--hairline) dashed var(--ui-stroke-secondary, currentColor);\r\n  border-radius: var(--r-sm);\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-quaternary, inherit);\r\n  white-space: nowrap;\r\n}\r\n\r\n.hc-adv__mode-why {\r\n  font-size: var(--fs-sm);\r\n  color: var(--ui-text-secondary, inherit);\r\n  overflow-wrap: anywhere;\r\n}\r\n\r\n.hc-adv__mode-table {\r\n  display: flex;\r\n  flex-direction: column;\r\n  min-width: 0;\r\n  border: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  border-radius: var(--r-sm);\r\n  overflow: hidden;\r\n}\r\n\r\n.hc-adv__mode-row {\r\n  display: grid;\r\n  grid-template-columns: minmax(88px, 0.8fr) minmax(96px, 0.9fr) minmax(180px, 2fr);\r\n  gap: var(--s2);\r\n  align-items: baseline;\r\n  min-width: 0;\r\n  padding: var(--s2) var(--s3);\r\n  border-top: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  font-size: var(--fs-sm);\r\n}\r\n\r\n.hc-adv__mode-row:first-child {\r\n  border-top: none;\r\n}\r\n\r\n/* 当前在用的那一档：左边条（和覆盖条 active 同一套语义） */\r\n.hc-adv__mode-row--now {\r\n  border-left: var(--nav-mark) solid var(--ui-accent, currentColor);\r\n  background: var(--ui-row-active-background, transparent);\r\n}\r\n\r\n.hc-adv__mode-name {\r\n  font-weight: 600;\r\n  color: var(--ui-text-primary, inherit);\r\n  white-space: nowrap;\r\n}\r\n\r\n.hc-adv__mode-when {\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-secondary, inherit);\r\n  overflow-wrap: anywhere;\r\n}\r\n\r\n.hc-adv__mode-crit {\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-tertiary, inherit);\r\n  overflow-wrap: anywhere;\r\n}\r\n\r\n/* 源码位置：等宽小字，长路径自己折行（绝不撑出横向滚动） */\r\n.hc-adv__mode-src {\r\n  grid-column: 1 / -1;\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-quaternary, inherit);\r\n  overflow-wrap: anywhere;\r\n}\r\n\r\n/* 「不支持切换」的整幅说明：虚线框，与「错误」区分（不是红，是提示） */\r\n.hc-adv__mode-fixedbox {\r\n  padding: var(--s2) var(--s3);\r\n  border: var(--hairline) dashed var(--ui-warning, var(--ui-orange, currentColor));\r\n  border-radius: var(--r-sm);\r\n  font-size: var(--fs-sm);\r\n  color: var(--ui-warning, var(--ui-orange, inherit));\r\n  overflow-wrap: anywhere;\r\n}\r\n\r\n.hc-adv__mode-evidence,\r\n.hc-adv__mode-branches,\r\n.hc-adv__mode-knobs,\r\n.hc-adv__hostlayers {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s1);\r\n  min-width: 0;\r\n  padding: var(--s2) var(--s3);\r\n  border: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  border-radius: var(--r-sm);\r\n  background: var(--ui-bg-tertiary, transparent);\r\n}\r\n\r\n/* 两个提示词分支：本轮落在哪个分支由 --now 左边条指出（不只靠颜色：文字也标了） */\r\n/* 模式块的 agent 作用域：只显示，不放第二个选择器（切换在下面的策略设置里） */\r\n.hc-adv__mode-agent {\r\n  display: flex;\r\n  gap: var(--s2);\r\n  align-items: baseline;\r\n  flex-wrap: wrap;\r\n  min-width: 0;\r\n}\r\n\r\n.hc-adv__mode-branch {\r\n  display: grid;\r\n  grid-template-columns: minmax(96px, 0.8fr) minmax(200px, 2fr);\r\n  gap: var(--s2);\r\n  align-items: baseline;\r\n  min-width: 0;\r\n  padding-left: var(--s2);\r\n  border-left: var(--nav-mark) solid transparent;\r\n  font-size: var(--fs-sm);\r\n}\r\n\r\n.hc-adv__mode-branch--now {\r\n  border-left-color: var(--ui-accent, currentColor);\r\n}\r\n\r\n/* ------------------------------------------------ 评审模式设置字段（策略设置里） */\r\n\r\n.hc-adv__modefield {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s2);\r\n  min-width: 0;\r\n  padding: var(--s3);\r\n  border: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  border-radius: var(--r-sm);\r\n  background: var(--ui-bg-tertiary, transparent);\r\n}\r\n\r\n.hc-adv__modefield-head {\r\n  display: flex;\r\n  gap: var(--s2);\r\n  align-items: baseline;\r\n  flex-wrap: wrap;\r\n}\r\n\r\n.hc-adv__modefield-pick {\r\n  display: flex;\r\n  gap: var(--s2);\r\n  align-items: center;\r\n  flex-wrap: wrap;\r\n}\r\n\r\n/* 「设置值 / 生效值 / 来源层」三个读数：一律是描边小标签，不做成按钮 */\r\n.hc-adv__modefield-facts {\r\n  display: flex;\r\n  gap: var(--s2);\r\n  flex-wrap: wrap;\r\n  min-width: 0;\r\n}\r\n\r\n.hc-adv__modefield-fact {\r\n  padding: 0 var(--s2);\r\n  border: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  border-radius: var(--r-sm);\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-secondary, inherit);\r\n  overflow-wrap: anywhere;\r\n}\r\n\r\n.hc-adv__modefield-rules {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s1);\r\n  min-width: 0;\r\n}\r\n\r\n.hc-adv__modefield-rules-title {\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-quaternary, inherit);\r\n  letter-spacing: 0.02em;\r\n}\r\n\r\n.hc-adv__modefield-rule {\r\n  display: grid;\r\n  grid-template-columns: minmax(120px, 0.9fr) minmax(140px, 1fr) minmax(180px, 2fr);\r\n  gap: var(--s2);\r\n  align-items: baseline;\r\n  min-width: 0;\r\n  padding: var(--s1) var(--s2);\r\n  border-left: var(--nav-mark) solid transparent;\r\n  font-size: var(--fs-sm);\r\n}\r\n\r\n.hc-adv__modefield-rule--now {\r\n  border-left-color: var(--ui-accent, currentColor);\r\n  background: var(--ui-row-active-background, transparent);\r\n}\r\n\r\n.hc-adv__modefield-rule-name {\r\n  font-weight: 600;\r\n  color: var(--ui-text-primary, inherit);\r\n}\r\n\r\n.hc-adv__modefield-rule-when,\r\n.hc-adv__modefield-rule-crit {\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-tertiary, inherit);\r\n  overflow-wrap: anywhere;\r\n}\r\n\r\n/* 强制档（target / conservative）在每 agent 表里用强调色 + 加粗，和 auto 一眼可分 */\r\n.hc-adv__mode-forced {\r\n  color: var(--ui-accent, inherit);\r\n  font-weight: 600;\r\n}\r\n\r\n.hc-adv__mode-knob-resolved {\r\n  color: var(--ui-text-secondary, inherit);\r\n}\r\n\r\n.hc-adv__mode-ev-title {\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-quaternary, inherit);\r\n  letter-spacing: 0.02em;\r\n}\r\n\r\n.hc-adv__mode-knob-row {\r\n  display: grid;\r\n  grid-template-columns: minmax(72px, 0.9fr) minmax(72px, 0.8fr) minmax(64px, 0.7fr)\r\n    minmax(64px, 0.7fr) minmax(72px, 1.1fr) minmax(64px, 0.8fr) minmax(40px, 0.5fr);\r\n  gap: var(--s2);\r\n  align-items: baseline;\r\n  min-width: 0;\r\n  font-size: var(--fs-sm);\r\n  color: var(--ui-text-secondary, inherit);\r\n}\r\n\r\n.hc-adv__mode-knob-row > span {\r\n  min-width: 0;\r\n  overflow: hidden;\r\n  text-overflow: ellipsis;\r\n  white-space: nowrap;\r\n}\r\n\r\n.hc-adv__mode-knob-row--head {\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-quaternary, inherit);\r\n}\r\n\r\n/* 关着的 agent：虚线 + warning 文字（不只靠颜色） */\r\n.hc-adv__off {\r\n  color: var(--ui-warning, var(--ui-orange, inherit));\r\n  border-bottom: var(--hairline) dashed var(--ui-warning, var(--ui-orange, currentColor));\r\n}\r\n\r\n/* ------------------------------------------------ 评审流水与错误 */\r\n\r\n.hc-adv__trail {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s2);\r\n  min-width: 0;\r\n  padding: var(--s4);\r\n  border: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  border-radius: var(--r-md);\r\n}\r\n\r\n.hc-adv__err-list,\r\n.hc-adv__loglist,\r\n.hc-adv__inflight,\r\n.hc-adv__trail-rows {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s1);\r\n  min-width: 0;\r\n}\r\n\r\n.hc-adv__err-head,\r\n.hc-adv__log-head,\r\n.hc-adv__inflight-head {\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-warning, var(--ui-orange, inherit));\r\n  overflow-wrap: anywhere;\r\n}\r\n\r\n/* 一条错误：虚线框（提示「要看」，不是「坏了」） */\r\n.hc-adv__err-item {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s1);\r\n  min-width: 0;\r\n  padding: var(--s2) var(--s3);\r\n  border: var(--hairline) dashed var(--ui-warning, var(--ui-orange, currentColor));\r\n  border-radius: var(--r-sm);\r\n}\r\n\r\n/* 日志旁证：点线框（和台账里的错误区分开 —— 它不是台账） */\r\n.hc-adv__err-item--log {\r\n  border-style: dotted;\r\n  background: var(--ui-bg-tertiary, transparent);\r\n}\r\n\r\n.hc-adv__err-title {\r\n  display: flex;\r\n  align-items: baseline;\r\n  flex-wrap: wrap;\r\n  gap: var(--s1) var(--s2);\r\n  min-width: 0;\r\n}\r\n\r\n.hc-adv__err-kind {\r\n  padding: 0 var(--s2);\r\n  border: var(--hairline) solid var(--ui-warning, var(--ui-orange, currentColor));\r\n  border-radius: var(--r-sm);\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-warning, var(--ui-orange, inherit));\r\n  white-space: nowrap;\r\n}\r\n\r\n.hc-adv__err-read {\r\n  font-size: var(--fs-sm);\r\n  color: var(--ui-text-primary, inherit);\r\n  overflow-wrap: anywhere;\r\n}\r\n\r\n.hc-adv__err-raw {\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-quaternary, inherit);\r\n  font-family: var(--ui-font-mono, monospace);\r\n  overflow-wrap: anywhere;\r\n}\r\n\r\n.hc-adv__err-hints {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 2px;\r\n  margin: 0;\r\n  padding-left: var(--s4);\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-secondary, inherit);\r\n  overflow-wrap: anywhere;\r\n}\r\n\r\n.hc-adv__inflight-row,\r\n.hc-adv__trail-row {\r\n  display: flex;\r\n  align-items: baseline;\r\n  flex-wrap: wrap;\r\n  gap: var(--s1) var(--s2);\r\n  min-width: 0;\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-secondary, inherit);\r\n}\r\n\r\n.hc-adv__outcome {\r\n  padding: 0 var(--s2);\r\n  border: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  border-radius: 999px;\r\n  font-size: var(--fs-xs);\r\n  white-space: nowrap;\r\n}\r\n\r\n.hc-adv__outcome--advised {\r\n  border-color: var(--ui-accent, currentColor);\r\n  color: var(--ui-accent, inherit);\r\n}\r\n\r\n.hc-adv__outcome--error {\r\n  border-style: dashed;\r\n  border-color: var(--ui-warning, var(--ui-orange, currentColor));\r\n  color: var(--ui-warning, var(--ui-orange, inherit));\r\n}\r\n\r\n.hc-adv__outcome--started,\r\n.hc-adv__outcome--skipped {\r\n  border-style: dotted;\r\n  color: var(--ui-text-quaternary, inherit);\r\n}\r\n\r\n/* ------------------------------------------------ 建议正文结构自检 */\r\n\r\n.hc-adv__struct {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s1);\r\n  min-width: 0;\r\n  padding: var(--s2) var(--s3);\r\n  border: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  border-radius: var(--r-sm);\r\n  background: var(--ui-bg-tertiary, transparent);\r\n}\r\n\r\n.hc-adv__struct-head {\r\n  display: flex;\r\n  align-items: baseline;\r\n  flex-wrap: wrap;\r\n  gap: var(--s1) var(--s2);\r\n  min-width: 0;\r\n}\r\n\r\n.hc-adv__struct-title {\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-quaternary, inherit);\r\n  letter-spacing: 0.02em;\r\n}\r\n\r\n.hc-adv__struct-cells {\r\n  display: flex;\r\n  flex-wrap: wrap;\r\n  gap: var(--s1);\r\n  min-width: 0;\r\n}\r\n\r\n/* 有 = 实线 + ✓；缺 = 虚线 + 「缺」字（形状与文字双通道） */\r\n.hc-adv__struct-cell {\r\n  display: inline-flex;\r\n  align-items: baseline;\r\n  gap: var(--s1);\r\n  padding: 0 var(--s2);\r\n  border: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  border-radius: var(--r-sm);\r\n  font-size: var(--fs-xs);\r\n  white-space: nowrap;\r\n}\r\n\r\n.hc-adv__struct-cell--yes {\r\n  border-color: var(--ui-accent, currentColor);\r\n  color: var(--ui-accent, inherit);\r\n}\r\n\r\n.hc-adv__struct-cell--no {\r\n  border-style: dashed;\r\n  color: var(--ui-warning, var(--ui-orange, inherit));\r\n}\r\n\r\n.hc-adv__struct-mark {\r\n  font-variant-numeric: tabular-nums;\r\n}\r\n\r\n/* 列表里「未点名」的小标记：点线框，最弱一档但看得见 */\r\n.hc-adv__nontarget {\r\n  padding: 0 var(--s1);\r\n  border: var(--hairline) dotted var(--ui-warning, var(--ui-orange, currentColor));\r\n  border-radius: var(--r-sm);\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-warning, var(--ui-orange, inherit));\r\n  white-space: nowrap;\r\n}\r\n\r\n/* 「只引了原话」：引号不算点名（插件闸门只认四种识别形态）。用中性虚线与\r\n   「没点名」的警示色区分开 —— 文字是主通道，颜色只是辅证。 */\r\n.hc-adv__nontarget--quote {\r\n  border-style: dashed;\r\n  border-color: var(--ui-border);\r\n  color: inherit;\r\n  opacity: 0.82;\r\n}\r\n\r\n/* ------------------------------------------------ 设置：逐项来源层表 */\r\n\r\n.hc-adv__stable {\r\n  display: flex;\r\n  flex-direction: column;\r\n  min-width: 0;\r\n  border: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  border-radius: var(--r-sm);\r\n  overflow: hidden;\r\n}\r\n\r\n.hc-adv__stable-row {\r\n  display: grid;\r\n  grid-template-columns: minmax(96px, 1.1fr) minmax(64px, 0.8fr) minmax(72px, 0.9fr)\r\n    minmax(56px, 0.7fr) minmax(56px, 0.7fr);\r\n  gap: var(--s2);\r\n  align-items: baseline;\r\n  min-width: 0;\r\n  padding: var(--s1) var(--s3);\r\n  border-top: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  font-size: var(--fs-sm);\r\n}\r\n\r\n.hc-adv__stable-row:first-child {\r\n  border-top: none;\r\n}\r\n\r\n.hc-adv__stable-row--head {\r\n  background: var(--ui-bg-tertiary, transparent);\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-quaternary, inherit);\r\n}\r\n\r\n.hc-adv__stable-row--ro {\r\n  border-style: dashed;\r\n  background: var(--ui-bg-tertiary, transparent);\r\n}\r\n\r\n.hc-adv__stable-row > span {\r\n  min-width: 0;\r\n  overflow: hidden;\r\n  text-overflow: ellipsis;\r\n  white-space: nowrap;\r\n}\r\n\r\n.hc-adv__stable-key {\r\n  font-family: var(--ui-font-mono, monospace);\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-secondary, inherit);\r\n}\r\n\r\n.hc-adv__stable-value {\r\n  color: var(--ui-text-primary, inherit);\r\n  font-variant-numeric: tabular-nums;\r\n}\r\n\r\n/* 来源层徽标：三层形状不同（实线 / 点线 / 虚线） */\r\n.hc-adv__stable-src {\r\n  justify-self: start;\r\n  padding: 0 var(--s1);\r\n  border: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  border-radius: var(--r-sm);\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-secondary, inherit);\r\n}\r\n\r\n.hc-adv__stable-src--default {\r\n  border-style: dotted;\r\n  color: var(--ui-text-quaternary, inherit);\r\n}\r\n\r\n.hc-adv__stable-src--settings_file {\r\n  border-color: var(--ui-accent, currentColor);\r\n  color: var(--ui-accent, inherit);\r\n}\r\n\r\n.hc-adv__stable-src--forced_constant {\r\n  border-style: dashed;\r\n  color: var(--ui-warning, var(--ui-orange, inherit));\r\n}\r\n\r\n.hc-adv__stable-disk,\r\n.hc-adv__stable-default {\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-quaternary, inherit);\r\n  font-variant-numeric: tabular-nums;\r\n}\r\n\r\n/* ------------------------------------------------ 设置：总闸（enabled） */\r\n\r\n.hc-adv__gate {\r\n  padding: var(--s2) var(--s3);\r\n  border: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  border-radius: var(--r-sm);\r\n  font-size: var(--fs-sm);\r\n  overflow-wrap: anywhere;\r\n}\r\n\r\n/* 关着 = 虚线 + warning；开着 = 实线；待保存 = 粗描边 */\r\n.hc-adv__gate--off {\r\n  border-style: dashed;\r\n  border-color: var(--ui-warning, var(--ui-orange, currentColor));\r\n  color: var(--ui-warning, var(--ui-orange, inherit));\r\n  background: var(--ui-bg-tertiary, transparent);\r\n}\r\n\r\n.hc-adv__gate--on {\r\n  border-color: var(--ui-accent, currentColor);\r\n  color: var(--ui-text-secondary, inherit);\r\n}\r\n\r\n.hc-adv__gate--pending {\r\n  border-width: 2px;\r\n}\r\n\r\n.hc-adv__gate-note {\r\n  padding: var(--s1) var(--s2);\r\n  border-left: var(--nav-mark) solid var(--ui-warning, var(--ui-orange, currentColor));\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-warning, var(--ui-orange, inherit));\r\n  overflow-wrap: anywhere;\r\n}\r\n\r\n.hc-adv__hostlayer-row {\r\n  display: grid;\r\n  grid-template-columns: minmax(120px, 1.2fr) minmax(72px, 0.8fr) minmax(120px, 1.6fr);\r\n  gap: var(--s2);\r\n  align-items: baseline;\r\n  min-width: 0;\r\n  font-size: var(--fs-sm);\r\n  color: var(--ui-text-secondary, inherit);\r\n}\r\n\r\n.hc-adv__hostlayer-row > span {\r\n  min-width: 0;\r\n  overflow-wrap: anywhere;\r\n}\r\n\r\n/* 窄容器：上面这些表全部塌成一列（没有横向滚动条） */\r\n@container hc (max-width: 899px) {\r\n  .hc-adv__mode-row,\r\n  .hc-adv__mode-knob-row,\r\n  .hc-adv__stable-row,\r\n  .hc-adv__hostlayer-row {\r\n    grid-template-columns: minmax(0, 1fr);\r\n    gap: var(--s1);\r\n  }\r\n\r\n  .hc-adv__stable-row > span,\r\n  .hc-adv__mode-knob-row > span {\r\n    white-space: normal;\r\n    overflow-wrap: anywhere;\r\n  }\r\n\r\n  .hc-adv__mode-src {\r\n    grid-column: auto;\r\n  }\r\n\r\n  .hc-adv__stable-row--head {\r\n    display: none;\r\n  }\r\n}\r\n\r\n/* ------------------------------------------------------------ 自动命名分区 */\r\n/*\r\n * hermes-auto-titler 面板：监控（失败率是主角）+ 按 config_schema 动态渲染的参数表。\r\n * 颜色一律走 var(--ui-*)；形状也承担信息（虚线框 = 需要注意，粗边框 = 正在编辑），\r\n * 不只靠颜色区分，色盲用户也能读。\r\n */\r\n.hc-atl {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s4);\r\n  min-width: 0;\r\n}\r\n\r\n.hc-atl__tabs {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: var(--s2);\r\n  flex-wrap: wrap;\r\n  border-bottom: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  padding-bottom: var(--s2);\r\n}\r\n\r\n.hc-atl__tab {\r\n  appearance: none;\r\n  border: var(--hairline) solid transparent;\r\n  border-radius: var(--r-sm);\r\n  background: transparent;\r\n  color: var(--ui-text-secondary, inherit);\r\n  font: inherit;\r\n  font-size: var(--fs-md);\r\n  padding: var(--s1) var(--s3);\r\n  cursor: pointer;\r\n  transition: border-color var(--t-fast), color var(--t-fast);\r\n}\r\n\r\n.hc-atl__tab:hover {\r\n  color: var(--ui-text-primary, inherit);\r\n  border-color: var(--ui-stroke-secondary, currentColor);\r\n}\r\n\r\n.hc-atl__tab--active {\r\n  color: var(--ui-text-primary, inherit);\r\n  font-weight: 600;\r\n  border-color: var(--ui-accent, currentColor);\r\n}\r\n\r\n.hc-atl__tabs-right {\r\n  margin-left: auto;\r\n  display: flex;\r\n  align-items: center;\r\n  gap: var(--s2);\r\n}\r\n\r\n.hc-atl__stack {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s4);\r\n  min-width: 0;\r\n}\r\n\r\n.hc-atl__grid {\r\n  display: grid;\r\n  grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));\r\n  gap: var(--s4);\r\n  min-width: 0;\r\n}\r\n\r\n.hc-atl__panel {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s3);\r\n  min-width: 0;\r\n  padding: var(--s4);\r\n  border: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  border-radius: var(--r-md);\r\n  background: var(--ui-bg-secondary, transparent);\r\n}\r\n\r\n.hc-atl__panel-head {\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: space-between;\r\n  gap: var(--s2);\r\n  flex-wrap: wrap;\r\n}\r\n\r\n.hc-atl__panel-actions {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: var(--s3);\r\n}\r\n\r\n.hc-atl__panel-title {\r\n  font-size: var(--fs-lg);\r\n  font-weight: 600;\r\n  color: var(--ui-text-primary, inherit);\r\n}\r\n\r\n.hc-atl__sub-title {\r\n  font-size: var(--fs-sm);\r\n  font-weight: 600;\r\n  color: var(--ui-text-secondary, inherit);\r\n  margin-top: var(--s1);\r\n}\r\n\r\n/* 健康度大条：失败率单独占一行，过 50% 换虚线 + 警示色（形状也变了） */\r\n.hc-atl__banner {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s3);\r\n  padding: var(--s4);\r\n  border: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  border-radius: var(--r-md);\r\n  background: var(--ui-bg-tertiary, transparent);\r\n}\r\n\r\n.hc-atl__banner--bad {\r\n  border-style: dashed;\r\n  border-color: var(--ui-warning, var(--ui-orange, currentColor));\r\n  border-width: 2px;\r\n}\r\n\r\n.hc-atl__banner-head {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: var(--s4);\r\n  flex-wrap: wrap;\r\n}\r\n\r\n.hc-atl__banner-rate {\r\n  font-size: var(--fs-xl);\r\n  font-weight: 700;\r\n  line-height: 1.1;\r\n  font-variant-numeric: tabular-nums;\r\n  color: var(--ui-text-primary, inherit);\r\n}\r\n\r\n.hc-atl__banner--bad .hc-atl__banner-rate {\r\n  color: var(--ui-warning, var(--ui-orange, inherit));\r\n}\r\n\r\n.hc-atl__banner-copy {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s1);\r\n  min-width: 0;\r\n}\r\n\r\n.hc-atl__banner-title {\r\n  font-size: var(--fs-md);\r\n  font-weight: 600;\r\n  color: var(--ui-text-primary, inherit);\r\n}\r\n\r\n.hc-atl__banner-sub {\r\n  font-size: var(--fs-sm);\r\n  color: var(--ui-text-secondary, inherit);\r\n}\r\n\r\n.hc-atl__diagnosis {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s2);\r\n  padding: var(--s3);\r\n  border: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  border-radius: var(--r-sm);\r\n  background: var(--ui-bg-quaternary, transparent);\r\n}\r\n\r\n.hc-atl__diagnosis-head {\r\n  font-size: var(--fs-md);\r\n  font-weight: 600;\r\n  color: var(--ui-text-primary, inherit);\r\n}\r\n\r\n.hc-atl__diagnosis-body,\r\n.hc-atl__diagnosis-note {\r\n  font-size: var(--fs-sm);\r\n  color: var(--ui-text-secondary, inherit);\r\n  line-height: 1.6;\r\n}\r\n\r\n.hc-atl__diagnosis-fix {\r\n  font-size: var(--fs-sm);\r\n  color: var(--ui-text-quaternary, inherit);\r\n}\r\n\r\n.hc-atl__diagnosis-list {\r\n  margin: 0;\r\n  padding-left: var(--s5);\r\n  font-size: var(--fs-sm);\r\n  color: var(--ui-text-secondary, inherit);\r\n}\r\n\r\n.hc-atl__stats {\r\n  display: grid;\r\n  grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));\r\n  gap: var(--s3);\r\n  min-width: 0;\r\n}\r\n\r\n.hc-atl__stat {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s1);\r\n  min-width: 0;\r\n  padding: var(--s3);\r\n  border: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  border-radius: var(--r-sm);\r\n}\r\n\r\n.hc-atl__stat--good {\r\n  border-left: 3px solid var(--ui-accent, currentColor);\r\n}\r\n\r\n.hc-atl__stat--bad {\r\n  border-left: 3px dashed var(--ui-warning, var(--ui-orange, currentColor));\r\n}\r\n\r\n.hc-atl__stat-value {\r\n  font-size: var(--fs-xl);\r\n  font-weight: 600;\r\n  line-height: 1.2;\r\n  font-variant-numeric: tabular-nums;\r\n  color: var(--ui-text-primary, inherit);\r\n  overflow-wrap: anywhere;\r\n}\r\n\r\n.hc-atl__stat-label {\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-quaternary, inherit);\r\n  letter-spacing: 0.02em;\r\n}\r\n\r\n.hc-atl__stat-hint {\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-quaternary, inherit);\r\n  overflow-wrap: anywhere;\r\n}\r\n\r\n.hc-atl__kv {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s1);\r\n}\r\n\r\n.hc-atl__kv-row {\r\n  display: flex;\r\n  gap: var(--s2);\r\n  align-items: baseline;\r\n  font-size: var(--fs-sm);\r\n  min-width: 0;\r\n}\r\n\r\n.hc-atl__kv-key {\r\n  flex: 0 0 96px;\r\n  color: var(--ui-text-quaternary, inherit);\r\n  font-size: var(--fs-xs);\r\n  letter-spacing: 0.02em;\r\n}\r\n\r\n.hc-atl__kv-value {\r\n  min-width: 0;\r\n  color: var(--ui-text-primary, inherit);\r\n  overflow-wrap: anywhere;\r\n}\r\n\r\n.hc-atl__kv-value--good {\r\n  color: var(--ui-accent, inherit);\r\n}\r\n\r\n.hc-atl__kv-value--bad {\r\n  color: var(--ui-warning, var(--ui-orange, inherit));\r\n}\r\n\r\n.hc-atl__kv-value--warn {\r\n  color: var(--ui-warning, var(--ui-orange, inherit));\r\n}\r\n\r\n.hc-atl__kv-value--muted {\r\n  color: var(--ui-text-quaternary, inherit);\r\n}\r\n\r\n.hc-atl__chip {\r\n  display: inline-flex;\r\n  align-items: center;\r\n  gap: var(--s1);\r\n  padding: 1px var(--s2);\r\n  border: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  border-radius: 999px;\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-secondary, inherit);\r\n  white-space: nowrap;\r\n}\r\n\r\n.hc-atl__chip--warn {\r\n  border-style: dashed;\r\n  border-color: var(--ui-warning, var(--ui-orange, currentColor));\r\n  color: var(--ui-warning, var(--ui-orange, inherit));\r\n}\r\n\r\n.hc-atl__chip--dirty {\r\n  border-color: var(--ui-accent, currentColor);\r\n  color: var(--ui-accent, inherit);\r\n}\r\n\r\n/* 失败原因条：长度 = 占比；invalid payload 用警示色 + 虚线边框（不只靠颜色） */\r\n.hc-atl__bars {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s2);\r\n}\r\n\r\n.hc-atl__bar-row {\r\n  display: grid;\r\n  grid-template-columns: minmax(160px, 220px) minmax(60px, 1fr) auto minmax(120px, 240px);\r\n  align-items: center;\r\n  gap: var(--s2);\r\n  min-width: 0;\r\n  font-size: var(--fs-sm);\r\n}\r\n\r\n.hc-atl__bar-key {\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-secondary, inherit);\r\n  overflow-wrap: anywhere;\r\n}\r\n\r\n.hc-atl__bar-track {\r\n  height: 10px;\r\n  border-radius: 999px;\r\n  background: var(--ui-bg-quaternary, transparent);\r\n  border: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  overflow: hidden;\r\n  min-width: 0;\r\n}\r\n\r\n.hc-atl__bar-fill {\r\n  height: 100%;\r\n  background: var(--ui-text-quaternary, currentColor);\r\n}\r\n\r\n.hc-atl__bar-fill--bad {\r\n  background: var(--ui-warning, var(--ui-orange, currentColor));\r\n}\r\n\r\n.hc-atl__bar-fill--warn {\r\n  background: var(--ui-accent, currentColor);\r\n}\r\n\r\n.hc-atl__bar-count {\r\n  font-variant-numeric: tabular-nums;\r\n  color: var(--ui-text-primary, inherit);\r\n  white-space: nowrap;\r\n}\r\n\r\n.hc-atl__bar-label {\r\n  color: var(--ui-text-quaternary, inherit);\r\n  overflow-wrap: anywhere;\r\n}\r\n\r\n/* 表格：窄容器下退化成两列（键 / 值），不出现横向滚动条 */\r\n.hc-atl__table {\r\n  display: flex;\r\n  flex-direction: column;\r\n  border: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  border-radius: var(--r-sm);\r\n  overflow: hidden;\r\n}\r\n\r\n.hc-atl__table-head,\r\n.hc-atl__table-row {\r\n  display: grid;\r\n  grid-template-columns: minmax(90px, 140px) minmax(80px, 1.4fr) 72px 76px minmax(80px, 120px);\r\n  gap: var(--s2);\r\n  align-items: center;\r\n  padding: var(--s2) var(--s3);\r\n  font-size: var(--fs-sm);\r\n  min-width: 0;\r\n}\r\n\r\n.hc-atl__table--wide .hc-atl__table-head,\r\n.hc-atl__table--wide .hc-atl__table-row {\r\n  grid-template-columns: minmax(90px, 150px) minmax(120px, 1.2fr) minmax(120px, 1.2fr) 80px 72px 84px;\r\n}\r\n\r\n.hc-atl__table-head {\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-quaternary, inherit);\r\n  letter-spacing: 0.02em;\r\n  border-bottom: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  background: var(--ui-bg-tertiary, transparent);\r\n}\r\n\r\n.hc-atl__table-row + .hc-atl__table-row {\r\n  border-top: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n}\r\n\r\n.hc-atl__table-row:hover {\r\n  background: var(--ui-row-hover-background, transparent);\r\n}\r\n\r\n.hc-atl__sid {\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-secondary, inherit);\r\n  overflow: hidden;\r\n  text-overflow: ellipsis;\r\n  white-space: nowrap;\r\n}\r\n\r\n.hc-atl__cell {\r\n  min-width: 0;\r\n  color: var(--ui-text-secondary, inherit);\r\n  overflow: hidden;\r\n  text-overflow: ellipsis;\r\n  white-space: nowrap;\r\n}\r\n\r\n.hc-atl__num {\r\n  font-variant-numeric: tabular-nums;\r\n  text-align: right;\r\n}\r\n\r\n.hc-atl__title {\r\n  color: var(--ui-text-primary, inherit);\r\n}\r\n\r\n.hc-atl__title--diff {\r\n  border-bottom: var(--hairline) dashed var(--ui-accent, currentColor);\r\n}\r\n\r\n.hc-atl__muted {\r\n  color: var(--ui-text-quaternary, inherit);\r\n  font-size: var(--fs-xs);\r\n}\r\n\r\n.hc-atl__note {\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-quaternary, inherit);\r\n  line-height: 1.6;\r\n  overflow-wrap: anywhere;\r\n}\r\n\r\n.hc-atl__notes {\r\n  margin: 0;\r\n  padding-left: var(--s5);\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-quaternary, inherit);\r\n  line-height: 1.7;\r\n}\r\n\r\n.hc-atl__warn {\r\n  padding: var(--s2) var(--s3);\r\n  border: var(--hairline) dashed var(--ui-warning, var(--ui-orange, currentColor));\r\n  border-radius: var(--r-sm);\r\n  font-size: var(--fs-sm);\r\n  color: var(--ui-warning, var(--ui-orange, inherit));\r\n  overflow-wrap: anywhere;\r\n}\r\n\r\n.hc-atl__toast {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: var(--s3);\r\n  padding: var(--s2) var(--s3);\r\n  border: var(--hairline) solid var(--ui-accent, currentColor);\r\n  border-radius: var(--r-sm);\r\n  font-size: var(--fs-sm);\r\n  color: var(--ui-text-primary, inherit);\r\n  background: var(--ui-bg-tertiary, transparent);\r\n}\r\n\r\n.hc-atl__save-status {\r\n  padding: var(--s2) var(--s3);\r\n  border-radius: var(--r-sm);\r\n  border: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  font-size: var(--fs-sm);\r\n  color: var(--ui-text-secondary, inherit);\r\n  overflow-wrap: anywhere;\r\n}\r\n\r\n.hc-atl__save-status--good {\r\n  border-color: var(--ui-accent, currentColor);\r\n  color: var(--ui-text-primary, inherit);\r\n}\r\n\r\n.hc-atl__save-status--bad {\r\n  border-style: dashed;\r\n  border-color: var(--ui-warning, var(--ui-orange, currentColor));\r\n  color: var(--ui-warning, var(--ui-orange, inherit));\r\n}\r\n\r\n.hc-atl__source-legend {\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-quaternary, inherit);\r\n  line-height: 1.6;\r\n  overflow-wrap: anywhere;\r\n}\r\n\r\n/* 参数分组 */\r\n.hc-atl__group {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s2);\r\n  min-width: 0;\r\n}\r\n\r\n.hc-atl__group-title {\r\n  font-size: var(--fs-sm);\r\n  font-weight: 600;\r\n  color: var(--ui-text-secondary, inherit);\r\n  padding-bottom: var(--s1);\r\n  border-bottom: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n}\r\n\r\n.hc-atl__group-body {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s2);\r\n  min-width: 0;\r\n}\r\n\r\n/* 单项参数：改过的用左侧粗线标出来（形状通道，不只颜色） */\r\n.hc-atl__field {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s1);\r\n  padding: var(--s3);\r\n  border: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  border-left-width: 3px;\r\n  border-left-color: var(--ui-stroke-secondary, currentColor);\r\n  border-radius: var(--r-sm);\r\n  min-width: 0;\r\n}\r\n\r\n.hc-atl__field--dirty {\r\n  border-left-color: var(--ui-accent, currentColor);\r\n}\r\n\r\n.hc-atl__field--bad {\r\n  border-style: dashed;\r\n  border-color: var(--ui-warning, var(--ui-orange, currentColor));\r\n  border-left-style: solid;\r\n  border-left-color: var(--ui-warning, var(--ui-orange, currentColor));\r\n}\r\n\r\n.hc-atl__field-head {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: var(--s2);\r\n  flex-wrap: wrap;\r\n  min-width: 0;\r\n}\r\n\r\n.hc-atl__field-key {\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-secondary, inherit);\r\n  background: var(--ui-bg-quaternary, transparent);\r\n  padding: 1px var(--s2);\r\n  border-radius: var(--r-sm);\r\n}\r\n\r\n.hc-atl__field-label {\r\n  font-size: var(--fs-md);\r\n  color: var(--ui-text-primary, inherit);\r\n  min-width: 0;\r\n  overflow-wrap: anywhere;\r\n}\r\n\r\n.hc-atl__field-desc {\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-quaternary, inherit);\r\n  line-height: 1.6;\r\n  overflow-wrap: anywhere;\r\n}\r\n\r\n.hc-atl__field-body {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s2);\r\n  min-width: 0;\r\n}\r\n\r\n.hc-atl__field-meta {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: var(--s3);\r\n  flex-wrap: wrap;\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-quaternary, inherit);\r\n  min-width: 0;\r\n}\r\n\r\n.hc-atl__from {\r\n  padding: 1px var(--s2);\r\n  border-radius: 999px;\r\n  border: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n}\r\n\r\n.hc-atl__from--host {\r\n  border-color: var(--ui-accent, currentColor);\r\n  color: var(--ui-text-primary, inherit);\r\n}\r\n\r\n.hc-atl__from--file {\r\n  border-style: dashed;\r\n}\r\n\r\n.hc-atl__default {\r\n  color: var(--ui-text-quaternary, inherit);\r\n}\r\n\r\n.hc-atl__field-error {\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-warning, var(--ui-orange, inherit));\r\n  overflow-wrap: anywhere;\r\n}\r\n\r\n.hc-atl__input {\r\n  width: 100%;\r\n  max-width: 420px;\r\n  box-sizing: border-box;\r\n  padding: var(--s1) var(--s2);\r\n  font: inherit;\r\n  font-size: var(--fs-sm);\r\n  color: var(--ui-text-primary, inherit);\r\n  background: var(--ui-bg-secondary, transparent);\r\n  border: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  border-radius: var(--r-sm);\r\n}\r\n\r\n.hc-atl__input--area {\r\n  max-width: 100%;\r\n  resize: vertical;\r\n  line-height: 1.6;\r\n}\r\n\r\n.hc-atl__input:focus-visible {\r\n  border-color: var(--ui-accent, currentColor);\r\n}\r\n\r\n.hc-atl__switch {\r\n  display: inline-flex;\r\n  align-items: center;\r\n  gap: var(--s2);\r\n  font-size: var(--fs-sm);\r\n  color: var(--ui-text-secondary, inherit);\r\n  cursor: pointer;\r\n}\r\n\r\n.hc-atl__switch input {\r\n  width: 16px;\r\n  height: 16px;\r\n  accent-color: var(--ui-accent, currentColor);\r\n}\r\n\r\n.hc-atl__link {\r\n  appearance: none;\r\n  border: 0;\r\n  background: transparent;\r\n  padding: 0;\r\n  font: inherit;\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-accent, inherit);\r\n  cursor: pointer;\r\n  text-decoration: underline;\r\n  text-underline-offset: 2px;\r\n}\r\n\r\n.hc-atl__link:disabled {\r\n  color: var(--ui-text-quaternary, inherit);\r\n  cursor: default;\r\n  text-decoration: none;\r\n}\r\n\r\n/* 手动操作区：没有按钮，只有可复制的命令 */\r\n.hc-atl__manual {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s2);\r\n  padding: var(--s3);\r\n  border: var(--hairline) dashed var(--ui-stroke-secondary, currentColor);\r\n  border-radius: var(--r-sm);\r\n}\r\n\r\n.hc-atl__manual-title {\r\n  font-size: var(--fs-sm);\r\n  font-weight: 600;\r\n  color: var(--ui-text-secondary, inherit);\r\n}\r\n\r\n.hc-atl__cmds {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s2);\r\n}\r\n\r\n.hc-atl__cmd {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: var(--s2);\r\n  flex-wrap: wrap;\r\n  min-width: 0;\r\n}\r\n\r\n.hc-atl__cmd-label {\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-quaternary, inherit);\r\n  flex: 0 0 auto;\r\n}\r\n\r\n.hc-atl__cmd code {\r\n  font-size: var(--fs-xs);\r\n  padding: 1px var(--s2);\r\n  border-radius: var(--r-sm);\r\n  background: var(--ui-bg-quaternary, transparent);\r\n  color: var(--ui-text-primary, inherit);\r\n  overflow-wrap: anywhere;\r\n}\r\n\r\n/* 窄容器：表格退化成两列（键在上、值在下），不出现横向滚动条 */\r\n@container hc (max-width: 899px) {\r\n  .hc-atl__bar-row {\r\n    grid-template-columns: minmax(0, 1fr) auto;\r\n    grid-template-areas:\r\n      'key count'\r\n      'track track'\r\n      'label label';\r\n  }\r\n\r\n  .hc-atl__bar-key {\r\n    grid-area: key;\r\n  }\r\n\r\n  .hc-atl__bar-track {\r\n    grid-area: track;\r\n  }\r\n\r\n  .hc-atl__bar-count {\r\n    grid-area: count;\r\n  }\r\n\r\n  .hc-atl__bar-label {\r\n    grid-area: label;\r\n  }\r\n\r\n  .hc-atl__table-head,\r\n  .hc-atl__table-row,\r\n  .hc-atl__table--wide .hc-atl__table-head,\r\n  .hc-atl__table--wide .hc-atl__table-row {\r\n    grid-template-columns: minmax(0, 1fr) auto;\r\n    row-gap: var(--s1);\r\n  }\r\n\r\n  .hc-atl__table-head span:nth-child(n + 3),\r\n  .hc-atl__table-row > *:nth-child(n + 3) {\r\n    grid-column: 1 / -1;\r\n  }\r\n\r\n  .hc-atl__kv-key {\r\n    flex: 0 0 76px;\r\n  }\r\n}\r\n\r\n/* ==========================================================================\r\n * 自动命名 · 历史 vs 当前（t_85957de2）\r\n *\r\n * 三块新东西：① 统计区间切换条 ② 「现在（最近 1 小时）」实况行 + 基线时间线\r\n * ③ 运行日志（只读、脱敏）。颜色一律 var(--ui-*)，尺寸走 tokens。\r\n * ========================================================================== */\r\n\r\n.hc-atl__banner-window {\r\n  display: flex;\r\n  flex-wrap: wrap;\r\n  gap: var(--s3);\r\n  margin-top: var(--s1);\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-quaternary, inherit);\r\n  font-variant-numeric: tabular-nums;\r\n}\r\n\r\n.hc-atl__nowline {\r\n  display: flex;\r\n  flex-wrap: wrap;\r\n  align-items: baseline;\r\n  gap: var(--s2);\r\n  padding: var(--s2) var(--s3);\r\n  border: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  border-radius: var(--r-sm);\r\n  font-size: var(--fs-sm);\r\n  color: var(--ui-text-secondary, inherit);\r\n  overflow-wrap: anywhere;\r\n}\r\n\r\n.hc-atl__nowline--good {\r\n  border-color: var(--ui-accent, currentColor);\r\n  color: var(--ui-text-primary, inherit);\r\n}\r\n\r\n.hc-atl__nowline--bad {\r\n  border-style: dashed;\r\n  border-color: var(--ui-warning, var(--ui-orange, currentColor));\r\n  color: var(--ui-warning, var(--ui-orange, inherit));\r\n}\r\n\r\n/* 区间切换 */\r\n.hc-atl__windowbar {\r\n  display: flex;\r\n  align-items: center;\r\n  flex-wrap: wrap;\r\n  gap: var(--s2);\r\n  padding: var(--s2) var(--s3);\r\n  border: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  border-radius: var(--r-sm);\r\n  background: var(--ui-bg-tertiary, transparent);\r\n  min-width: 0;\r\n}\r\n\r\n.hc-atl__windowbar-label {\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-quaternary, inherit);\r\n}\r\n\r\n.hc-atl__windowbar-buttons {\r\n  display: flex;\r\n  flex-wrap: wrap;\r\n  gap: var(--s1);\r\n  min-width: 0;\r\n}\r\n\r\n.hc-atl__windowbtn {\r\n  appearance: none;\r\n  display: inline-flex;\r\n  align-items: baseline;\r\n  gap: var(--s1);\r\n  border: var(--hairline) solid transparent;\r\n  border-radius: var(--r-sm);\r\n  background: transparent;\r\n  color: var(--ui-text-secondary, inherit);\r\n  font: inherit;\r\n  font-size: var(--fs-sm);\r\n  padding: var(--s1) var(--s2);\r\n  cursor: pointer;\r\n  white-space: nowrap;\r\n  transition: border-color var(--t-fast), color var(--t-fast);\r\n}\r\n\r\n.hc-atl__windowbtn:hover {\r\n  color: var(--ui-text-primary, inherit);\r\n  border-color: var(--ui-stroke-secondary, currentColor);\r\n}\r\n\r\n.hc-atl__windowbtn--active {\r\n  border-color: var(--ui-accent, currentColor);\r\n  color: var(--ui-text-primary, inherit);\r\n  background: var(--ui-bg-secondary, transparent);\r\n}\r\n\r\n.hc-atl__windowbtn-count {\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-quaternary, inherit);\r\n  font-variant-numeric: tabular-nums;\r\n}\r\n\r\n/* 基线（修复点） */\r\n.hc-atl__baseline-head {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s1);\r\n  min-width: 0;\r\n}\r\n\r\n.hc-atl__baseline-ts {\r\n  font-size: var(--fs-md);\r\n  color: var(--ui-text-primary, inherit);\r\n  font-variant-numeric: tabular-nums;\r\n}\r\n\r\n.hc-atl__baseline-copy {\r\n  font-size: var(--fs-sm);\r\n  color: var(--ui-text-secondary, inherit);\r\n  overflow-wrap: anywhere;\r\n}\r\n\r\n.hc-atl__baseline-sides {\r\n  display: grid;\r\n  grid-template-columns: repeat(2, minmax(0, 1fr));\r\n  gap: var(--s2);\r\n}\r\n\r\n.hc-atl__side {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s1);\r\n  padding: var(--s2) var(--s3);\r\n  border: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  border-radius: var(--r-sm);\r\n  min-width: 0;\r\n}\r\n\r\n.hc-atl__side--before {\r\n  border-style: dashed;\r\n}\r\n\r\n.hc-atl__side--after {\r\n  border-color: var(--ui-accent, currentColor);\r\n}\r\n\r\n.hc-atl__side-title {\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-quaternary, inherit);\r\n}\r\n\r\n.hc-atl__side-value {\r\n  font-size: var(--fs-lg);\r\n  color: var(--ui-text-primary, inherit);\r\n  font-variant-numeric: tabular-nums;\r\n}\r\n\r\n.hc-atl__timeline {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s1);\r\n  min-width: 0;\r\n}\r\n\r\n.hc-atl__timeline-label {\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-quaternary, inherit);\r\n}\r\n\r\n.hc-atl__timeline-bars {\r\n  display: flex;\r\n  align-items: flex-end;\r\n  gap: 2px;\r\n  height: 96px;\r\n  padding: var(--s1);\r\n  border: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  border-radius: var(--r-sm);\r\n  min-width: 0;\r\n  overflow: hidden;\r\n}\r\n\r\n.hc-atl__timeline-bar {\r\n  flex: 1 1 0;\r\n  min-width: 2px;\r\n  border-radius: 2px;\r\n  background: var(--ui-stroke-secondary, currentColor);\r\n}\r\n\r\n.hc-atl__timeline-bar--bad {\r\n  background: var(--ui-warning, var(--ui-orange, currentColor));\r\n}\r\n\r\n.hc-atl__timeline-bar--good {\r\n  background: var(--ui-accent, currentColor);\r\n}\r\n\r\n.hc-atl__timeline-bar--idle {\r\n  background: var(--ui-stroke-secondary, currentColor);\r\n  opacity: 0.45;\r\n}\r\n\r\n.hc-atl__timeline-bar--before {\r\n  opacity: 0.6;\r\n}\r\n\r\n/* 运行日志 */\r\n.hc-atl__logfilters {\r\n  display: flex;\r\n  align-items: center;\r\n  flex-wrap: wrap;\r\n  gap: var(--s2);\r\n  min-width: 0;\r\n}\r\n\r\n.hc-atl__logfilter-label {\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-quaternary, inherit);\r\n}\r\n\r\n.hc-atl__logfilter-chips {\r\n  display: flex;\r\n  flex-wrap: wrap;\r\n  gap: var(--s1);\r\n  min-width: 0;\r\n}\r\n\r\n.hc-atl__chipbtn {\r\n  appearance: none;\r\n  border: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  border-radius: 999px;\r\n  background: transparent;\r\n  color: var(--ui-text-secondary, inherit);\r\n  font: inherit;\r\n  font-size: var(--fs-xs);\r\n  padding: 2px var(--s2);\r\n  cursor: pointer;\r\n  white-space: nowrap;\r\n  font-variant-numeric: tabular-nums;\r\n}\r\n\r\n.hc-atl__chipbtn:hover {\r\n  color: var(--ui-text-primary, inherit);\r\n}\r\n\r\n.hc-atl__chipbtn--active {\r\n  border-color: var(--ui-accent, currentColor);\r\n  color: var(--ui-text-primary, inherit);\r\n  background: var(--ui-bg-secondary, transparent);\r\n}\r\n\r\n.hc-atl__chipbtn--bad {\r\n  color: var(--ui-warning, var(--ui-orange, inherit));\r\n}\r\n\r\n.hc-atl__input--narrow {\r\n  max-width: 180px;\r\n  min-width: 0;\r\n}\r\n\r\n.hc-atl__table--log .hc-atl__table-head,\r\n.hc-atl__table--log .hc-atl__table-row {\r\n  grid-template-columns:\r\n    minmax(120px, 170px) minmax(70px, 110px) 82px\r\n    minmax(80px, 1fr) 68px;\r\n}\r\n\r\n.hc-atl__table-row--bad .hc-atl__cell,\r\n.hc-atl__table-row--bad .hc-atl__sid {\r\n  color: var(--ui-warning, var(--ui-orange, inherit));\r\n}\r\n\r\n.hc-atl__cell--reason {\r\n  color: var(--ui-text-primary, inherit);\r\n}\r\n\r\n/* 常用四项（置顶） */\r\n.hc-atl__pinned {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s2);\r\n  padding: var(--s3);\r\n  border: var(--hairline) solid var(--ui-accent, currentColor);\r\n  border-radius: var(--r-sm);\r\n  min-width: 0;\r\n}\r\n\r\n.hc-atl__pinned-title {\r\n  font-size: var(--fs-md);\r\n  font-weight: 600;\r\n  color: var(--ui-text-primary, inherit);\r\n}\r\n\r\n.hc-atl__pinned-note {\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-quaternary, inherit);\r\n}\r\n\r\n.hc-atl__pinned-block {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s1);\r\n  min-width: 0;\r\n}\r\n\r\n.hc-atl__pinned-head {\r\n  font-size: var(--fs-sm);\r\n  font-weight: 600;\r\n  color: var(--ui-text-secondary, inherit);\r\n}\r\n\r\n.hc-atl__pinned-hint {\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-quaternary, inherit);\r\n  line-height: 1.6;\r\n}\r\n\r\n@container hc (max-width: 1099px) {\r\n  /* 侧栏占掉宽度后，900px 视口里的内容宽只有 ~560px：两列网格会让每列只剩 ~270px，\r\n     里面的表格（最小 ~430px）必然顶出去。容器查询量的是 .hc-root（视口宽），\r\n     所以断点必须放在 1100，而不是 899。 */\r\n  .hc-atl__grid {\r\n    grid-template-columns: minmax(0, 1fr);\r\n  }\r\n\r\n  .hc-atl__table--wide .hc-atl__table-head,\r\n  .hc-atl__table--wide .hc-atl__table-row {\r\n    grid-template-columns: minmax(0, 1fr) auto;\r\n    row-gap: var(--s1);\r\n  }\r\n\r\n  .hc-atl__table--wide .hc-atl__table-head span:nth-child(n + 3),\r\n  .hc-atl__table--wide .hc-atl__table-row > *:nth-child(n + 3) {\r\n    grid-column: 1 / -1;\r\n  }\r\n}\r\n\r\n@container hc (max-width: 899px) {\r\n  .hc-atl__baseline-sides {\r\n    grid-template-columns: minmax(0, 1fr);\r\n  }\r\n\r\n  .hc-atl__timeline-bars {\r\n    height: 72px;\r\n  }\r\n\r\n  .hc-atl__table--log .hc-atl__table-head,\r\n  .hc-atl__table--log .hc-atl__table-row {\r\n    grid-template-columns: minmax(0, 1fr) auto;\r\n  }\r\n\r\n  .hc-atl__input--narrow {\r\n    max-width: 100%;\r\n    flex: 1 1 120px;\r\n  }\r\n}\r\n\r\n/* ==========================================================================\r\n * 项目分组 · 新布局（t_1dea3c49）\r\n *\r\n * 结构：① 状态条 → ② 项目条 / ③ 会话区 / ④ 检查器 → ⑤ 折叠区 → ⑥ 底部抽屉。\r\n * 首屏目标：900 与 1350 两个容器宽度下，②③ 的标题与首批行都在第一屏内，且无横向溢出。\r\n * 颜色一律 var(--ui-*)，尺寸走 tokens（--s* / --fs-* / --r-*）。\r\n * ========================================================================== */\r\n\r\n.hc-agg2 {\r\n  min-width: 0;\r\n  max-width: 100%;\r\n  overflow-x: clip;\r\n}\r\n\r\n.hc-agg2__head {\r\n  display: flex;\r\n  align-items: baseline;\r\n  flex-wrap: wrap;\r\n  gap: var(--s2);\r\n  min-width: 0;\r\n}\r\n\r\n.hc-agg2__title {\r\n  font-size: var(--fs-lg);\r\n  font-weight: 600;\r\n  color: var(--ui-text-primary, inherit);\r\n}\r\n\r\n.hc-agg2__hint {\r\n  flex: 1 1 240px;\r\n  min-width: 0;\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-quaternary, inherit);\r\n  line-height: 1.5;\r\n}\r\n\r\n.hc-agg2__scope {\r\n  max-width: 46%;\r\n  overflow: hidden;\r\n  text-overflow: ellipsis;\r\n  white-space: nowrap;\r\n}\r\n\r\n/* ------------------------------------------------------------------ ① 状态条 */\r\n\r\n.hc-agg2__strip {\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: space-between;\r\n  flex-wrap: wrap;\r\n  gap: var(--s2);\r\n  padding: var(--s1) var(--s3);\r\n  border: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  border-radius: var(--r-md);\r\n  background: var(--ui-bg-secondary, transparent);\r\n}\r\n\r\n.hc-agg2__strip-metrics {\r\n  display: flex;\r\n  align-items: stretch;\r\n  flex-wrap: wrap;\r\n  gap: var(--s1);\r\n  min-width: 0;\r\n}\r\n\r\n.hc-agg2__metric {\r\n  display: flex;\r\n  flex-direction: column;\r\n  align-items: flex-start;\r\n  gap: 0;\r\n  min-width: 64px;\r\n  padding: var(--s1) var(--s2);\r\n  border: var(--hairline) solid transparent;\r\n  border-radius: var(--r-sm);\r\n  background: transparent;\r\n  font: inherit;\r\n  text-align: left;\r\n  cursor: pointer;\r\n  transition: background var(--t-fast), border-color var(--t-fast);\r\n}\r\n\r\n.hc-agg2__metric:hover {\r\n  background: var(--ui-row-hover-background, var(--ui-bg-tertiary, transparent));\r\n}\r\n\r\n.hc-agg2__metric--on {\r\n  border-color: var(--ui-accent, currentColor);\r\n  background: var(--ui-row-active-background, var(--ui-bg-tertiary, transparent));\r\n}\r\n\r\n.hc-agg2__metric-num {\r\n  font-size: var(--fs-xl);\r\n  font-variant-numeric: tabular-nums;\r\n  color: var(--ui-text-primary, inherit);\r\n  line-height: 1.2;\r\n}\r\n\r\n.hc-agg2__metric--warn .hc-agg2__metric-num {\r\n  color: var(--ui-warning, inherit);\r\n}\r\n\r\n.hc-agg2__metric-label {\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-quaternary, inherit);\r\n  white-space: nowrap;\r\n}\r\n\r\n/* -------------------------------------------------------------- ②③④ 主工作区 */\r\n\r\n.hc-agg2__workspace {\r\n  display: grid;\r\n  grid-template-columns: minmax(0, 1fr);\r\n  align-items: start;\r\n  gap: var(--s3);\r\n  min-width: 0;\r\n}\r\n\r\n/* 900+：项目条 + 会话区并排，检查器落到下一行（首屏仍然先看到项目与会话） */\r\n@container hc (min-width: 900px) {\r\n  .hc-agg2__workspace {\r\n    grid-template-columns: 200px minmax(0, 1fr);\r\n  }\r\n\r\n  .hc-agg2__inspector {\r\n    grid-column: 1 / -1;\r\n  }\r\n}\r\n\r\n/* 1200+：三栏，检查器回到右侧 */\r\n@container hc (min-width: 1200px) {\r\n  .hc-agg2__workspace {\r\n    grid-template-columns: 240px minmax(0, 1fr) 300px;\r\n  }\r\n\r\n  .hc-agg2__inspector {\r\n    grid-column: auto;\r\n  }\r\n}\r\n\r\n.hc-agg2__rail,\r\n.hc-agg2__sessions,\r\n.hc-agg2__inspector {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s2);\r\n  min-width: 0;\r\n  padding: var(--s2) var(--s3);\r\n  border: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  border-radius: var(--r-md);\r\n  background: var(--ui-bg-secondary, transparent);\r\n}\r\n\r\n.hc-agg2__pane-head {\r\n  display: flex;\r\n  align-items: center;\r\n  flex-wrap: wrap;\r\n  gap: var(--s2);\r\n  min-height: var(--row-h);\r\n  min-width: 0;\r\n}\r\n\r\n.hc-agg2__pane-title {\r\n  font-size: var(--fs-md);\r\n  font-weight: 600;\r\n  color: var(--ui-text-primary, inherit);\r\n}\r\n\r\n/* ------------------------------------------------------------------ ② 项目条 */\r\n\r\n.hc-agg2__proj-list {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 2px;\r\n  max-height: 56vh;\r\n  overflow-y: auto;\r\n  overflow-x: hidden;\r\n}\r\n\r\n.hc-agg2__proj {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 2px;\r\n  padding: var(--s1) var(--s2);\r\n  border-left: var(--nav-mark) solid transparent;\r\n  border-radius: var(--r-sm);\r\n  min-width: 0;\r\n}\r\n\r\n.hc-agg2__proj:hover {\r\n  background: var(--ui-row-hover-background, var(--ui-bg-tertiary, transparent));\r\n}\r\n\r\n.hc-agg2__proj--on {\r\n  border-left-color: var(--ui-accent, currentColor);\r\n  background: var(--ui-row-active-background, var(--ui-bg-tertiary, transparent));\r\n}\r\n\r\n.hc-agg2__proj-head {\r\n  display: flex;\r\n  align-items: baseline;\r\n  gap: var(--s2);\r\n  min-width: 0;\r\n}\r\n\r\n.hc-agg2__proj-name {\r\n  flex: 1 1 auto;\r\n  min-width: 0;\r\n  padding: 0;\r\n  border: 0;\r\n  background: transparent;\r\n  font: inherit;\r\n  font-size: var(--fs-sm);\r\n  font-weight: 600;\r\n  color: var(--ui-text-primary, inherit);\r\n  text-align: left;\r\n  overflow: hidden;\r\n  text-overflow: ellipsis;\r\n  white-space: nowrap;\r\n  cursor: pointer;\r\n}\r\n\r\n.hc-agg2__proj-slug,\r\n.hc-agg2__proj-count {\r\n  flex: 0 0 auto;\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-quaternary, inherit);\r\n  white-space: nowrap;\r\n}\r\n\r\n.hc-agg2__proj-meta {\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-quaternary, inherit);\r\n  overflow: hidden;\r\n  text-overflow: ellipsis;\r\n  white-space: nowrap;\r\n}\r\n\r\n.hc-agg2__proj-ops {\r\n  display: flex;\r\n  flex-wrap: wrap;\r\n  gap: var(--s1);\r\n}\r\n\r\n.hc-agg2__editor {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s1);\r\n  padding: var(--s2);\r\n  border: var(--hairline) dashed var(--ui-stroke-secondary, currentColor);\r\n  border-radius: var(--r-sm);\r\n  min-width: 0;\r\n}\r\n\r\n.hc-agg2__editor-ops {\r\n  display: flex;\r\n  align-items: center;\r\n  flex-wrap: wrap;\r\n  gap: var(--s1);\r\n  min-width: 0;\r\n}\r\n\r\n.hc-agg2__inline-input {\r\n  width: 100%;\r\n  min-width: 0;\r\n}\r\n\r\n.hc-agg2__inline-select {\r\n  max-width: 100%;\r\n}\r\n\r\n.hc-agg2__radio {\r\n  display: inline-flex;\r\n  align-items: center;\r\n  gap: var(--s1);\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-secondary, inherit);\r\n}\r\n\r\n/* ------------------------------------------------------------------ ③ 会话区 */\r\n\r\n.hc-agg2__agents {\r\n  display: flex;\r\n  flex-wrap: wrap;\r\n  gap: var(--s1);\r\n  min-width: 0;\r\n}\r\n\r\n.hc-agg2__agent {\r\n  display: inline-flex;\r\n  align-items: center;\r\n  gap: var(--s1);\r\n  padding: 2px var(--s2);\r\n  border: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  border-radius: 999px;\r\n  background: transparent;\r\n  font: inherit;\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-secondary, inherit);\r\n  cursor: pointer;\r\n  transition: border-color var(--t-fast), color var(--t-fast);\r\n}\r\n\r\n.hc-agg2__agent--on {\r\n  border-color: var(--ui-accent, currentColor);\r\n  color: var(--ui-text-primary, inherit);\r\n  background: var(--ui-row-active-background, var(--ui-bg-tertiary, transparent));\r\n}\r\n\r\n.hc-agg2__agent-n {\r\n  color: var(--ui-text-quaternary, inherit);\r\n}\r\n\r\n.hc-agg2__search {\r\n  flex: 1 1 160px;\r\n  min-width: 120px;\r\n  max-width: 260px;\r\n}\r\n\r\n.hc-agg2__scopes {\r\n  display: flex;\r\n  gap: var(--s1);\r\n}\r\n\r\n.hc-agg2__note {\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-quaternary, inherit);\r\n  line-height: 1.5;\r\n  word-break: break-word;\r\n}\r\n\r\n/* 「显示 X / 共 N 条」+「加载更多」：建议数 >200 时这三个数字必须写在一起，\r\n   不让人拿状态条的 500 去对明细的 200 行（t_4d192e1b）。 */\r\n.hc-agg2__counts {\r\n  display: flex;\r\n  flex-wrap: wrap;\r\n  align-items: center;\r\n  gap: var(--s2, 8px);\r\n  font-size: var(--fs-xs);\r\n  line-height: 1.6;\r\n  color: var(--ui-text-quaternary, inherit);\r\n}\r\n\r\n.hc-agg2__counts-text {\r\n  font-variant-numeric: tabular-nums;\r\n}\r\n\r\n.hc-agg2__counts-err {\r\n  color: var(--ui-warning, var(--ui-orange, inherit));\r\n  word-break: break-word;\r\n}\r\n\r\n.hc-agg2__sect {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s1);\r\n  min-width: 0;\r\n}\r\n\r\n/* 未分组：醒目但克制 —— 一条左侧警示竖线 + 计数 chip，不整块染色 */\r\n.hc-agg2__sect--warn {\r\n  padding-left: var(--s2);\r\n  border-left: var(--nav-mark) solid var(--ui-warning, currentColor);\r\n  border-radius: var(--r-sm);\r\n}\r\n\r\n.hc-agg2__sect-head {\r\n  display: flex;\r\n  align-items: baseline;\r\n  flex-wrap: wrap;\r\n  gap: var(--s2);\r\n}\r\n\r\n.hc-agg2__sect-title {\r\n  font-size: var(--fs-md);\r\n  font-weight: 600;\r\n  color: var(--ui-text-primary, inherit);\r\n}\r\n\r\n.hc-agg2__sect-warn {\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-warning, inherit);\r\n}\r\n\r\n.hc-agg2__sect-empty {\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-quaternary, inherit);\r\n  padding: var(--s1) 0;\r\n}\r\n\r\n.hc-agg2__sess-list {\r\n  display: flex;\r\n  flex-direction: column;\r\n  max-height: 52vh;\r\n  overflow-y: auto;\r\n  overflow-x: hidden;\r\n}\r\n\r\n.hc-agg2__sess {\r\n  display: flex;\r\n  align-items: center;\r\n  flex-wrap: wrap;\r\n  gap: var(--s1) var(--s2);\r\n  padding: var(--s1) var(--s2);\r\n  border-radius: var(--r-sm);\r\n  font-size: var(--fs-sm);\r\n  min-width: 0;\r\n}\r\n\r\n.hc-agg2__sess + .hc-agg2__sess {\r\n  border-top: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n}\r\n\r\n.hc-agg2__sess:hover {\r\n  background: var(--ui-row-hover-background, var(--ui-bg-tertiary, transparent));\r\n}\r\n\r\n.hc-agg2__sess-title {\r\n  flex: 1 1 180px;\r\n  min-width: 0;\r\n  overflow: hidden;\r\n  text-overflow: ellipsis;\r\n  white-space: nowrap;\r\n  color: var(--ui-text-primary, inherit);\r\n}\r\n\r\n.hc-agg2__sess--loose .hc-agg2__sess-title {\r\n  color: var(--ui-text-secondary, inherit);\r\n}\r\n\r\n.hc-agg2__sess-agent,\r\n.hc-agg2__sess-msg,\r\n.hc-agg2__sess-time {\r\n  flex: 0 0 auto;\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-quaternary, inherit);\r\n  white-space: nowrap;\r\n}\r\n\r\n.hc-agg2__sess-project {\r\n  flex: 0 1 auto;\r\n  min-width: 0;\r\n  max-width: 140px;\r\n  overflow: hidden;\r\n  text-overflow: ellipsis;\r\n  white-space: nowrap;\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-secondary, inherit);\r\n}\r\n\r\n.hc-agg2__sess-project--none {\r\n  color: var(--ui-warning, inherit);\r\n}\r\n\r\n.hc-agg2__quick {\r\n  flex: 0 0 auto;\r\n  max-width: 132px;\r\n}\r\n\r\n/* ------------------------------------------------------------------ ④ 检查器 */\r\n\r\n.hc-agg2__pending {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s1);\r\n  padding: var(--s2);\r\n  border: var(--hairline) solid var(--ui-accent, currentColor);\r\n  border-radius: var(--r-sm);\r\n  background: var(--ui-bg-tertiary, transparent);\r\n  min-width: 0;\r\n}\r\n\r\n.hc-agg2__pending-title {\r\n  font-size: var(--fs-sm);\r\n  font-weight: 600;\r\n  color: var(--ui-text-primary, inherit);\r\n}\r\n\r\n.hc-agg2__pending-row {\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-secondary, inherit);\r\n  word-break: break-word;\r\n}\r\n\r\n.hc-agg2__sel-list {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 2px;\r\n  max-height: 108px;\r\n  overflow-y: auto;\r\n  overflow-x: hidden;\r\n}\r\n\r\n.hc-agg2__sel-row {\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-secondary, inherit);\r\n  overflow: hidden;\r\n  text-overflow: ellipsis;\r\n  white-space: nowrap;\r\n}\r\n\r\n.hc-agg2__batch {\r\n  min-width: 0;\r\n}\r\n\r\n/* 批量块沿用旧面板的 .hc-agg__warn（nowrap 药丸）：在 300px 宽的检查器里会把整栏撑破，\r\n   这里允许折行，保证「无横向溢出」这条验收在 1350 宽度下也成立。 */\r\n.hc-agg2__inspector .hc-agg__warn,\r\n.hc-agg2__rail .hc-agg__warn {\r\n  max-width: 100%;\r\n  white-space: normal;\r\n  overflow-wrap: anywhere;\r\n  border-radius: var(--r-sm);\r\n}\r\n\r\n/* ------------------------------------------------------- ⑤⑥ 折叠区 / 底部抽屉 */\r\n\r\n.hc-agg2__drawers {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s1);\r\n  min-width: 0;\r\n}\r\n\r\n.hc-agg2__drawer {\r\n  border: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  border-radius: var(--r-md);\r\n  background: var(--ui-bg-secondary, transparent);\r\n  min-width: 0;\r\n}\r\n\r\n.hc-agg2__drawer-head {\r\n  display: flex;\r\n  align-items: baseline;\r\n  flex-wrap: wrap;\r\n  gap: var(--s2);\r\n  padding: var(--s2) var(--s3);\r\n  font-size: var(--fs-sm);\r\n  cursor: pointer;\r\n  list-style: none;\r\n  color: var(--ui-text-secondary, inherit);\r\n}\r\n\r\n.hc-agg2__drawer-head::-webkit-details-marker {\r\n  display: none;\r\n}\r\n\r\n.hc-agg2__drawer-head::before {\r\n  content: '▸';\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-quaternary, inherit);\r\n}\r\n\r\n.hc-agg2__drawer[open] > .hc-agg2__drawer-head::before {\r\n  content: '▾';\r\n}\r\n\r\n.hc-agg2__drawer-title {\r\n  font-weight: 600;\r\n  color: var(--ui-text-primary, inherit);\r\n}\r\n\r\n.hc-agg2__drawer-hint {\r\n  margin-left: auto;\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-quaternary, inherit);\r\n}\r\n\r\n.hc-agg2__drawer-body {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s2);\r\n  padding: 0 var(--s3) var(--s3);\r\n  min-width: 0;\r\n}\r\n\r\n.hc-agg2__drawer-table {\r\n  max-height: 52vh;\r\n  overflow: auto;\r\n}\r\n\r\n.hc-agg2__rules {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s1);\r\n  min-width: 0;\r\n}\r\n\r\n.hc-agg2__rules-list {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s1);\r\n  max-height: 40vh;\r\n  overflow-y: auto;\r\n  overflow-x: hidden;\r\n}\r\n\r\n.hc-agg2__rules-row {\r\n  display: flex;\r\n  align-items: baseline;\r\n  gap: var(--s2);\r\n  min-width: 0;\r\n  font-size: var(--fs-xs);\r\n}\r\n\r\n.hc-agg2__rules-slug {\r\n  flex: 0 0 120px;\r\n  overflow: hidden;\r\n  text-overflow: ellipsis;\r\n  white-space: nowrap;\r\n  font-weight: 600;\r\n  color: var(--ui-text-secondary, inherit);\r\n}\r\n\r\n.hc-agg2__rules-kw {\r\n  flex: 1 1 auto;\r\n  min-width: 0;\r\n  color: var(--ui-text-quaternary, inherit);\r\n  word-break: break-word;\r\n}\r\n\r\n/* 窄容器：状态条指标压缩，抽屉头提示换行不撑宽 */\r\n@container hc (max-width: 899px) {\r\n  .hc-agg2__metric {\r\n    min-width: 56px;\r\n    padding: var(--s1);\r\n  }\r\n\r\n  .hc-agg2__metric-num {\r\n    font-size: var(--fs-lg);\r\n  }\r\n\r\n  .hc-agg2__drawer-hint {\r\n    margin-left: 0;\r\n    flex-basis: 100%;\r\n  }\r\n}\r\n\r\n/* ==========================================================================\r\n * t_f2338eb2 · 模式选择（A 只归类未分组 / B 全量重建）+ 预览 diff + 确认应用 + 整批撤销\r\n *\r\n * 结构：模式行（单选 + 先预览）→ B 破坏性提示（或 A 安全提示）→ 计划面板\r\n *      （扫描范围 / 变更数 / 逐条新旧映射 diff / B 的被抛弃旧项目）→ 应用结果（成功失败 + 撤销）\r\n *\r\n * 约束：\r\n *   - B 的破坏性提示在 900 与 1350 两个容器宽度下都必须**完整可见**：允许折行，\r\n *     禁止 white-space: nowrap / text-overflow: ellipsis / 固定高度；\r\n *   - 颜色一律 var(--ui-*)，尺寸走 tokens（--s* / --fs-* / --r-*）；\r\n *   - 任何一行都 min-width: 0，保证「无横向溢出」这条验收在窄宽度下也成立。\r\n * ========================================================================== */\r\n\r\n.hc-agg2__mode {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s2);\r\n  min-width: 0;\r\n  max-width: 100%;\r\n  padding: var(--s2) var(--s3);\r\n  border: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  border-radius: var(--r-md);\r\n  background: var(--ui-bg-secondary, transparent);\r\n}\r\n\r\n/* B 模式整块换色：和 A 一眼就能分开，不靠「读文字才知道选了哪个」 */\r\n.hc-agg2__mode--danger {\r\n  border-color: var(--ui-warning, var(--ui-orange, currentColor));\r\n}\r\n\r\n.hc-agg2__mode-row {\r\n  display: flex;\r\n  align-items: center;\r\n  flex-wrap: wrap;\r\n  gap: var(--s2);\r\n  min-width: 0;\r\n}\r\n\r\n.hc-agg2__mode-label {\r\n  font-size: var(--fs-sm);\r\n  font-weight: 600;\r\n  color: var(--ui-text-secondary, inherit);\r\n}\r\n\r\n.hc-agg2__modes {\r\n  display: flex;\r\n  flex-wrap: wrap;\r\n  gap: var(--s1);\r\n  min-width: 0;\r\n}\r\n\r\n.hc-agg2__mode-opt {\r\n  display: inline-flex;\r\n  align-items: center;\r\n  gap: var(--s1);\r\n  min-width: 0;\r\n  padding: 2px var(--s2);\r\n  border: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  border-radius: var(--r-sm);\r\n  font-size: var(--fs-sm);\r\n  color: var(--ui-text-secondary, inherit);\r\n  cursor: pointer;\r\n  white-space: normal;\r\n  overflow-wrap: anywhere;\r\n}\r\n\r\n.hc-agg2__mode-opt input {\r\n  margin: 0;\r\n  accent-color: var(--ui-accent, currentColor);\r\n}\r\n\r\n.hc-agg2__mode-opt--on {\r\n  border-color: var(--ui-accent, currentColor);\r\n  color: var(--ui-text-primary, inherit);\r\n  background: var(--ui-bg-tertiary, transparent);\r\n}\r\n\r\n.hc-agg2__mode-opt--danger {\r\n  color: var(--ui-warning, var(--ui-orange, inherit));\r\n}\r\n\r\n.hc-agg2__mode-opt--danger.hc-agg2__mode-opt--on {\r\n  border-color: var(--ui-warning, var(--ui-orange, currentColor));\r\n  border-left-width: 3px;\r\n  background: var(--ui-bg-tertiary, transparent);\r\n}\r\n\r\n.hc-agg2__mode-zero {\r\n  flex: 1 1 220px;\r\n  min-width: 0;\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-quaternary, inherit);\r\n  overflow-wrap: anywhere;\r\n}\r\n\r\n/* B 的破坏性提示：折行、不截断，左侧加粗竖条 + 警示色 */\r\n.hc-agg2__mode-warn {\r\n  display: block;\r\n  min-width: 0;\r\n  padding: var(--s1) var(--s2);\r\n  border: var(--hairline) solid var(--ui-warning, var(--ui-orange, currentColor));\r\n  border-left-width: 3px;\r\n  border-radius: var(--r-sm);\r\n  background: var(--ui-bg-tertiary, transparent);\r\n  color: var(--ui-warning, var(--ui-orange, inherit));\r\n  font-size: var(--fs-sm);\r\n  font-weight: 600;\r\n  line-height: 1.55;\r\n  white-space: normal;\r\n  overflow-wrap: anywhere;\r\n  word-break: break-word;\r\n}\r\n\r\n.hc-agg2__mode-safe {\r\n  min-width: 0;\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-quaternary, inherit);\r\n  line-height: 1.5;\r\n  white-space: normal;\r\n  overflow-wrap: anywhere;\r\n}\r\n\r\n.hc-agg2__mode-body {\r\n  min-width: 0;\r\n}\r\n\r\n.hc-agg2__plan-loading {\r\n  padding: var(--s1) 0;\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-quaternary, inherit);\r\n}\r\n\r\n.hc-agg2__plan {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s2);\r\n  min-width: 0;\r\n  padding-top: var(--s1);\r\n  border-top: var(--hairline) dashed var(--ui-stroke-secondary, currentColor);\r\n}\r\n\r\n.hc-agg2__plan-facts {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 2px;\r\n  min-width: 0;\r\n}\r\n\r\n.hc-agg2__plan-fact {\r\n  display: flex;\r\n  align-items: baseline;\r\n  gap: var(--s2);\r\n  min-width: 0;\r\n  font-size: var(--fs-sm);\r\n}\r\n\r\n.hc-agg2__plan-k {\r\n  flex: 0 0 72px;\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-quaternary, inherit);\r\n}\r\n\r\n.hc-agg2__plan-v {\r\n  flex: 1 1 auto;\r\n  min-width: 0;\r\n  color: var(--ui-text-secondary, inherit);\r\n  line-height: 1.5;\r\n  overflow-wrap: anywhere;\r\n}\r\n\r\n.hc-agg2__plan-v--danger {\r\n  color: var(--ui-warning, var(--ui-orange, inherit));\r\n  font-weight: 600;\r\n}\r\n\r\n.hc-agg2__plan-v--ok {\r\n  color: var(--ui-text-tertiary, inherit);\r\n}\r\n\r\n/* 逐条 diff：会话 → 原项目 → 新项目 → 变化 */\r\n.hc-agg2__diff {\r\n  display: flex;\r\n  flex-direction: column;\r\n  min-width: 0;\r\n  border: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  border-radius: var(--r-sm);\r\n}\r\n\r\n.hc-agg2__diff-head,\r\n.hc-agg2__diff-row {\r\n  display: grid;\r\n  grid-template-columns: minmax(0, 1.6fr) minmax(72px, 0.6fr) minmax(72px, 0.6fr) minmax(72px, 0.5fr);\r\n  align-items: baseline;\r\n  gap: var(--s2);\r\n  min-width: 0;\r\n  padding: 2px var(--s2);\r\n}\r\n\r\n.hc-agg2__diff-head {\r\n  border-bottom: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-quaternary, inherit);\r\n}\r\n\r\n.hc-agg2__diff-rows {\r\n  max-height: 300px;\r\n  overflow-y: auto;\r\n  overflow-x: hidden;\r\n  min-width: 0;\r\n}\r\n\r\n.hc-agg2__diff-row {\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-secondary, inherit);\r\n}\r\n\r\n.hc-agg2__diff-row + .hc-agg2__diff-row {\r\n  border-top: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n}\r\n\r\n.hc-agg2__diff-row--mute {\r\n  color: var(--ui-text-quaternary, inherit);\r\n}\r\n\r\n.hc-agg2__diff-sess {\r\n  display: flex;\r\n  align-items: baseline;\r\n  gap: var(--s1);\r\n  min-width: 0;\r\n}\r\n\r\n.hc-agg2__diff-id {\r\n  flex: 0 0 auto;\r\n  font-family: var(--ui-font-mono, monospace);\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-tertiary, inherit);\r\n}\r\n\r\n.hc-agg2__diff-title {\r\n  flex: 1 1 auto;\r\n  min-width: 0;\r\n  overflow: hidden;\r\n  text-overflow: ellipsis;\r\n  white-space: nowrap;\r\n}\r\n\r\n.hc-agg2__diff-from,\r\n.hc-agg2__diff-to {\r\n  min-width: 0;\r\n  overflow-wrap: anywhere;\r\n}\r\n\r\n.hc-agg2__diff-change {\r\n  min-width: 0;\r\n  font-size: var(--fs-xs);\r\n  overflow-wrap: anywhere;\r\n}\r\n\r\n.hc-agg2__diff-change--ok {\r\n  color: var(--ui-accent, inherit);\r\n}\r\n\r\n.hc-agg2__diff-change--warn {\r\n  color: var(--ui-warning, var(--ui-orange, inherit));\r\n}\r\n\r\n.hc-agg2__diff-change--mute {\r\n  color: var(--ui-text-quaternary, inherit);\r\n}\r\n\r\n/* B 模式被抛弃的旧项目 */\r\n.hc-agg2__dropped {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s1);\r\n  min-width: 0;\r\n  padding: var(--s1) var(--s2);\r\n  border: var(--hairline) solid var(--ui-warning, var(--ui-orange, currentColor));\r\n  border-radius: var(--r-sm);\r\n  background: var(--ui-bg-tertiary, transparent);\r\n}\r\n\r\n.hc-agg2__dropped-title {\r\n  font-size: var(--fs-xs);\r\n  font-weight: 600;\r\n  color: var(--ui-warning, var(--ui-orange, inherit));\r\n}\r\n\r\n.hc-agg2__dropped-list {\r\n  display: flex;\r\n  flex-wrap: wrap;\r\n  gap: var(--s1);\r\n  min-width: 0;\r\n}\r\n\r\n.hc-agg2__dropped-item {\r\n  display: inline-flex;\r\n  align-items: baseline;\r\n  gap: var(--s1);\r\n  min-width: 0;\r\n  max-width: 100%;\r\n  padding: 1px var(--s2);\r\n  border: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  border-radius: 999px;\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-secondary, inherit);\r\n  overflow-wrap: anywhere;\r\n}\r\n\r\n.hc-agg2__dropped-name {\r\n  color: var(--ui-text-primary, inherit);\r\n}\r\n\r\n.hc-agg2__dropped-count {\r\n  color: var(--ui-text-quaternary, inherit);\r\n}\r\n\r\n/* 确认应用 / 二次确认 */\r\n.hc-agg2__apply {\r\n  display: flex;\r\n  align-items: center;\r\n  flex-wrap: wrap;\r\n  gap: var(--s2);\r\n  min-width: 0;\r\n}\r\n\r\n.hc-agg2__apply-hint {\r\n  flex: 1 1 200px;\r\n  min-width: 0;\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-quaternary, inherit);\r\n  line-height: 1.5;\r\n  overflow-wrap: anywhere;\r\n}\r\n\r\n.hc-agg2__mode .hc-btn--danger,\r\n.hc-agg2__confirm .hc-btn--danger {\r\n  color: var(--ui-warning, var(--ui-orange, inherit));\r\n  border-color: var(--ui-warning, var(--ui-orange, currentColor));\r\n  font-weight: 600;\r\n}\r\n\r\n.hc-agg2__mode .hc-btn--danger:hover,\r\n.hc-agg2__confirm .hc-btn--danger:hover {\r\n  background: var(--ui-bg-tertiary, transparent);\r\n}\r\n\r\n.hc-agg2__confirm {\r\n  display: flex;\r\n  align-items: center;\r\n  flex-wrap: wrap;\r\n  gap: var(--s2);\r\n  min-width: 0;\r\n  padding: var(--s1) var(--s2);\r\n  border: var(--hairline) solid var(--ui-warning, var(--ui-orange, currentColor));\r\n  border-left-width: 3px;\r\n  border-radius: var(--r-sm);\r\n  background: var(--ui-bg-tertiary, transparent);\r\n}\r\n\r\n.hc-agg2__confirm-text {\r\n  flex: 1 1 240px;\r\n  min-width: 0;\r\n  font-size: var(--fs-sm);\r\n  font-weight: 600;\r\n  color: var(--ui-warning, var(--ui-orange, inherit));\r\n  line-height: 1.5;\r\n  overflow-wrap: anywhere;\r\n}\r\n\r\n/* 应用结果 */\r\n.hc-agg2__result {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s1);\r\n  min-width: 0;\r\n  margin-top: var(--s2);\r\n  padding: var(--s2);\r\n  border: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  border-radius: var(--r-sm);\r\n  background: var(--ui-bg-secondary, transparent);\r\n}\r\n\r\n.hc-agg2__result-head {\r\n  display: flex;\r\n  align-items: baseline;\r\n  flex-wrap: wrap;\r\n  gap: var(--s2);\r\n  min-width: 0;\r\n}\r\n\r\n.hc-agg2__result-title {\r\n  font-size: var(--fs-sm);\r\n  font-weight: 600;\r\n  color: var(--ui-text-primary, inherit);\r\n}\r\n\r\n.hc-agg2__result-chip {\r\n  padding: 0 var(--s1);\r\n  border: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  border-radius: 999px;\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-tertiary, inherit);\r\n}\r\n\r\n.hc-agg2__result-chip--ok {\r\n  border-color: var(--ui-accent, currentColor);\r\n  color: var(--ui-text-primary, inherit);\r\n}\r\n\r\n.hc-agg2__result-chip--bad {\r\n  border-color: var(--ui-warning, var(--ui-orange, currentColor));\r\n  color: var(--ui-warning, var(--ui-orange, inherit));\r\n}\r\n\r\n.hc-agg2__result-op {\r\n  min-width: 0;\r\n  font-family: var(--ui-font-mono, monospace);\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-quaternary, inherit);\r\n  overflow-wrap: anywhere;\r\n}\r\n\r\n.hc-agg2__result-rows {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 1px;\r\n  min-width: 0;\r\n  max-height: 220px;\r\n  overflow-y: auto;\r\n  overflow-x: hidden;\r\n}\r\n\r\n.hc-agg2__result-row {\r\n  display: flex;\r\n  align-items: baseline;\r\n  flex-wrap: wrap;\r\n  gap: var(--s1);\r\n  min-width: 0;\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-secondary, inherit);\r\n}\r\n\r\n.hc-agg2__result-row--bad {\r\n  color: var(--ui-warning, var(--ui-orange, inherit));\r\n}\r\n\r\n.hc-agg2__result-arrow {\r\n  color: var(--ui-text-quaternary, inherit);\r\n}\r\n\r\n.hc-agg2__result-ok {\r\n  color: var(--ui-text-tertiary, inherit);\r\n}\r\n\r\n.hc-agg2__result-bad {\r\n  min-width: 0;\r\n  overflow-wrap: anywhere;\r\n}\r\n\r\n.hc-agg2__result-error {\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-warning, var(--ui-orange, inherit));\r\n  overflow-wrap: anywhere;\r\n}\r\n\r\n.hc-agg2__failed {\r\n  min-width: 0;\r\n}\r\n\r\n.hc-agg2__failed-summary {\r\n  cursor: pointer;\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-warning, var(--ui-orange, inherit));\r\n}\r\n\r\n.hc-agg2__failed-body {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 1px;\r\n  min-width: 0;\r\n  padding-top: var(--s1);\r\n}\r\n\r\n.hc-agg2__failed-row {\r\n  min-width: 0;\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-tertiary, inherit);\r\n  overflow-wrap: anywhere;\r\n}\r\n\r\n.hc-agg2__undo {\r\n  display: flex;\r\n  align-items: center;\r\n  flex-wrap: wrap;\r\n  gap: var(--s2);\r\n  min-width: 0;\r\n}\r\n\r\n.hc-agg2__undo-result {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s1);\r\n  min-width: 0;\r\n  padding: var(--s1) var(--s2);\r\n  border: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  border-radius: var(--r-sm);\r\n}\r\n\r\n.hc-agg2__undo-title {\r\n  font-size: var(--fs-sm);\r\n  font-weight: 600;\r\n  color: var(--ui-text-primary, inherit);\r\n  overflow-wrap: anywhere;\r\n}\r\n\r\n/* 窄容器：模式行竖排，避免「先预览」被挤到下一行之外；diff 列收窄但保留四列 */\r\n@container hc (max-width: 899px) {\r\n  .hc-agg2__plan-k {\r\n    flex-basis: 56px;\r\n  }\r\n\r\n  .hc-agg2__diff-head,\r\n  .hc-agg2__diff-row {\r\n    grid-template-columns: minmax(0, 1.4fr) minmax(60px, 0.6fr) minmax(60px, 0.6fr) minmax(56px, 0.5fr);\r\n    gap: var(--s1);\r\n  }\r\n}\r\n\r\n/* 模式门：抽屉里的三个旧入口（扫描 / AI 跑批 / 自动模式 tick）都按当前模式收口。\r\n   open 时是一句口径说明，blocked 时换成警示色并说明「为什么停用、该去哪」。 */\r\n.hc-agg2__gate {\r\n  display: flex;\r\n  align-items: baseline;\r\n  flex-wrap: wrap;\r\n  gap: var(--s2);\r\n  min-width: 0;\r\n  padding: var(--s1) var(--s2);\r\n  border: var(--hairline) dashed var(--ui-stroke-secondary, currentColor);\r\n  border-radius: var(--r-sm);\r\n}\r\n\r\n.hc-agg2__gate[data-agg2-mode-gate-state='blocked'] {\r\n  border-style: solid;\r\n  border-color: var(--ui-warning, var(--ui-orange, currentColor));\r\n  background: var(--ui-bg-tertiary, transparent);\r\n}\r\n\r\n.hc-agg2__gate-title {\r\n  flex: 0 0 auto;\r\n  font-size: var(--fs-xs);\r\n  font-weight: 600;\r\n  color: var(--ui-text-secondary, inherit);\r\n}\r\n\r\n.hc-agg2__gate[data-agg2-mode-gate-state='blocked'] .hc-agg2__gate-title {\r\n  color: var(--ui-warning, var(--ui-orange, inherit));\r\n}\r\n\r\n.hc-agg2__gate-text {\r\n  flex: 1 1 260px;\r\n  min-width: 0;\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-quaternary, inherit);\r\n  line-height: 1.5;\r\n  white-space: normal;\r\n  overflow-wrap: anywhere;\r\n}\r\n\r\n.hc-agg2__gate[data-agg2-mode-gate-state='blocked'] .hc-agg2__gate-text {\r\n  color: var(--ui-warning, var(--ui-orange, inherit));\r\n}\r\n\r\n/* ============================================================ Advisor 可操作覆盖矩阵（t_72e9a7fa） */\r\n.hc-btn--sm { padding: 2px var(--s2); font-size: var(--fs-xs); }\r\n/* 第三档 · 危险：**红字**（不描红边、不填底色，避免和主操作抢注意力；只有 hover 时给一层淡底）。\r\n   桌面端主题里只定义了 --ui-red（没有 --ui-danger/--ui-warning），\r\n   所以兜底链必须一路走到 --ui-red，否则 color:inherit 会落到深色背景上的近黑字（等于看不见）。 */\r\n.hc-btn--danger {\r\n  color: var(--ui-danger, var(--ui-red, var(--ui-warning, currentColor)));\r\n  border-color: transparent;\r\n  background: none;\r\n}\r\n.hc-btn--danger:hover {\r\n  color: var(--ui-danger, var(--ui-red, var(--ui-warning, currentColor)));\r\n  border-color: transparent;\r\n  background: var(--ui-bg-quaternary, transparent);\r\n}\r\n.hc-btn:disabled { opacity: .45; cursor: not-allowed; border-color: var(--ui-stroke-secondary, currentColor); color: var(--ui-text-quaternary, inherit); }\r\n\r\n.hc-adv__cov { display: flex; flex-direction: column; gap: var(--s2); min-width: 0; }\r\n.hc-adv__cov-cards { display: flex; flex-direction: column; gap: var(--s2); min-width: 0; }\r\n\r\n/* 顶部数字卡：只作概览，字号与描边都收敛（不再抢卡片的注意力） */\r\n.hc-adv__cov-strip .hc-adv__cov-cell { padding: var(--s2) var(--s3); }\r\n.hc-adv__cov-strip .hc-adv__cov-num { font-size: var(--fs-md); }\r\n.hc-adv__cov-strip .hc-adv__cov-caliber { line-height: 1.25; }\r\n\r\n/* ---------------------------------------------------------- Agent 卡片（收起态 88~120px） */\r\n.hc-adv__cov-card {\r\n  display: grid;\r\n  grid-template-columns: minmax(0, 1fr) auto;\r\n  grid-template-areas: 'head side' 'facts side';\r\n  align-items: center;\r\n  align-content: center;\r\n  /* 任务书要求收起态 88~120px：两行内容只有 ~47px，靠 min-height 撑到 88px 的下限，\r\n     同时保持整卡垂直居中（不靠乱加 padding 把内容推开）。 */\r\n  min-height: 88px;\r\n  gap: var(--s2) var(--s3);\r\n  padding: var(--s3);\r\n  border: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  border-radius: var(--r-sm);\r\n  background: var(--ui-bg-secondary, transparent);\r\n  min-width: 0;\r\n}\r\n.hc-adv__cov-card--open { background: var(--ui-bg-tertiary, transparent); }\r\n.hc-adv__cov-card-head { grid-area: head; display: flex; align-items: center; gap: var(--s2); min-width: 0; }\r\n.hc-adv__cov-dot { width: 8px; height: 8px; flex: 0 0 auto; border-radius: 50%; background: var(--ui-text-quaternary, currentColor); }\r\n.hc-adv__cov-dot--ok { background: var(--ui-accent, currentColor); }\r\n.hc-adv__cov-dot--partial { background: var(--ui-warning, var(--ui-orange, currentColor)); }\r\n.hc-adv__cov-dot--risk { background: var(--ui-warning, var(--ui-orange, currentColor)); }\r\n.hc-adv__cov-name { font-size: var(--fs-md); font-weight: 600; color: var(--ui-text-primary, inherit); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; min-width: 0; }\r\n.hc-adv__cov-facts { grid-area: facts; display: flex; flex-wrap: wrap; align-items: center; gap: var(--s2); min-width: 0; font-size: var(--fs-xs); color: var(--ui-text-tertiary, inherit); }\r\n.hc-adv__cov-fact + .hc-adv__cov-fact::before { content: '·'; margin-right: var(--s2); color: var(--ui-text-quaternary, inherit); }\r\n.hc-adv__cov-side { grid-area: side; display: flex; align-items: center; gap: var(--s2); flex: 0 0 auto; }\r\n.hc-adv__cov-primary { flex: 0 0 auto; }\r\n.hc-adv__cov-running { font-size: var(--fs-xs); color: var(--ui-warning, var(--ui-orange, inherit)); white-space: nowrap; }\r\n.hc-adv__cov-expand {\r\n  display: inline-flex; align-items: center; justify-content: center;\r\n  width: 26px; height: 26px; flex: 0 0 auto;\r\n  border: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  border-radius: var(--r-sm); background: none; cursor: pointer;\r\n  font: inherit; font-size: var(--fs-xs); color: var(--ui-text-secondary, inherit);\r\n}\r\n.hc-adv__cov-expand:hover { border-color: var(--ui-accent, currentColor); color: var(--ui-text-primary, inherit); }\r\n\r\n/* ------------------------------------------------------------- 展开区（整卡下方） */\r\n.hc-adv__cov-body {\r\n  grid-column: 1 / -1;\r\n  display: flex; flex-direction: column; gap: var(--s3);\r\n  padding-top: var(--s2);\r\n  border-top: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  min-width: 0;\r\n}\r\n.hc-adv__cov-section { display: flex; flex-direction: column; gap: var(--s2); min-width: 0; }\r\n.hc-adv__cov-sec-title { font-size: var(--fs-xs); font-weight: 600; color: var(--ui-text-quaternary, inherit); }\r\n\r\n/* 权限开关：左「开/关」按钮 + 右侧标签与一句说明 */\r\n.hc-adv__cov-switch { display: grid; grid-template-columns: auto minmax(0, 1fr); align-items: center; gap: var(--s2); min-width: 0; }\r\n.hc-adv__cov-toggle { min-width: 40px; padding: 0 var(--s2); border: var(--hairline) solid var(--ui-stroke-secondary, currentColor); border-radius: var(--r-sm); background: none; font: inherit; font-size: var(--fs-xs); color: var(--ui-text-quaternary, inherit); cursor: pointer; }\r\n.hc-adv__cov-toggle--on { border-color: var(--ui-accent, currentColor); color: var(--ui-accent, inherit); }\r\n.hc-adv__cov-toggle:hover { color: var(--ui-text-primary, inherit); }\r\n.hc-adv__cov-toggle:disabled { opacity: .45; cursor: not-allowed; border-color: var(--ui-stroke-secondary, currentColor); color: var(--ui-text-quaternary, inherit); }\r\n.hc-adv__cov-switch-text { display: flex; flex-direction: column; gap: var(--s2); min-width: 0; }\r\n.hc-adv__cov-switch-label { font-size: var(--fs-sm); color: var(--ui-text-primary, inherit); }\r\n.hc-adv__cov-switch-hint { font-size: var(--fs-xs); color: var(--ui-text-quaternary, inherit); }\r\n\r\n/* 次级动作：次操作走描边；危险项只用红字、无底色 */\r\n.hc-adv__cov-ops { display: flex; flex-wrap: wrap; gap: var(--s2); }\r\n/* 危险项不再带描边：描边是「次操作」的语汇，给危险项也描边两者就同质了（老板说的「看不出来」）。\r\n   只留红字 + hover 时极淡底，扫视时一眼区分「能点的常规操作 / 危险操作」。 */\r\n.hc-adv__cov-ops .hc-btn--danger { border-color: transparent; background: none; }\r\n\r\n/* 就地面板：在被操作卡片**下方**展开，绝不覆盖被操作的行 */\r\n.hc-adv__cov-panel {\r\n  display: flex; flex-direction: column; gap: var(--s2);\r\n  padding: var(--s3);\r\n  border: var(--hairline) solid var(--ui-accent, currentColor);\r\n  border-radius: var(--r-sm);\r\n  background: var(--ui-bg-primary, transparent);\r\n  min-width: 0;\r\n}\r\n\r\n/* 二次确认框 */\r\n.hc-adv__modal-mask { position: fixed; inset: 0; display: flex; align-items: center; justify-content: center; padding: var(--s4); background: color-mix(in srgb, var(--ui-text-primary, CanvasText) 55%, transparent); z-index: 50; }\r\n.hc-adv__modal { display: flex; flex-direction: column; gap: var(--s3); width: min(720px, 100%); max-height: 85vh; overflow: auto; padding: var(--s4); border: var(--hairline) solid var(--ui-stroke-secondary, currentColor); border-radius: var(--r-md); background: var(--ui-bg-primary, Canvas); }\r\n.hc-adv__modal-title { font-size: var(--fs-md); font-weight: 600; color: var(--ui-text-primary, inherit); }\r\n.hc-adv__modal-body { display: flex; flex-direction: column; gap: var(--s2); min-width: 0; }\r\n.hc-adv__modal-sec { font-size: var(--fs-sm); font-weight: 600; color: var(--ui-text-secondary, inherit); margin-top: var(--s2); }\r\n.hc-adv__modal-list { margin: 0; padding-left: var(--s4); font-size: var(--fs-xs); color: var(--ui-text-secondary, inherit); overflow-wrap: anywhere; }\r\n.hc-adv__modal-actions { display: flex; justify-content: flex-end; gap: var(--s2); }\r\n\r\n/* AgentStrip 真表格 */\r\n.hc-adv__agent-table { display: flex; flex-direction: column; min-width: 0; border: var(--hairline) solid var(--ui-stroke-secondary, currentColor); border-radius: var(--r-sm); overflow: hidden; }\r\n.hc-adv__agent-row { display: grid; grid-template-columns: minmax(90px, 1fr) minmax(90px, 1fr) 70px minmax(160px, 1.6fr); gap: var(--s2); align-items: baseline; padding: var(--s1) var(--s3); border-top: var(--hairline) solid var(--ui-stroke-secondary, currentColor); font-size: var(--fs-sm); color: var(--ui-text-secondary, inherit); min-width: 0; }\r\n.hc-adv__agent-row--head { border-top: none; background: var(--ui-bg-tertiary, transparent); font-size: var(--fs-xs); color: var(--ui-text-quaternary, inherit); }\r\n.hc-adv__agent-row > span { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }\r\n\r\n/* 评审流水迷你表格 */\r\n.hc-adv__mini-table { display: flex; flex-direction: column; min-width: 0; }\r\n.hc-adv__mini-row { display: grid; grid-template-columns: minmax(120px, 1fr) minmax(80px, .8fr) minmax(90px, 1fr) minmax(140px, 1.6fr); gap: var(--s2); align-items: baseline; padding: 2px 0; font-size: var(--fs-xs); color: var(--ui-text-secondary, inherit); min-width: 0; }\r\n.hc-adv__mini-row--head { color: var(--ui-text-quaternary, inherit); border-bottom: var(--hairline) solid var(--ui-stroke-secondary, currentColor); }\r\n.hc-adv__mini-row > span { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }\r\n\r\n/* 状态徽标：纯色文字 + 极淡底色，不再是带边框灰底（扫视时与按钮区分开） */\r\n.hc-adv__cov-badge { display: inline-block; padding: 0 var(--s2); border: none; border-radius: var(--r-sm); font-size: var(--fs-xs); white-space: nowrap; color: var(--ui-text-secondary, inherit); background: var(--ui-bg-tertiary, transparent); }\r\n.hc-adv__cov-badge--active { color: var(--ui-accent, inherit); }\r\n.hc-adv__cov-badge--reviewing_only, .hc-adv__cov-badge--ledger_no_delivery { color: var(--ui-warning, var(--ui-orange, inherit)); }\r\n.hc-adv__cov-badge--installed_disabled, .hc-adv__cov-badge--not_installed { color: var(--ui-text-quaternary, inherit); }\r\n\r\n/* 窄容器：卡片本来就是单列，只需把右侧主操作挪到第二行，避免挤压 */\r\n@container hc (max-width: 899px) {\r\n  .hc-adv__cov-card { grid-template-columns: minmax(0, 1fr); grid-template-areas: 'head' 'facts' 'side'; }\r\n  .hc-adv__cov-side { justify-content: flex-start; }\r\n  .hc-adv__agent-row, .hc-adv__mini-row { grid-template-columns: minmax(0, 1fr); }\r\n}\r\n\r\n/* ===========================================================================\r\n * Advisor 版面收敛（t_22813006）：唯一 Agent 选择器 / 折叠诊断 / 紧凑覆盖矩阵 /\r\n * 一张设置表单 + 底部固定提交 / 技术详情与帮助默认收起。\r\n *\r\n * 视觉规则沿用上文：颜色只走 var(--ui-*)；状态不只靠颜色（形状 + 文字双通道）；\r\n * 任何一档都不出现横向滚动条；卡只用 1px stroke，无阴影。\r\n * =========================================================================== */\r\n\r\n/* --------------------------------------------------- 唯一的 Agent 作用域选择器 */\r\n\r\n.hc-adv__scope {\r\n  display: flex;\r\n  align-items: center;\r\n  flex-wrap: wrap;\r\n  gap: var(--s2) var(--s3);\r\n  min-width: 0;\r\n  padding: var(--s2) var(--s3);\r\n  border: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  border-radius: var(--r-md);\r\n  background: var(--ui-bg-secondary, transparent);\r\n}\r\n\r\n.hc-adv__scope-pick {\r\n  display: inline-flex;\r\n  align-items: center;\r\n  gap: var(--s2);\r\n  flex: 0 0 auto;\r\n  min-width: 0;\r\n}\r\n\r\n.hc-adv__scope-label {\r\n  font-size: var(--fs-xs);\r\n  font-weight: 600;\r\n  color: var(--ui-text-quaternary, inherit);\r\n  white-space: nowrap;\r\n}\r\n\r\n.hc-adv__scope-pick .hc-select {\r\n  min-width: 148px;\r\n}\r\n\r\n.hc-adv__scope-facts {\r\n  display: flex;\r\n  align-items: center;\r\n  flex-wrap: wrap;\r\n  gap: var(--s1) var(--s2);\r\n  min-width: 0;\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-quaternary, inherit);\r\n}\r\n\r\n.hc-adv__scope-fact {\r\n  padding: 0 var(--s2);\r\n  border-radius: var(--r-sm);\r\n  background: var(--ui-bg-tertiary, transparent);\r\n  color: var(--ui-text-tertiary, inherit);\r\n  white-space: nowrap;\r\n}\r\n\r\n.hc-adv__scope-fact--warn {\r\n  color: var(--ui-warning, var(--ui-orange, inherit));\r\n}\r\n\r\n.hc-adv__scope-hint {\r\n  min-width: 0;\r\n  overflow-wrap: anywhere;\r\n  color: var(--ui-text-quaternary, inherit);\r\n}\r\n\r\n/* --------------------------------------------------------- 折叠诊断（一行摘要） */\r\n\r\n.hc-adv__diag {\r\n  min-width: 0;\r\n  border: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  border-radius: var(--r-md);\r\n  background: var(--ui-bg-secondary, transparent);\r\n}\r\n\r\n.hc-adv__diag[data-adv-diagnostics='warn'] {\r\n  border-color: var(--ui-warning, var(--ui-orange, currentColor));\r\n}\r\n\r\n.hc-adv__diag-sum {\r\n  display: flex;\r\n  align-items: center;\r\n  flex-wrap: wrap;\r\n  gap: var(--s1) var(--s2);\r\n  padding: var(--s2) var(--s3);\r\n  cursor: pointer;\r\n  list-style: none;\r\n  font-size: var(--fs-sm);\r\n  color: var(--ui-text-secondary, inherit);\r\n  min-width: 0;\r\n}\r\n\r\n.hc-adv__diag-sum::-webkit-details-marker {\r\n  display: none;\r\n}\r\n\r\n.hc-adv__diag-sum::after {\r\n  content: '▾';\r\n  margin-left: auto;\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-quaternary, inherit);\r\n}\r\n\r\n.hc-adv__diag[open] > .hc-adv__diag-sum::after {\r\n  content: '▴';\r\n}\r\n\r\n.hc-adv__diag-title {\r\n  font-weight: 600;\r\n  color: var(--ui-text-primary, inherit);\r\n}\r\n\r\n.hc-adv__diag-chip {\r\n  padding: 0 var(--s2);\r\n  border-radius: var(--r-sm);\r\n  font-size: var(--fs-xs);\r\n  white-space: nowrap;\r\n}\r\n\r\n.hc-adv__diag-chip--muted {\r\n  color: var(--ui-text-quaternary, inherit);\r\n  background: var(--ui-bg-tertiary, transparent);\r\n}\r\n\r\n.hc-adv__diag-chip--ok {\r\n  color: var(--ui-accent, inherit);\r\n  background: var(--ui-bg-tertiary, transparent);\r\n}\r\n\r\n.hc-adv__diag-chip--warn {\r\n  color: var(--ui-warning, var(--ui-orange, inherit));\r\n  background: var(--ui-bg-tertiary, transparent);\r\n}\r\n\r\n.hc-adv__diag-body {\r\n  padding: var(--s3);\r\n  border-top: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  min-width: 0;\r\n}\r\n\r\n/* ---------------------------------------------------- 覆盖状态条（压成一行） */\r\n\r\n.hc-adv__cov-strip {\r\n  display: flex;\r\n  align-items: stretch;\r\n  flex-wrap: wrap;\r\n  gap: 0;\r\n  border: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  border-radius: var(--r-md);\r\n  overflow: hidden;\r\n  min-width: 0;\r\n}\r\n\r\n.hc-adv__cov-cell {\r\n  display: flex;\r\n  align-items: baseline;\r\n  gap: var(--s1);\r\n  flex: 1 1 0;\r\n  min-width: 0;\r\n  padding: var(--s1) var(--s2);\r\n  border-left: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-tertiary, inherit);\r\n}\r\n\r\n.hc-adv__cov-cell:first-child {\r\n  border-left: none;\r\n}\r\n\r\n.hc-adv__cov-cell--zero {\r\n  color: var(--ui-text-quaternary, inherit);\r\n  opacity: 0.7;\r\n}\r\n\r\n.hc-adv__cov-cell .hc-adv__cov-num {\r\n  font-size: var(--fs-sm);\r\n  font-weight: 600;\r\n  font-variant-numeric: tabular-nums;\r\n  color: var(--ui-text-primary, inherit);\r\n}\r\n\r\n.hc-adv__cov-cell--active .hc-adv__cov-num {\r\n  color: var(--ui-accent, inherit);\r\n}\r\n\r\n.hc-adv__cov-cell--reviewing_only .hc-adv__cov-num,\r\n.hc-adv__cov-cell--ledger_no_delivery .hc-adv__cov-num {\r\n  color: var(--ui-warning, var(--ui-orange, inherit));\r\n}\r\n\r\n.hc-adv__cov-cell .hc-adv__cov-label {\r\n  overflow: hidden;\r\n  text-overflow: ellipsis;\r\n  white-space: nowrap;\r\n  min-width: 0;\r\n}\r\n\r\n/* -------------------------------------------------- 覆盖矩阵：一行一个 agent */\r\n\r\n.hc-adv__cov-cards {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 0;\r\n  min-width: 0;\r\n  border: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  border-radius: var(--r-md);\r\n  overflow: hidden;\r\n}\r\n\r\n.hc-adv__cov-card {\r\n  position: relative;\r\n  display: flex;\r\n  flex-direction: column;\r\n  min-width: 0;\r\n  /* 覆盖上文那张 88px 高的卡片规则：收起态的高度只由这一行内容决定 */\r\n  min-height: 0;\r\n  height: auto;\r\n  /* 上面那条 grid 版规则留了 `align-items: center`；这里是列向 flex，center 会让每行\r\n     收缩成内容宽度 → 操作按钮逐行左右跳（实测右缘 884/934/992/1045 四个位置）。\r\n     必须 stretch，行的右缘才齐。 */\r\n  align-items: stretch;\r\n  align-content: normal;\r\n  padding: 0;\r\n  border-top: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  background: none;\r\n}\r\n\r\n/* 收起的 <details> 必须真的不占位：Chrome 的 UA 规则是 `details:not([open]) > *` 不渲染，\r\n   但**作者 CSS 一旦给子元素设了 display（如 .hc-adv__modeguide-body{display:flex}）就失效**，\r\n   于是「收起」只是看不见、仍占几百像素高度。这里显式关掉，折叠才是真折叠。 */\r\n.hc-adv__diag:not([open]) > .hc-adv__diag-body,\r\n.hc-adv__modeguide:not([open]) > .hc-adv__modeguide-body,\r\n.hc-adv__tech:not([open]) > .hc-adv__tech-body,\r\n.hc-adv__help:not([open]) > .hc-adv__help-body,\r\n.hc-adv__ledger:not([open]) > .hc-adv__agent-table,\r\n.hc-adv__ledger:not([open]) > .hc-adv__notes,\r\n.hc-adv__modeguide:not([open]) .hc-adv__mode-evidence:not([open]) > .hc-adv__mode-ev-body {\r\n  display: none;\r\n}\r\n\r\n.hc-adv__cov-card:first-child {\r\n  border-top: none;\r\n}\r\n\r\n.hc-adv__cov-card--selected {\r\n  background: var(--ui-bg-tertiary, transparent);\r\n}\r\n\r\n/* 「当前选中」的左侧强调条：用伪元素画一根 2px 竖线（本仓库的样式不变量是\r\n   「卡片靠 stroke 立起来，不加阴影」，所以不用 inset 阴影做强调）。 */\r\n.hc-adv__cov-card--selected::before {\r\n  content: '';\r\n  position: absolute;\r\n  left: 0;\r\n  top: 0;\r\n  bottom: 0;\r\n  width: 2px;\r\n  background: var(--ui-accent, currentColor);\r\n}\r\n\r\n.hc-adv__cov-card--open {\r\n  background: var(--ui-bg-tertiary, transparent);\r\n}\r\n\r\n/* 收起态就是**一行**：名字 / 徽标 / 事实 / 主操作 / 箭头。高度由行内容决定（~36px），\r\n   不再靠 min-height 撑到 88px —— 9 个 agent 排下来是一张紧凑清单，不是九张卡片。 */\r\n.hc-adv__cov-card-head {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: var(--s2);\r\n  min-width: 0;\r\n  padding: var(--s1) var(--s3);\r\n  min-height: 36px;\r\n}\r\n\r\n.hc-adv__cov-name {\r\n  font-size: var(--fs-sm);\r\n  font-weight: 600;\r\n  color: var(--ui-text-primary, inherit);\r\n  overflow: hidden;\r\n  text-overflow: ellipsis;\r\n  white-space: nowrap;\r\n  min-width: 0;\r\n  flex: 0 0 auto;\r\n  max-width: 180px;\r\n}\r\n\r\n.hc-adv__cov-card-head .hc-adv__cov-badge {\r\n  flex: 0 0 auto;\r\n}\r\n\r\n.hc-adv__cov-card-head .hc-adv__cov-facts {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: var(--s2);\r\n  flex: 1 1 auto;\r\n  min-width: 0;\r\n  overflow: hidden;\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-quaternary, inherit);\r\n  white-space: nowrap;\r\n}\r\n\r\n.hc-adv__cov-card-head .hc-adv__cov-side {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: var(--s2);\r\n  flex: 0 0 auto;\r\n}\r\n\r\n/* 展开区：贴在该行下方，一块浅底，四个维度分两栏（窄窗一栏） */\r\n.hc-adv__cov-body {\r\n  display: grid;\r\n  grid-template-columns: minmax(0, 1fr);\r\n  gap: var(--s3);\r\n  padding: var(--s3);\r\n  border-top: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  background: var(--ui-bg-secondary, transparent);\r\n  min-width: 0;\r\n}\r\n\r\n@container hc (min-width: 1000px) {\r\n  .hc-adv__cov-body {\r\n    grid-template-columns: minmax(0, 1.15fr) minmax(0, 1fr);\r\n  }\r\n\r\n  .hc-adv__cov-body > .hc-adv__cov-detail,\r\n  .hc-adv__cov-body > .hc-adv__cov-panel {\r\n    grid-column: 1 / -1;\r\n  }\r\n}\r\n\r\n/* ------------------------------------------------------ 设置：一张表单 */\r\n\r\n.hc-adv__settings {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s3);\r\n  min-width: 0;\r\n  padding: var(--s4);\r\n  border: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  border-radius: var(--r-md);\r\n  background: var(--ui-bg-secondary, transparent);\r\n}\r\n\r\n.hc-adv__settings--idle {\r\n  color: var(--ui-text-quaternary, inherit);\r\n}\r\n\r\n.hc-adv__form {\r\n  display: flex;\r\n  flex-direction: column;\r\n  min-width: 0;\r\n  border: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  border-radius: var(--r-md);\r\n  overflow: hidden;\r\n}\r\n\r\n/* 一行一项：标签 / 唯一控件 / 只读读数 + 来源 chip */\r\n.hc-adv__srow {\r\n  display: grid;\r\n  grid-template-columns: minmax(104px, 148px) minmax(0, 1fr) auto;\r\n  align-items: center;\r\n  gap: var(--s2) var(--s3);\r\n  min-width: 0;\r\n  padding: var(--s2) var(--s3);\r\n  border-top: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n}\r\n\r\n.hc-adv__srow:first-child {\r\n  border-top: none;\r\n}\r\n\r\n.hc-adv__srow:hover {\r\n  background: var(--ui-bg-tertiary, transparent);\r\n}\r\n\r\n.hc-adv__srow-label {\r\n  font-size: var(--fs-sm);\r\n  color: var(--ui-text-secondary, inherit);\r\n  min-width: 0;\r\n  overflow-wrap: anywhere;\r\n}\r\n\r\n.hc-adv__srow-control {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: var(--s2);\r\n  flex-wrap: wrap;\r\n  min-width: 0;\r\n}\r\n\r\n.hc-adv__srow-control .hc-select {\r\n  min-width: 160px;\r\n  max-width: 280px;\r\n}\r\n\r\n.hc-adv__srow-control .hc-adv__input {\r\n  flex: 0 1 120px;\r\n  width: 120px;\r\n}\r\n\r\n.hc-adv__srow-meta {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: var(--s2);\r\n  flex-wrap: wrap;\r\n  justify-content: flex-end;\r\n  min-width: 0;\r\n}\r\n\r\n.hc-adv__srow-read {\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-quaternary, inherit);\r\n  font-variant-numeric: tabular-nums;\r\n  white-space: nowrap;\r\n}\r\n\r\n.hc-adv__srow-read--accent {\r\n  color: var(--ui-accent, inherit);\r\n}\r\n\r\n.hc-adv__srow-read--warn {\r\n  color: var(--ui-warning, var(--ui-orange, inherit));\r\n}\r\n\r\n.hc-adv__srow-read--pending {\r\n  color: var(--ui-warning, var(--ui-orange, inherit));\r\n  font-weight: 600;\r\n}\r\n\r\n/* 来源 chip：形状承担语义（实线=文件里写了 / 点线=默认值），不单靠颜色 */\r\n.hc-adv__srcchip {\r\n  padding: 0 var(--s2);\r\n  border: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  border-radius: var(--r-sm);\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-quaternary, inherit);\r\n  white-space: nowrap;\r\n  font-family: var(--ui-font-mono, monospace);\r\n}\r\n\r\n.hc-adv__srcchip--settings_file {\r\n  border-color: var(--ui-accent, currentColor);\r\n  color: var(--ui-accent, inherit);\r\n}\r\n\r\n.hc-adv__srcchip--default {\r\n  border-style: dotted;\r\n}\r\n\r\n.hc-adv__srcchip--forced_constant {\r\n  border-style: dashed;\r\n  color: var(--ui-warning, var(--ui-orange, inherit));\r\n}\r\n\r\n/* 复选框开关：原生 input + 文字双通道 */\r\n.hc-adv__switch {\r\n  display: inline-flex;\r\n  align-items: center;\r\n  gap: var(--s2);\r\n  min-width: 0;\r\n  cursor: pointer;\r\n}\r\n\r\n.hc-adv__switch-text {\r\n  font-size: var(--fs-sm);\r\n  color: var(--ui-text-primary, inherit);\r\n}\r\n\r\n/* 设置区里的模型选择器：不要撑满整行，来源说明单独一行小字 */\r\n.hc-adv__srow--wide .hc-adv__srow-control {\r\n  flex-direction: column;\r\n  align-items: stretch;\r\n  gap: var(--s1);\r\n}\r\n\r\n.hc-adv__pair {\r\n  min-width: 0;\r\n  overflow-wrap: anywhere;\r\n}\r\n\r\n/* 提交动作固定在表单底部：一条分隔线 + 右对齐按钮，上面是待保存内容 */\r\n.hc-adv__form-actions {\r\n  display: flex;\r\n  align-items: center;\r\n  flex-wrap: wrap;\r\n  gap: var(--s2);\r\n  justify-content: flex-end;\r\n  min-width: 0;\r\n  padding: var(--s2) var(--s3);\r\n  border-top: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  background: var(--ui-bg-tertiary, transparent);\r\n}\r\n\r\n.hc-adv__form-note {\r\n  margin-right: auto;\r\n  min-width: 0;\r\n  overflow-wrap: anywhere;\r\n}\r\n\r\n/* ------------------------------------ 技术详情 / 帮助 / 模式说明：默认收起 */\r\n\r\n.hc-adv__tech,\r\n.hc-adv__help,\r\n.hc-adv__modeguide,\r\n.hc-adv__ledger {\r\n  min-width: 0;\r\n  border: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  border-radius: var(--r-sm);\r\n}\r\n\r\n.hc-adv__tech > summary,\r\n.hc-adv__help > summary,\r\n.hc-adv__modeguide > summary,\r\n.hc-adv__ledger > summary,\r\n.hc-adv__modeguide-sum {\r\n  display: flex;\r\n  align-items: baseline;\r\n  gap: var(--s2);\r\n  padding: var(--s1) var(--s3);\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-quaternary, inherit);\r\n  cursor: pointer;\r\n  list-style: none;\r\n  min-width: 0;\r\n  overflow-wrap: anywhere;\r\n}\r\n\r\n.hc-adv__tech > summary::-webkit-details-marker,\r\n.hc-adv__help > summary::-webkit-details-marker,\r\n.hc-adv__modeguide > summary::-webkit-details-marker,\r\n.hc-adv__ledger > summary::-webkit-details-marker {\r\n  display: none;\r\n}\r\n\r\n.hc-adv__tech > summary::before,\r\n.hc-adv__help > summary::before,\r\n.hc-adv__modeguide > summary::before,\r\n.hc-adv__ledger > summary::before {\r\n  content: '▸';\r\n  flex: 0 0 auto;\r\n  color: var(--ui-text-quaternary, inherit);\r\n}\r\n\r\n.hc-adv__tech[open] > summary::before,\r\n.hc-adv__help[open] > summary::before,\r\n.hc-adv__modeguide[open] > summary::before,\r\n.hc-adv__ledger[open] > summary::before {\r\n  content: '▾';\r\n}\r\n\r\n.hc-adv__tech-body,\r\n.hc-adv__help-body,\r\n.hc-adv__modeguide-body,\r\n.hc-adv__ledger > .hc-adv__agent-table {\r\n  padding: var(--s2) var(--s3) var(--s3);\r\n  min-width: 0;\r\n}\r\n\r\n.hc-adv__modeguide-body {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s2);\r\n}\r\n\r\n/* 模式说明表：三列（名字 / 什么时候生效 / 判据），窄窗塌成一列 */\r\n.hc-adv__mode-row {\r\n  grid-template-columns: minmax(96px, 0.7fr) minmax(120px, 1fr) minmax(0, 2fr);\r\n}\r\n\r\n/* 窄容器：设置行塌成两行（标签 + 控件，读数换行），矩阵事实行换行显示 */\r\n@container hc (max-width: 899px) {\r\n  .hc-adv__srow {\r\n    grid-template-columns: minmax(0, 1fr);\r\n    gap: var(--s1);\r\n  }\r\n\r\n  .hc-adv__srow-meta {\r\n    justify-content: flex-start;\r\n  }\r\n\r\n  .hc-adv__cov-card-head {\r\n    flex-wrap: wrap;\r\n  }\r\n\r\n  .hc-adv__cov-card-head .hc-adv__cov-facts {\r\n    flex: 1 1 100%;\r\n    order: 3;\r\n    white-space: normal;\r\n  }\r\n\r\n  .hc-adv__cov-cell {\r\n    flex: 1 1 40%;\r\n  }\r\n}\r\n\r\n/* 覆盖口径 / 后端附注：现在和「每个 agent 的计件」共用一个 <details class=\"hc-adv__ledger\">，\r\n   样式走上面那组（.hc-adv__ledger）。原来独立的 .hc-adv__notes-fold 已随之删除。 */\r\n\r\n/* ===========================================================================\r\n * 执行 Lane（只读心跳面板）\r\n *\r\n * 结构：.hc-lane-root = 标题行 + .hc-lanes（每条 lane 一张 .hc-lane 卡）。\r\n * 状态色只做辅助（左边框 + 小圆点），**文字是主通道**（在线 / 心跳停滞 / 离线 / 未知），\r\n * 所以黑白打印或色盲用户都不丢信息。颜色全部走 var(--ui-*)，没有字面色值；\r\n * 卡片只用 1px stroke，无阴影。本面板没有任何按钮。\r\n * =========================================================================== */\r\n\r\n.hc-lane-root {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s4);\r\n  min-width: 0;\r\n}\r\n\r\n.hc-lanes {\r\n  display: grid;\r\n  grid-template-columns: minmax(0, 1fr);\r\n  gap: var(--s4);\r\n}\r\n\r\n@container hc (min-width: 1200px) {\r\n  .hc-lanes {\r\n    grid-template-columns: repeat(2, minmax(0, 1fr));\r\n  }\r\n}\r\n\r\n.hc-lane {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s3);\r\n  min-width: 0;\r\n  padding: var(--s4);\r\n  border: var(--hairline) solid var(--ui-stroke-secondary, currentColor);\r\n  border-left: 3px solid var(--ui-text-quaternary, currentColor);\r\n  border-radius: var(--r-md);\r\n  background: var(--ui-bg-secondary, transparent);\r\n}\r\n\r\n.hc-lane--online {\r\n  border-left-color: var(--ui-accent, currentColor);\r\n}\r\n\r\n.hc-lane--stalled {\r\n  border-left-color: var(--ui-warning, var(--ui-orange, currentColor));\r\n}\r\n\r\n.hc-lane--offline {\r\n  border-left-color: var(--ui-danger, var(--ui-red, currentColor));\r\n}\r\n\r\n.hc-lane__head {\r\n  display: flex;\r\n  align-items: center;\r\n  flex-wrap: wrap;\r\n  gap: var(--s2);\r\n  min-width: 0;\r\n}\r\n\r\n/* 色点：纯辅助，aria-hidden；旁边一定有状态文字 */\r\n.hc-lane__dot {\r\n  width: 8px;\r\n  height: 8px;\r\n  border-radius: 999px;\r\n  flex: none;\r\n  background: var(--ui-text-quaternary, currentColor);\r\n}\r\n\r\n.hc-lane--online .hc-lane__dot {\r\n  background: var(--ui-accent, currentColor);\r\n}\r\n\r\n.hc-lane--stalled .hc-lane__dot {\r\n  background: var(--ui-warning, var(--ui-orange, currentColor));\r\n}\r\n\r\n.hc-lane--offline .hc-lane__dot {\r\n  background: var(--ui-danger, var(--ui-red, currentColor));\r\n}\r\n\r\n.hc-lane__name {\r\n  font-size: var(--fs-md);\r\n  font-weight: 600;\r\n  margin: 0;\r\n  min-width: 0;\r\n  overflow-wrap: anywhere;\r\n}\r\n\r\n.hc-lane__status {\r\n  font-size: var(--fs-sm);\r\n  color: var(--ui-text-secondary, inherit);\r\n  white-space: nowrap;\r\n}\r\n\r\n.hc-lane__rows {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: var(--s1);\r\n  min-width: 0;\r\n}\r\n\r\n.hc-lane__row {\r\n  display: flex;\r\n  align-items: baseline;\r\n  gap: var(--s2);\r\n  min-width: 0;\r\n  font-size: var(--fs-sm);\r\n}\r\n\r\n.hc-lane__key {\r\n  flex: none;\r\n  width: 72px;\r\n  color: var(--ui-text-quaternary, inherit);\r\n}\r\n\r\n.hc-lane__val {\r\n  min-width: 0;\r\n  color: var(--ui-text-secondary, inherit);\r\n  overflow-wrap: anywhere;\r\n}\r\n\r\n/* 心跳坏掉时的原话：等宽、换行，不截断 */\r\n.hc-lane__error {\r\n  padding: var(--s2);\r\n  border: var(--hairline) dashed var(--ui-warning, var(--ui-orange, currentColor));\r\n  border-radius: var(--r-sm);\r\n  font-family: var(--ui-font-mono, monospace);\r\n  font-size: var(--fs-xs);\r\n  color: var(--ui-text-secondary, inherit);\r\n  overflow-wrap: anywhere;\r\n}\r\n\r\n";

// src/tokens.css
var tokens_default = "/*\n * hermes-console · 设计 tokens（唯一尺寸来源）\n *\n * 这里只放与主题无关的**尺寸**：间距、字号、圆角、布局常量。\n * 颜色一律不在这里定义，也不在别处定义 —— 所有颜色都是宿主主题变量\n * `var(--ui-*)` 的直接引用（见 style.css 顶部规则）。宿主切深浅主题时\n * `--ui-*` 由宿主自己改写，因此本插件不需要、也不允许写 data-theme 分支。\n *\n * 作用域挂在 `.hc-root`（不是 `:root`）：`--s1/--fs-md/--r-md` 这种通用名\n * 放在全局会污染宿主和其它插件；挂在外壳根节点上由后代继承即可。\n */\n.hc-root {\n  /* 间距：4/8 栅格 */\n  --s1: 4px;\n  --s2: 8px;\n  --s3: 12px;\n  --s4: 16px;\n  --s5: 20px;\n  --s6: 24px;\n  --s7: 28px;\n  --s8: 32px;\n\n  /* 字号 */\n  --fs-xs: 11px;\n  --fs-sm: 12px;\n  --fs-md: 13px;\n  --fs-lg: 15px;\n  --fs-xl: 20px;\n\n  /* 圆角 */\n  --r-sm: 6px;\n  --r-md: 10px;\n  --r-lg: 14px;\n\n  /* 布局常量 */\n  --nav-w: 180px;\n  --nav-w-narrow: 56px;\n  --row-h: 34px;\n  --hairline: 1px;\n  --nav-mark: 2px;\n\n  /* 动效只有两种用途：hover/选中态过渡（120ms）与骨架屏呼吸（1.8s） */\n  --t-fast: 120ms ease;\n}\n";

// src/lib/style-inject.js
var STYLE_ATTR = "data-hermes-console-style";
var AT_IMPORT = /@import[^;]*;/g;
var TOKEN_DEF = /(-{2}[A-Za-z0-9_-]+)\s*:\s*([^;{}]+);/g;
var TOKEN_USE = /var\((--[A-Za-z0-9_-]+)\)/g;
var bundled = "";
function readTokens(text) {
  var values = {};
  var m;
  TOKEN_DEF.lastIndex = 0;
  while ((m = TOKEN_DEF.exec(text)) !== null) values[m[1]] = m[2].trim();
  return values;
}
function expandTokens(text, values) {
  return text.replace(TOKEN_USE, function(whole, name) {
    var value = values[name];
    return value === void 0 ? whole : value;
  });
}
function consoleStyleText() {
  if (!bundled) {
    var values = readTokens(tokens_default);
    bundled = tokens_default + "\n" + // 替换文本里**不能出现 @import 字样**（哪怕是注释）：注释里的同一个字符串会让
    // 「产物里没有外链导入」这条验收 grep 变成假阳性。
    expandTokens(style_default.replace(AT_IMPORT, "/* tokens.css 已前置合并，外链导入已剥离 */"), values);
  }
  return bundled;
}
function injectConsoleStyles(css) {
  if (typeof document === "undefined") return null;
  var head = document.head;
  if (!head || typeof document.createElement !== "function") return null;
  var text = typeof css === "string" && css ? css : consoleStyleText();
  var existing = document.querySelectorAll("style[" + STYLE_ATTR + "]");
  var node = existing.length ? existing[0] : null;
  for (var i = 1; i < existing.length; i += 1) {
    if (existing[i].parentNode) existing[i].parentNode.removeChild(existing[i]);
  }
  if (node) {
    if (node.textContent !== text) node.textContent = text;
    return node;
  }
  node = document.createElement("style");
  node.setAttribute(STYLE_ATTR, "");
  node.textContent = text;
  head.appendChild(node);
  return node;
}

// src/main.js
var ID = "hermes-console";
var NAME = "控制台";
var TAB_PATH = "/console";
injectConsoleStyles();
var plugin = {
  id: ID,
  name: NAME,
  register(ctx) {
    bindRest(ctx);
    bindStorage(ctx);
    injectConsoleStyles();
    ctx.registerMany([
      {
        id: "page",
        area: "routes",
        data: { path: TAB_PATH },
        render: () => jsx20(ConsoleApp, {})
      },
      {
        id: "nav",
        area: "sidebar.nav",
        order: 60,
        data: { path: TAB_PATH, label: NAME, codicon: "dashboard" }
      }
    ]);
  }
};
var main_default = plugin;
export {
  STYLE_ATTR,
  main_default as default,
  injectConsoleStyles
};
